    return `${this._basePath}?lang=${encodeURIComponent(getLocale())}`;
  }

  // GET ohne Render: setzt this._cats aus der Server-Antwort. Wirft weiter,
  // damit der aufrufende Mutations-Handler (mit eigenem try/catch) selbst
  // entscheidet, welchen Ausschnitt er danach neu zeichnet.
  async _fetch() {
    const res = await api.get(this._listPath());
    this._cats = res.data ?? [];
  }

  // Voll-Load: Erstbefüllung (configure) und generischer Refresh — lädt und
  // baut die gesamte Komponente neu auf.
  async _load() {
    try {
      await this._fetch();
      this._render();
    } catch (err) {
      // BEWUSST NICHT `_fail`: das Laden darf sich nicht selbst wieder
      // anstossen, wenn es scheitert.
      window.yuvomi?.showToast(this._errMsg(err), 'danger');
    }
  }

  _inGroup(groupKey) {
    if (!groupKey) return this._cats;
    return this._cats.filter((c) => this._groupOf(c) === groupKey);
  }

  _groupOf(item) {
    return item?.[this._groupField] ?? item?.type ?? item?.group ?? '';
  }

  /* Stabiler Zeilen-Schlüssel: Budget/Tasks/Kontakte liefern `key`,
   * Einkauf numerische `id` (Audit F-15 — eine Komponente für alle vier). */
  _keyOf(item) {
    return String(item.key ?? item.id);
  }

  // Markup einer Gruppen-Sektion (cat-list + Add-Form; Sublists stecken in den
  // Zeilen via _rowHtml→_subListHtml). Geteilt von Voll- und Teil-Render.
  _groupSectionHtml(g) {
    const items = this._inGroup(g.key);
    return `
      <section class="cat-group" data-group="${esc(g.key)}">
        ${g.labelKey ? `<h4 class="cat-group__title">${esc(t(g.labelKey))}</h4>` : ''}
        <ul class="cat-list">
          ${items.map((c, i) => this._rowHtml(c, g, i === 0, i === items.length - 1)).join('')}
        </ul>
        ${this._unifiedAdd ? '' : `<form class="cat-add-form" data-group="${esc(g.key)}" novalidate autocomplete="off">
          <input class="form-input" type="text" maxlength="${this._addMaxLength}"
                 placeholder="${esc(t(this._addPlaceholderKey))}"
                 aria-label="${esc(t(this._addPlaceholderKey))}" />
          <button type="submit" class="btn btn--primary">${esc(t(g.addLabelKey || 'common.add'))}</button>
        </form>`}
      </section>`;
  }

  _unifiedAddFormHtml() {
    if (!this._unifiedAdd) return '';
    const hasScopeChoice = this._groups.length > 1;
    const help = hasScopeChoice && this._addScopeHelpKey
      ? `<button type="button" class="category-scope-help" aria-expanded="false" aria-label="${esc(t(this._addScopeHelpKey))}">
          <i data-lucide="info" aria-hidden="true"></i>
          <span class="category-scope-help__tooltip u-meta" id="cat-manager-scope-help" role="tooltip">${esc(t(this._addScopeHelpKey))}</span>
        </button>`
      : '';
    return `<form class="cat-add-form cat-add-form--unified" data-group="${esc(this._groups[0]?.key ?? '')}"
                  novalidate autocomplete="off">
      <input class="form-input" type="text" maxlength="${this._addMaxLength}"
             placeholder="${esc(t(this._addPlaceholderKey))}"
             aria-label="${esc(t(this._addPlaceholderKey))}" />
      ${hasScopeChoice ? `<div class="cat-add-form__scope">
        <select class="form-input" name="category-scope" aria-label="${esc(t(this._addScopeLabelKey))}"
                ${help ? 'aria-describedby="cat-manager-scope-help"' : ''}>
          ${this._groups.map((group) => `<option value="${esc(group.key)}">${esc(t(group.labelKey))}</option>`).join('')}
        </select>${help}
      </div>` : ''}
      <button type="submit" class="btn btn--primary">${esc(t(this._groups[0]?.addLabelKey || 'common.add'))}</button>
    </form>`;
  }

  // Läuft irgendwo ein Drag (z. B. eine zweite Zeile, die gezogen wird, während
  // der vorige Drag noch auf _persistOrder wartet)? Dann den Render bis zum
  // nächsten Frame verschieben, statt die aktive Sortable-Instanz mitten im Zug
  // zu zerstören und den laufenden Drag kommentarlos abzubrechen. Teil-Renderer
  // fallen in diesem seltenen Fall bewusst auf den (deferten) Voll-Render zurück.
  _deferForDrag() {
    if (!isDragActive()) return false;
    if (!this._renderDeferred) {
      this._renderDeferred = true;
      requestAnimationFrame(() => { this._renderDeferred = false; this._render(); });
    }
    return true;
  }

  // Voll-Render: baut alle Gruppen neu auf. Erstbefüllung + Fallback, wenn ein
  // Teil-Render sein Ziel nicht findet.
  _render() {
    if (!this._groupsEl) return;
    if (this._deferForDrag()) return;
    this._destroySortables();
    this._groupsEl.replaceChildren();
    this._groups.forEach((g) => {
      const tmp = document.createElement('div');
      tmp.insertAdjacentHTML('beforeend', this._groupSectionHtml(g));
      this._groupsEl.appendChild(tmp.firstElementChild);
    });
    this._groupsEl.insertAdjacentHTML('beforeend', this._unifiedAddFormHtml());
    this._wireScopeHelp();
    if (window.lucide) window.lucide.createIcons({ el: this._groupsEl });
    this._wireSortableIn(this._groupsEl);
  }

  _wireScopeHelp() {
    this._disposeScopeHelp?.();
    this._disposeScopeHelp = wireCategoryScopeHelp(this.closest?.('.modal-panel') || this._groupsEl);
  }

  // Teil-Render einer einzelnen Gruppe: baut nur deren Sektion (cat-list +
  // Add-Form + eigene Sublists) neu und verdrahtet ausschließlich deren
  // Sortable-Instanzen neu — andere Gruppen (samt Instanzen) bleiben unberührt.
  // Fällt bei laufendem Drag oder fehlender Sektion auf den Voll-Render zurück.
  _renderGroup(groupKey) {
    if (!this._groupsEl) return;
    if (this._deferForDrag()) return;
    const g = this._groups.find((gr) => gr.key === groupKey);
    const oldSection = this._groupsEl.querySelector(`.cat-group[data-group="${CSS.escape(groupKey ?? '')}"]`);
    if (!g || !oldSection) { this._render(); return; }
    this._destroySortablesIn(oldSection);
    const tmp = document.createElement('div');
    tmp.insertAdjacentHTML('beforeend', this._groupSectionHtml(g));
    const newSection = tmp.firstElementChild;
    oldSection.replaceWith(newSection);
    if (window.lucide) window.lucide.createIcons({ el: newSection });
    this._wireSortableIn(newSection);
  }

  // Teil-Render einer einzelnen Sublist: ersetzt nur die cat-sublist eines
  // Parents und verdrahtet deren Sub-Sortable neu; die cat-list-Instanz des
  // Parents bleibt bestehen (die Sublist ist Enkel der Liste, kein direktes
  // Listen-Kind). Fällt bei Drag oder fehlendem Ziel auf den Voll-Render zurück.
  _renderSublist(parentKey) {
    if (!this._groupsEl || !this._supportsSub) return;
    if (this._deferForDrag()) return;
    const cat = this._cats.find((c) => this._keyOf(c) === parentKey);
    const groupKey = cat ? this._groupOf(cat) : '';
    const g = this._groups.find((gr) => gr.key === groupKey);
    const row = this._groupsEl.querySelector(`.cat-row[data-key="${CSS.escape(parentKey ?? '')}"]`);
    if (!cat || !g || !row) { this._render(); return; }
    const oldSub = row.querySelector(`:scope > .cat-sublist[data-parent="${CSS.escape(parentKey ?? '')}"]`);
    const tmp = document.createElement('div');
    tmp.insertAdjacentHTML('beforeend', this._subListHtml(cat, g));
    const newSub = tmp.firstElementChild; // null, wenn die Gruppe keine Sublists führt
    if (oldSub) this._destroySortablesIn(oldSub);
    if (oldSub && newSub) oldSub.replaceWith(newSub);
    else if (oldSub) oldSub.remove();
    else if (newSub) row.appendChild(newSub);
    else return;
    if (newSub) {
      if (window.lucide) window.lucide.createIcons({ el: newSub });
      this._wireSortableIn(row);
    }
  }

  /* Drag ist nie der einzige Weg: die Auf/Ab-Buttons in _rowHtml/_subListHtml
   * bleiben der tastaturbedienbare Reorder-Pfad und rufen denselben
   * _persistOrder/_persistSubOrder-Handler wie das Drag-Ende auf.
   *
   * Scope-fähig: `root` ist beim Voll-Render der Groups-Container, beim
   * Teil-Render nur die neu gebaute Gruppen-Sektion bzw. Parent-Zeile — so
   * werden ausschließlich die Listen des neu gezeichneten Ausschnitts verdrahtet. */
  _wireSortableIn(root) {
    root.querySelectorAll('.cat-list').forEach((listEl) => {
      const groupKey = listEl.closest('.cat-group')?.dataset.group ?? '';
      makeSortable(listEl, {
        handle: '.cat-row__handle',
        onEnd: (evt) => {
          const movedKey = evt.item?.dataset.key;
          const orderedKeys = Array.from(listEl.children).map((el) => el.dataset.key);
          // Nur der Drag-Pfad hat das DOM schon optimistisch umgestellt (SortableJS
          // verschiebt vor dem PATCH); ein Fehler braucht daher hier einen
          // Rollback-Render. Der Button-Pfad (_move) mutiert das DOM nie vorab.
          this._persistOrder(groupKey, orderedKeys, movedKey, { rollbackRender: true });
        },
      }).then((instance) => this._trackSortable(instance, listEl)).catch((err) => this._warnDragUnavailable(err));
    });
    if (!this._supportsSub) return;
    root.querySelectorAll('.cat-sublist').forEach((subListEl) => {
      const parentKey = subListEl.dataset.parent;
      makeSortable(subListEl, {
        handle: '.cat-subrow__handle',
        draggable: '.cat-subrow',
        onEnd: (evt) => {
          const movedSubKey = evt.item?.dataset.subkey;
          const orderedSubKeys = Array.from(subListEl.children)
            .filter((el) => el.matches('.cat-subrow'))
            .map((el) => el.dataset.subkey);
          this._persistSubOrder(parentKey, orderedSubKeys, movedSubKey, { rollbackRender: true });
        },
      }).then((instance) => this._trackSortable(instance, subListEl)).catch((err) => this._warnDragUnavailable(err));
    });
  }

  // Instanzen einer inzwischen überholten _render()-Runde (Element schon aus
  // dem DOM entfernt, bevor der lazy SortableJS-Import fertig war) sofort
  // wieder freigeben statt sie in _sortables mitzuführen.
  _trackSortable(instance, el) {
    if (!instance) return;
    if (el.isConnected) this._sortables.push(instance);
    else instance.destroy();
  }

  _destroySortables() {
    this._sortables.forEach((s) => s?.destroy?.());
    this._sortables = [];
  }

  // Nur die Sortable-Instanzen freigeben, deren Liste (s.el) innerhalb von
  // `container` liegt — für Teil-Render, der andere Listen unangetastet lässt.
  // Vor dem DOM-Austausch aufrufen, solange s.el noch Nachfahre von container ist.
  _destroySortablesIn(container) {
    this._sortables = this._sortables.filter((s) => {
      if (s?.el && container.contains(s.el)) { s.destroy?.(); return false; }
      return true;
    });
  }

  // Nach einem erfolgreichen Button-Reorder den Fokus auf der bewegten Zeile
  // halten: der Teil-Render hat den geklickten Auf/Ab-Button neu gebaut, sonst
  // fiele der Fokus auf <body>. Bevorzugt die gedrückte Richtung; ist dieser
  // Button am Listenrand nun deaktiviert, auf die Gegenrichtung ausweichen,
  // sonst auf den Umbenennen-Button (letzter Rückfall, nie <body>). Nur der
  // Button-Pfad ruft das auf — der Drag-Pfad übergibt bewusst keine Fokus-Absicht.
  _restoreReorderFocus(rowSelector, dir, prefix = '') {
    const row = this._groupsEl?.querySelector(rowSelector);
    if (!row) return;
    const pick = (action) => {
      const el = row.querySelector(`[data-action="${action}"]`);
      return el && !el.disabled ? el : null;
    };
    const opposite = dir === 'down' ? 'up' : 'down';
    const target = pick(`${prefix}${dir}`)
      || pick(`${prefix}${opposite}`)
      || row.querySelector(`[data-action="${prefix}rename"]`);
    target?.focus();
  }

  // Einmalig warnen, wenn der lazy SortableJS-Import scheitert (statt bei jedem
  // Render still zu schlucken): Drag bleibt unverfügbar, die Auf/Ab-Buttons
  // funktionieren unbeeinflusst weiter. Diagnose-Log, kein Nutzer-Toast.
  _warnDragUnavailable(err) {
    if (this._dragWarned) return;
    this._dragWarned = true;
    console.warn('[yuvomi-category-manager] Drag-and-Drop nicht verfügbar (SortableJS-Import fehlgeschlagen); Auf/Ab-Buttons bleiben nutzbar.', err);
  }

  _announce(message) {
    if (this._announceEl) this._announceEl.textContent = message;
  }

  // Ungespeicherten Text in offenen „Kategorie hinzufügen"-Feldern über einen
  // (Rollback-)Rebuild retten: der Teil-Render verwirft die Formulare des neu
  // gebauten Ausschnitts, also die Werte vorher pro Gruppe/Elternschlüssel
  // einsammeln und danach zurückschreiben (nicht neu gebaute Felder bleiben
  // unberührt, das Zurückschreiben ist für sie ein No-op).
  _snapshotAddInputs() {
    const snapshot = [];
    this._groupsEl?.querySelectorAll('.cat-add-form, .cat-subadd-form').forEach((form) => {
      const input = form.querySelector('input');
      if (input?.value) {
        snapshot.push({
          isSub: form.classList.contains('cat-subadd-form'),
          match: form.dataset.parent ?? form.dataset.group ?? '',
          value: input.value,
        });
      }
    });
    return snapshot;
  }

  _restoreAddInputs(snapshot) {
    if (!snapshot?.length) return;
    snapshot.forEach(({ isSub, match, value }) => {
      const sel = isSub
        ? `.cat-subadd-form[data-parent="${CSS.escape(match)}"]`
        : `.cat-add-form[data-group="${CSS.escape(match)}"]`;
      const input = this._groupsEl?.querySelector(sel)?.querySelector('input');
      if (input) input.value = value;
    });
  }

  _rowHtml(cat, group, isFirst, isLast) {
    return `
      <li class="cat-row" data-key="${esc(this._keyOf(cat))}">
        <span class="cat-row__handle" role="img" aria-label="${esc(t('category.dragHandle'))}" title="${esc(t('category.dragHandle'))}">
          <i data-lucide="grip-vertical" class="icon-sm" aria-hidden="true"></i>
        </span>
        ${this._markHtml(cat)}
        <button type="button" class="cat-row__name" data-action="rename"
              title="${esc(t('category.renameHint'))}">${esc(this._labelResolver(cat))}</button>
        <div class="cat-row__actions row-actions">
          ${this._rowActionsHtml(this._labelResolver(cat), { isFirst, isLast })}
        </div>
        ${this._colorStripHtml(cat)}
        ${this._subListHtml(cat, group)}
      </li>`;
  }

  /**
   * Die vier Zeilenaktionen einer Kategorie oder Unterkategorie.
   *
   * ZEILENAKTION DER SHELL (Komponenten-Kanon 2026-09-26): `.row-action`, das
   * Loeschen `.row-action--danger`, und jeder Knopf nennt sein OBJEKT. Vorher
   * standen hier `btn--icon btn--ghost` und fuer das Loeschen ein roter Ring
   * (`btn--danger-outline`) - fuenfmal untereinander, und alle fuenf hiessen fuer
   * einen Screenreader nur „Loeschen" (Critique A7, Sam), waehrend die Familie
   * nebenan „Alex Johnson loeschen" sagte.
   */
  _rowActionsHtml(name, { isFirst, isLast, sub = false }) {
    const prefix = sub ? 'sub-' : '';
    return [
      rowActionHtml({ icon: 'pencil', action: `${prefix}rename`, label: t('category.renameNamed', { name }) }),
      rowActionHtml({ icon: 'chevron-up', action: `${prefix}up`, label: t('category.moveUpNamed', { name }), attrs: { disabled: isFirst } }),
      rowActionHtml({ icon: 'chevron-down', action: `${prefix}down`, label: t('category.moveDownNamed', { name }), attrs: { disabled: isLast } }),
      rowActionHtml({
        icon: 'trash-2',
        tone: 'danger',
        action: `${prefix}delete`,
        label: t(sub ? 'category.deleteSubNamed' : 'category.deleteNamed', { name }),
      }),
    ].join('');
  }

  /**
   * Das Zeichen der Zeile - als Vollton-Marke, wo eine Palette konfiguriert ist.
   *
   * Die Marke IST die Vorschau: sie zeigt Ton und Glyph genau so, wie die
   * Kategorie danach in der Liste steht (Vollton-Regel, DESIGN.md). Ohne
   * kuratierten Ton bleibt sie neutral - auch das ist die Vorschau, nicht ein
   * Fehlen.
   */
  _markHtml(cat) {
    const icon = this._rowIconResolver?.(cat) || cat.icon;
    // Ohne Palette bleibt es beim nackten Zeichen - fuenf der sechs Aufrufer
    // zeigen ihre Kategorien nirgends als farbige Marke.
    if (!this._colors.length) {
      return icon
        ? `<i data-lucide="${esc(icon)}" class="cat-row__icon icon-md" aria-hidden="true"></i>`
        : '';
    }
    const glyph = icon
      ? `<i data-lucide="${esc(icon)}" class="icon-md" aria-hidden="true"></i>`
      : '';
    const vivid = cat.color ? ' vivid-mark' : '';
    const style = cat.color ? ` style="--seal-accent:${esc(cat.color)}"` : '';
    return `
      <button type="button" class="cat-row__mark${vivid}" data-action="color"
              aria-expanded="false" aria-label="${esc(t('category.colorPick'))}"
              title="${esc(t('category.colorPick'))}"${style}>${glyph}</button>`;
  }

  /**
   * Die Palette einer Zeile, eingeklappt bis jemand die Marke drueckt.
   *
   * Immer sichtbar waeren es acht Punkte MAL sieben Zeilen in einem kleinen
   * Dialog; als Aufklapper zeigt die Zeile ihren Ton und die Wahl erscheint
   * dort, wo sie gebraucht wird. `radiogroup`, weil genau einer gilt.
   */
  _colorStripHtml(cat) {
    if (!this._colors.length) return '';
    // `data-tab-id` statt eines eigenen Attributs: den Streifen bedient
    // `wireTablist(mode: 'select')`, und der liefert Pfeiltasten,
    // Roving-Tabindex und aria-checked - das vorgeschriebene Muster fuer eine
    // radiogroup. Eine handgeschriebene Tastaturschleife waere hier die zweite
    // Fassung derselben zwanzig Zeilen (der Kalender hat eine aeltere).
    const swatch = (value, labelKey) => {
      const on = (cat.color ?? '') === value;
      return `<button type="button" role="radio" aria-checked="${on}"
        class="cat-color-swatch${on ? ' cat-color-swatch--active' : ''}${value ? ' vivid-mark' : ''}"
        data-tab-id="${esc(value || NO_COLOR_ID)}"
        tabindex="${on ? '0' : '-1'}"
        aria-label="${esc(t(labelKey))}" title="${esc(t(labelKey))}"
        ${value ? `style="--seal-accent:${esc(value)}"` : ''}></button>`;
    };
    return `
      <div class="cat-row__colors" role="radiogroup"
           aria-label="${esc(t('category.colorPick'))}" hidden>
        ${swatch('', 'category.colorNone')}
        ${this._colors.map((c, i) => swatch(c, COLOR_LABEL_KEYS[i] ?? 'category.colorPick')).join('')}
      </div>`;
  }

  _subListHtml(cat, group) {
    if (!this._supportsSub || !group?.subcategories) return '';
    const subs = cat.subcategories || [];
    return `
      <ul class="cat-sublist" data-parent="${esc(this._keyOf(cat))}">
        ${subs.map((s, j, arr) => `
          <li class="cat-subrow" data-subkey="${esc(this._keyOf(s))}" data-parent="${esc(this._keyOf(cat))}">
            <span class="cat-subrow__handle" role="img" aria-label="${esc(t('category.dragHandle'))}" title="${esc(t('category.dragHandle'))}">
              <i data-lucide="grip-vertical" class="icon-sm" aria-hidden="true"></i>
            </span>
            <button type="button" class="cat-subrow__name" data-action="sub-rename">${esc(this._labelResolver(s))}</button>
            <div class="cat-row__actions row-actions">
              ${this._rowActionsHtml(this._labelResolver(s), { isFirst: j === 0, isLast: j === arr.length - 1, sub: true })}
            </div>
          </li>`).join('')}
        <li><form class="cat-subadd-form" data-parent="${esc(this._keyOf(cat))}" novalidate autocomplete="off">
          <input class="form-input" type="text" maxlength="60" placeholder="${esc(t('category.addSubPlaceholder'))}" aria-label="${esc(t('category.addSubPlaceholder'))}" />
          <button type="submit" class="btn btn--secondary">${esc(t('common.add'))}</button>
        </form></li>
      </ul>`;
  }

  /**
   * BEIM LOESCHEN KOMMT DIESES EREIGNIS, WENN DAS ELEMENT SCHON AUS DEM DOKUMENT
   * IST (gemessen 08.09.2026 im laufenden Browser: `document.contains(el)` ist
   * dann false).
   *
   * `_delete()` fragt ueber `confirmOverModal`, und das schliesst nach einem Ja
   * das Modal darunter gleich mit ab (`closeModal({ force: true })`), BEVOR es
   * zurueckkehrt - `api.delete` laeuft also erst danach. Fuer die Aufrufer folgen
   * daraus zwei Dinge, und beide gelten fuer JEDEN von ihnen:
   *
   *   - Kein `removeEventListener` in onClose. Wer beim Schliessen abmeldet,
   *     verpasst genau die Loeschung - und behaelt einen lokalen Stand, der eine
   *     Kategorie anbietet, die der Server nicht mehr kennt. Ein Leck entsteht
   *     dadurch nicht: das Element entsteht je Oeffnen neu und wird mit dem
   *     Overlay verworfen, der Listener geht mit ihm.
   *   - Kein `changed`-Merker, der in onClose ausgewertet wird. Er stuende beim
   *     Loeschen auf false. Die Auffrischung gehoert in den Handler selbst.
   */
  _notifyChanged(detail = {}) {
    this.dispatchEvent(new CustomEvent('category-manager-changed', { bubbles: true, detail }));
  }

  // Server-Guard-Fehler in die UI-Sprache übersetzen: die Route liefert einen
  // stabilen `reason`-Code (+ optional `count`) in err.data.
  //
  // Unbekannte Fehler (#1909): hat der Aufrufer `errorFallbackKey` gesetzt,
  // sagt `errorSentence` den Satz - den eines anderen bekannten Grundes (der
  // Laden heisst schon so, die Kategorie wurde inzwischen geloescht) oder den
  // allgemeinen, nie den des Servers. Ohne den Schluessel bleibt der alte
  // Rueckfall auf die Server-Meldung: die Routen jener Module nennen ihre
  // Faelle noch nicht, und der allgemeine Satz sagte dort weniger als heute.
  _errMsg(err) {
    const reason = err?.data?.reason;
    const count = err?.data?.count;
    switch (reason) {
      case 'category_in_use':    return t('category.errorInUse', { count });
      case 'category_last':      return t('category.errorLast');
      case 'category_exists':    return t('category.errorExists');
      case 'subcategory_in_use': return t('category.errorSubInUse', { count });
      case 'subcategory_last':   return t('category.errorSubLast');
      case 'subcategory_exists': return t('category.errorSubExists');
      default:
        return this._errorFallbackKey
          ? errorSentence(err, this._errorFallbackKey)
          : (err?.message ?? '');
    }
  }

  /**
   * Der eine Weg, auf dem eine gescheiterte Aenderung gemeldet wird.
   *
   * Sagt der Server, dass es die Zeile nicht mehr gibt (`isGone`, #1909) -
   * jemand anderes hat sie geloescht, waehrend dieser Dialog offen war -,
   * holt die Komponente ihre Liste selbst neu und meldet dem Aufrufer eine
   * Aenderung, damit auch die Seite darunter nachzieht. Der Satz raet nicht
   * mehr zum Neuladen.
   */
  _fail(err) {
    window.yuvomi?.showToast(this._errMsg(err), 'danger');
    if (!isGone(err)) return;
    // Beim Loeschen ist das Element schon aus dem Dokument (siehe
    // `_notifyChanged`): dann gibt es hier nichts mehr zu zeichnen.
    if (this.isConnected) this._load();
    this._notifyChanged();
  }

  async _onSubmit(e) {
    e.preventDefault();
    const subForm = e.target.closest('.cat-subadd-form');
    if (subForm) {
      const input = subForm.querySelector('input');
      const name = input.value.trim();
      if (!name) return;
      await this._subAdd(subForm.dataset.parent, name);
      return;
    }
    const form = e.target.closest('.cat-add-form');
    if (!form) return;
    const input = form.querySelector('input');
    const name = input.value.trim();
    if (!name) return;
    const group = form.querySelector('[name="category-scope"]')?.value || form.dataset.group;
    try {
      const body = { name };
      if (group) body[this._groupField] = group;
      const res = await api.post(this._basePath, body);
      this._cats.push(res.data);
      this._renderGroup(group ?? '');
      if (this._unifiedAdd) input.value = '';
      window.yuvomi?.showToast(t('category.added'), 'success');
      this._notifyChanged();
    } catch (err) {
      this._fail(err);
    }
  }

  async _onClick(e) {
    const target = e.target.closest('[data-action]');
    if (!target) return;
    const action = target.dataset.action;
    if (action.startsWith('sub-')) {
      const subRow = target.closest('[data-subkey]');
      if (!subRow) return;
      const parent = subRow.dataset.parent;
      const subKey = subRow.dataset.subkey;
      if (action === 'sub-rename') await this._subRename(parent, subKey);
      else if (action === 'sub-up') await this._subMove(parent, subKey, -1);
      else if (action === 'sub-down') await this._subMove(parent, subKey, 1);
      else if (action === 'sub-delete') await this._subDelete(parent, subKey);
      return;
    }
    const row = target.closest('[data-key]');
    if (!row) return;
    const key = row.dataset.key;
    if (action === 'color') { this._toggleColors(row); return; }
    if (action === 'rename') await this._rename(key);
    else if (action === 'up') await this._move(key, -1);
    else if (action === 'down') await this._move(key, 1);
    else if (action === 'delete') await this._delete(key);
  }

  _toggleColors(row) {
    const strip = row.querySelector('.cat-row__colors');
    const btn = row.querySelector('.cat-row__mark');
    if (!strip || !btn) return;
    const open = strip.hidden;
    // Erst beim Aufklappen verdrahten: der Streifen wird bei jedem
    // Gruppen-Render neu gebaut, und eine Verdrahtung im Voraus waere N
    // Listener fuer eine Palette, die meistens niemand oeffnet.
    if (open && !strip.dataset.wired) {
      strip.dataset.wired = '1';
      const cat = this._cats.find((c) => this._keyOf(c) === row.dataset.key);
      wireTablist(strip, {
        activeId: cat?.color || NO_COLOR_ID,
        activeClass: 'cat-color-swatch--active',
        mode: 'select',
        onChange: (id) => this._setColor(row.dataset.key, id === NO_COLOR_ID ? '' : id),
      });
    }
    // Nur eine Palette gleichzeitig: zwei offene Streifen in einer kurzen
    // Liste lesen sich als Mehrfachauswahl.
    for (const other of this.querySelectorAll('.cat-row__colors')) other.hidden = true;
    for (const other of this.querySelectorAll('.cat-row__mark')) other.setAttribute('aria-expanded', 'false');
    strip.hidden = !open;
    btn.setAttribute('aria-expanded', String(open));
    if (open) strip.querySelector('[aria-checked="true"], .cat-color-swatch')?.focus();
  }

  async _setColor(key, color) {
    const cat = this._cats.find((c) => this._keyOf(c) === key);
    if (!cat || (cat.color ?? '') === color) return;
    try {
      // NUR die Farbe schicken: der Name der sieben Seed-Kategorien lebt als
      // `label_key` und wuerde beim Mitschicken auf die Sprache dieses
      // Klienten festgenagelt (siehe die Route).
      const res = await api.put(`${this._basePath}/${encodeURIComponent(key)}`, { color: color || null });
      const idx = this._cats.findIndex((c) => this._keyOf(c) === key);
      if (idx >= 0) this._cats[idx] = res.data;
      // KEIN Re-Render der Gruppe, und das ist keine Optimierung: eine
      // radiogroup wechselt bei JEDER Pfeiltaste ihren Wert. Ein Neubau der
      // Zeilen nimmt dabei den Fokus mit und schliesst den Streifen - nach
      // genau einem Schritt waere die Tastaturbedienung zu Ende. Geaendert hat
      // sich ohnehin nur die Marke.
      this._paintMark(key, res.data.color);
      this._notifyChanged();
    } catch (err) {
      this._fail(err);
    }
  }

  /** Die Marke einer Zeile auf einen neuen Ton setzen, ohne die Zeile neu zu bauen. */
  _paintMark(key, color) {
    const mark = this.querySelector(`[data-key="${CSS.escape(String(key))}"] .cat-row__mark`);
    if (!mark) return;
    mark.classList.toggle('vivid-mark', !!color);
    if (color) mark.style.setProperty('--seal-accent', color);
    else mark.style.removeProperty('--seal-accent');
  }

  async _rename(key) {
    const cat = this._cats.find((c) => this._keyOf(c) === key);
    if (!cat) return;
    const { promptModal, captureModalContext, isModalContextCurrent } = await import('/components/modal.js');
    const current = this._labelResolver(cat);
    let promptValue = current;
    while (true) {
      const newName = await promptModal(t('category.renamePrompt'), promptValue);
      if (!newName || newName === current) return;
      const modalContext = captureModalContext();
      try {
        const res = await api.put(`${this._basePath}/${encodeURIComponent(key)}`, { name: newName });
        const idx = this._cats.findIndex((c) => this._keyOf(c) === key);
        if (idx >= 0) this._cats[idx] = res.data;
        this._renderGroup(this._groupOf(cat));
        window.yuvomi?.showToast(t('category.renamed'), 'success');
        this._notifyChanged();
        return;
      } catch (err) {
        this._fail(err);
        if (err?.status !== 409) return;
        // Der 409 darf nur den Prompt wiederholen, aus dem diese Anfrage kam.
        // Ein inzwischen geoeffnetes (selbst schon wieder geschlossenes)
        // Modal oder eine neue Seiteninstanz besitzt den Shared-Slot; dort
        // wuerde promptModal() den fremden Dialog sonst mit force wegraeumen.
        if (!isModalContextCurrent(modalContext)) return;
        promptValue = newName;
      }
    }
  }

  async _move(key, delta) {
    const cat = this._cats.find((c) => this._keyOf(c) === key);
    if (!cat) return;
    const groupKey = this._groupOf(cat);
    // Auf einer Kopie arbeiten: _inGroup('') liefert bei gruppenlosen Modulen
    // (z. B. Kontakte) die LIVE-this._cats-Referenz zurück. Ein In-place-Swap
    // würde den State schon vor der Persistenz optimistisch umstellen — bei einem
    // fehlgeschlagenen Reorder (Button-Pfad rendert dann bewusst nicht) bliebe
    // this._cats in der ungespeicherten Reihenfolge zurück und der nächste
    // _render() zeigte sie an. Nur die berechnete Schlüsselliste zählt hier.
    const group = this._inGroup(groupKey).slice();
    const idx = group.findIndex((c) => this._keyOf(c) === key);
    const nextIdx = idx + delta;
    if (idx < 0 || nextIdx < 0 || nextIdx >= group.length) return;
    [group[idx], group[nextIdx]] = [group[nextIdx], group[idx]];
    // Fokus-Absicht mitgeben: nur der Button-Pfad (nicht Drag) soll den Fokus
    // nach dem Teil-Render auf der bewegten Zeile halten.
    await this._persistOrder(groupKey, group.map((c) => this._keyOf(c)), key, {
      focusKey: key,
      focusDir: delta > 0 ? 'down' : 'up',
    });
  }

  // Gemeinsamer Persistenz-Pfad für Auf/Ab-Buttons UND Drag-Ende (_wireSortableIn):
  // beide berechnen nur die neue Reihenfolge, dieser Handler übernimmt PATCH +
  // Refresh + Ansage. Bei Erfolg ersetzt die volle Server-Liste (contacts/tasks/
  // shopping liefern sie im PATCH bereits mit) den State direkt; nur Antworten
  // ohne Liste (budget: {data:true}) holen den Stand per zusätzlichem GET nach.
  // Bei Fehlern rollt NUR der Drag-Pfad zurück (rollbackRender): SortableJS hat
  // das DOM schon optimistisch umgestellt, ein Rebuild aus dem unveränderten
  // State stellt die servergültige Reihenfolge wieder her. Der Button-Pfad
  // rendert bewusst NICHT (sonst Fokusverlust auf dem gerade geklickten Auf/Ab-
  // Button und Verlust ungespeicherten Texts in offenen Add-Feldern).
  async _persistOrder(groupKey, orderedKeys, movedKey, { rollbackRender = false, focusKey = null, focusDir = null } = {}) {
    try {
      const body = { order: orderedKeys };
      if (groupKey) body[this._groupField] = groupKey;
      const res = await api.patch(`${this._basePath}/reorder`, body);
      if (Array.isArray(res?.data)) this._cats = res.data;
      else await this._fetch();
      this._renderGroup(groupKey);
      if (focusKey) this._restoreReorderFocus(`.cat-row[data-key="${CSS.escape(focusKey)}"]`, focusDir);
      if (movedKey) this._announceMove(movedKey, { groupKey });
      this._notifyChanged();
    } catch (err) {
      this._fail(err);
      if (rollbackRender) {
        const inputs = this._snapshotAddInputs();
        this._renderGroup(groupKey);
        this._restoreAddInputs(inputs);
      }
    }
  }

  // Position/Gesamtzahl NACH dem Refresh aus dem frischen State neu bestimmen
  // (nicht aus dem vor dem await berechneten orderedKeys-Array): bei einer
  // nebenläufigen Änderung könnte die lokal berechnete Liste sonst von der
  // tatsächlich gerenderten abweichen.
  _announceMove(key, { groupKey = null, parentKey = null } = {}) {
    let list;
    let cat;
    if (parentKey != null) {
      const found = this._findSub(parentKey, key);
      if (!found) return;
      cat = found.sub;
      list = found.cat.subcategories || [];
    } else {
      list = this._inGroup(groupKey);
      cat = list.find((c) => this._keyOf(c) === key);
    }
    const idx = list.findIndex((c) => this._keyOf(c) === key);
    if (idx < 0) return;
    this._announce(t('category.reorderAnnounce', {
      name: cat ? this._labelResolver(cat) : '',
      position: idx + 1,
      total: list.length,
    }));
  }

  async _delete(key) {
    const cat = this._cats.find((c) => this._keyOf(c) === key);
    if (!cat) return;
    const { confirmOverModal } = await import('/components/modal.js');
    const confirmed = await confirmOverModal(
      t(this._deleteConfirmKey, { name: this._labelResolver(cat) }),
      { danger: true, confirmLabel: t('common.delete'), detail: t(this._deleteDetailKey) }
    );
    if (!confirmed) return;
    try {
      try {
        await api.delete(`${this._basePath}/${encodeURIComponent(key)}`);
      } catch (err) {
        // JEMAND ANDERES HAT DIE ZEILE SCHON GELOESCHT: das Ziel ist erreicht,
        // also laeuft der Erfolgsweg darunter - Zeile raus, "Geloescht", und
        // die Seite erfaehrt es wie jedes Loeschen. Nur mit dem Grund, den der
        // Aufrufer genannt hat (`alreadyDeletedReason`); alles andere ist ein
        // Fehler und geht an `_fail`.
        if (!this._alreadyDeletedReason || !isAlreadyDeleted(err, this._alreadyDeletedReason)) throw err;
      }
      this._cats = this._cats.filter((c) => this._keyOf(c) !== key);
      this._renderGroup(this._groupOf(cat));
      window.yuvomi?.showToast(t('category.deleted'), 'default');
      this._notifyChanged({ action: 'delete', key, item: cat });
    } catch (err) {
      this._fail(err);
    }
  }

  _findSub(parent, subKey) {
    const cat = this._cats.find((c) => this._keyOf(c) === parent);
    if (!cat) return null;
    const sub = (cat.subcategories || []).find((s) => this._keyOf(s) === subKey);
    return sub ? { cat, sub } : null;
  }

  async _subAdd(parent, name) {
    try {
      const res = await api.post(
        `${this._basePath}/${encodeURIComponent(parent)}/subcategories`,
        { name }
      );
      await this._fetch();
      this._renderSublist(parent);
      window.yuvomi?.showToast(t('category.added'), 'success');
      this._notifyChanged();
      return res;
    } catch (err) {
      this._fail(err);
    }
  }

  async _subRename(parent, subKey) {
    const found = this._findSub(parent, subKey);
    if (!found) return;
    const { promptModal } = await import('/components/modal.js');
    const current = this._labelResolver(found.sub);
    const newName = await promptModal(t('category.renamePrompt'), current);
    if (!newName || newName === current) return;
    try {
      await api.put(
        `${this._basePath}/${encodeURIComponent(parent)}/subcategories/${encodeURIComponent(subKey)}`,
        { name: newName }
      );
      await this._fetch();
      this._renderSublist(parent);
      window.yuvomi?.showToast(t('category.renamed'), 'success');
      this._notifyChanged();
    } catch (err) {
      this._fail(err);
    }
  }

  async _subMove(parent, subKey, delta) {
    const cat = this._cats.find((c) => this._keyOf(c) === parent);
    if (!cat) return;
    const subs = (cat.subcategories || []).slice();
    const idx = subs.findIndex((s) => this._keyOf(s) === subKey);
    const nextIdx = idx + delta;
    if (idx < 0 || nextIdx < 0 || nextIdx >= subs.length) return;
    [subs[idx], subs[nextIdx]] = [subs[nextIdx], subs[idx]];
    await this._persistSubOrder(parent, subs.map((s) => this._keyOf(s)), subKey, {
      focusSubKey: subKey,
      focusDir: delta > 0 ? 'down' : 'up',
    });
  }

  // Sub-Pendant zu _persistOrder, gleicher Vertrag (Auf/Ab-Buttons + Drag-Ende
  // in _wireSortableIn rufen beide diesen Handler mit der neuen Reihenfolge auf;
  // nur der Drag-Pfad rollt bei Fehlern per rollbackRender zurück).
  async _persistSubOrder(parent, orderedSubKeys, movedSubKey, { rollbackRender = false, focusSubKey = null, focusDir = null } = {}) {
    try {
      const res = await api.patch(
        `${this._basePath}/${encodeURIComponent(parent)}/subcategories/reorder`,
        { order: orderedSubKeys }
      );
      if (Array.isArray(res?.data)) this._cats = res.data;
      else await this._fetch();
      this._renderSublist(parent);
      if (focusSubKey) this._restoreReorderFocus(`.cat-subrow[data-subkey="${CSS.escape(focusSubKey)}"]`, focusDir, 'sub-');
      if (movedSubKey) this._announceMove(movedSubKey, { parentKey: parent });
      this._notifyChanged();
    } catch (err) {
      this._fail(err);
      if (rollbackRender) {
        const inputs = this._snapshotAddInputs();
        this._renderSublist(parent);
        this._restoreAddInputs(inputs);
      }
    }
  }

  async _subDelete(parent, subKey) {
    const found = this._findSub(parent, subKey);
    if (!found) return;
    const { confirmOverModal } = await import('/components/modal.js');
    const confirmed = await confirmOverModal(
      t('category.deleteSubConfirm', { name: this._labelResolver(found.sub) }),
      { danger: true, confirmLabel: t('common.delete'), detail: t(this._subDeleteDetailKey) }
    );
    if (!confirmed) return;
    try {
      await api.delete(
        `${this._basePath}/${encodeURIComponent(parent)}/subcategories/${encodeURIComponent(subKey)}`
      );
      await this._fetch();
      this._renderSublist(parent);
      window.yuvomi?.showToast(t('category.deleted'), 'default');
      this._notifyChanged();
    } catch (err) {
      this._fail(err);
    }
  }
}

customElements.define('yuvomi-category-manager', CategoryManagerElement);
export { CategoryManagerElement };

changes.before:
/**
 * Modul: Einkaufslisten (Shopping)
 * Zweck: Multi-Listen-Tabs, Artikel mit Kategorie-Gruppierung, Quick-Add mit Autocomplete
 * Abhängigkeiten: /api.js
 */

import { api } from '/api.js';
import { stagger, vibrate, scheduleUndoableDelete, collapseOut, expandIn, acknowledgeCheck, durationToken } from '/utils/ux.js';
import { wireSwipeRows, maybeShowSwipeHint } from '/utils/swipe-row.js';
import { flipSnapshot, flipPlay } from '/utils/flip.js';
import { t } from '/i18n.js';
import { esc } from '/utils/html.js';
import { formRowsHtml, formRowHtml } from '/utils/form-row.js';
import { readRowHtml, readDetailsLabel } from '/utils/read-row.js';
import { promptModal, openModal, closeModal, confirmModal, reportFieldError, refocusAfterRender } from '/components/modal.js';
import { DEFAULT_CATEGORY_NAME, categoryLabel } from '/utils/shopping-categories.js';
import { addLocalDays, todayKey } from '/utils/date.js';
import { renderKitchenTabsBar, refreshKitchenBadges } from '/utils/kitchen-tabs.js';
import { mayImportMealPlan, mayTransferShoppingToPantry } from '/utils/kitchen-transfer.js';
import { mayWritePath } from '/utils/module-access.js';
import { mountEmptyState, mountLoadError } from '/utils/empty-state.js';
import { pageToolsMenuHtml, installPopoverMenus } from '/utils/popover-menu.js';
import { rowMenuHtml } from '/utils/row-action.js';
import '/components/category-manager.js';
import { findPageFab } from '/utils/fab.js';
import { setBulkPill, clearBulkPill, bulkPillLayer } from '/utils/bulk-pill.js';
import { makeSortable } from '/utils/sortable.js';
import { amountPlaceholder, formatMoney, currencyFractionDigits, centsToAmountInput, amountInputToCents, toDecimalString, breaksOffAtSeparator } from '/utils/money.js';
import { startLiveFeed } from '/utils/live-feed.js';
import { createPageController } from '/utils/page-lifecycle.js';
import { errorSentence, isGone, isAlreadyDeleted } from '/utils/friendly-error.js';


// --------------------------------------------------------
// Konstanten
// --------------------------------------------------------

/** Icon für eine Kategorie (aus state.categories, Fallback 'tag'). */
function catIcon(name) {
  return state.categories.find((c) => c.name === name)?.icon ?? 'tag';
}

/** Kategorienamen in DB-Reihenfolge. */
function categoryNames() {
  return state.categories.map((c) => c.name);
}

// --------------------------------------------------------
// State
// --------------------------------------------------------

const state = {
  lists:         [],
  activeListId:  null,
  items:         [],
  activeList:    null,
  categories:    [],   // { id, name, icon, sort_order }[]
  stores:        [],   // verwaltete Laeden fuer den Preis am Artikel (#1003)
  currency:      'EUR',// Haushaltswaehrung, nur fuer die Preisdarstellung
  /** Zwei getrennte Ladewege, zwei getrennte Fehler - sie haben verschiedene
   *  Wiederholungen: die Listen holt die ganze Seite neu, die Artikel nur die
   *  aktive Liste. Ein gemeinsames Feld hätte den einen Fehler mit der
   *  Wiederholung des anderen bedient. */
  listsError:    null,
  itemsError:    null,
  /** Wer gerade angemeldet ist - der Einklapp-Zustand der Kategorien ist pro
   *  Haushaltsmitglied gespeichert (#1039), nicht geteilt wie sonst nichts in
   *  diesem Modul: zwei Personen am selben Geraet sollen sich nicht gegenseitig
   *  die Gruppen zu- oder aufklappen. */
  currentUserId: null,
  /** Eingeklappte Kategorien der AKTIVEN Liste, als Menge stabiler Schluessel
   *  (siehe categoryStorageKey). Nur das Eingeklappte wird gespeichert - eine
   *  neu angelegte Kategorie ist damit ohne Zutun aufgeklappt (dieselbe Regel
   *  wie bei den Aufgaben-Gruppen, #812). */
  collapsedCategories: new Set(),
  /** Ist der Abschnitt „Abgehakt" der AKTIVEN Liste aufgeklappt (#1816)?
   *  Gespeichert wie die Kategorien - je Mitglied und Liste -, nur mit dem
   *  umgekehrten Grundzustand: er startet ZU, also wird das Offene gemerkt. */
  tickedOpen: false,
};

// --------------------------------------------------------
// Hilfsfunktionen
// --------------------------------------------------------

function groupItemsByCategory(items) {
  const grouped = {};
  for (const item of items) {
    const cat = item.category || (state.categories[0]?.name ?? DEFAULT_CATEGORY_NAME);
    (grouped[cat] = grouped[cat] || []).push(item);
  }
  // In DB-Reihenfolge zurückgeben; unbekannte Kategorien ans Ende
  const names   = categoryNames();
  const known   = names.filter((c) => grouped[c]).map((c) => [c, grouped[c]]);
  const unknown = Object.keys(grouped).filter((c) => !names.includes(c)).map((c) => [c, grouped[c]]);
  return [...known, ...unknown];
}

/** Die Kategorie, unter der ein Artikel steht - dieselbe Regel wie beim Gruppieren. */
function categoryOf(item) {
  return item.category || (state.categories[0]?.name ?? DEFAULT_CATEGORY_NAME);
}

/** Handsortierung, dann Eingabereihenfolge - wie `loadListItems` auf dem Server, ohne `is_checked`. */
function byRank(a, b) {
  return (a.sort_order ?? 0) - (b.sort_order ?? 0) || a.id - b.id;
}

/**
 * Die Liste in ihren zwei Teilen (#1816): je Kategorie die OFFENEN Artikel,
 * und EIN Abschnitt mit allem Abgehakten am Ende.
 *
 * Eine Kategorie bleibt auch ohne offenen Artikel in `groups` stehen (leer):
 * ihr Traeger wird gebraucht, sobald einer ihrer abgehakten Artikel
 * zurueckkommt - die Zeile wandert dann an Ort und Stelle, ohne Neuaufbau.
 *
 * Gelesen wird `checkedOf`, also die eigene Absicht vor dem Serverstand: die
 * Zeile steht dort, wo ihr Haken sie zeigt - ausser sie WARTET noch auf die
 * Pause (`heldRows`, siehe `holdPlacement`): dann steht sie, wo sie beim
 * Antippen stand, auch ueber einen Neuaufbau der Liste hinweg.
 */
function listSections(items) {
  const all = groupItemsByCategory(items);
  const position = new Map(all.map(([cat], idx) => [cat, idx]));
  const inTicked = (i) => (heldRows.has(i.id) ? heldRows.get(i.id) : Boolean(checkedOf(i)));
  const groups = all.map(([cat, members]) => [cat, members.filter((i) => !inTicked(i)).sort(byRank)]);
  const ticked = items.filter(inTicked)
    .sort((a, b) => position.get(categoryOf(a)) - position.get(categoryOf(b)) || byRank(a, b));
  return { groups, ticked };
}

/**
 * Wohin eine Zeile gehoert: in den Abschnitt „Abgehakt" oder in ihre
 * Kategorie, und vor welche Nachbarn. `following` nennt ALLE Artikel, die im
 * Ziel nach ihr stehen - der Aufrufer nimmt den ersten, dessen Zeile dort
 * schon steht (ein Nachbar kann selbst noch unterwegs sein).
 */
function placementOf(items, id) {
  const item = items.find((i) => i.id === id);
  if (!item) return null;
  const { groups, ticked } = listSections(items);
  const isTicked = ticked.includes(item);
  const category = categoryOf(item);
  const members = isTicked ? ticked : (groups.find(([cat]) => cat === category)?.[1] ?? []);
  return {
    ticked: isTicked,
    category,
    following: members.slice(members.indexOf(item) + 1).map((i) => i.id),
  };
}

// --------------------------------------------------------
// Abschnitt „Abgehakt": auf oder zu (#1816)
//
// Derselbe Speicherort und derselbe Zuschnitt wie bei den Kategorien darunter
// (localStorage, je Mitglied und Liste). Eine eigene Zeile und kein weiterer
// Schluessel in deren Menge: dort heisst ein Eintrag „zugeklappt" und faellt,
// sobald keine Gruppe mehr zu ihm passt - dieser Abschnitt ist aber von Haus
// aus zu, und gemerkt wird das Gegenteil.
// --------------------------------------------------------

const TICKED_OPEN_VERSION = 1;

function tickedOpenStorageKey(userId, listId) {
  return `yuvomi:shopping:tickedOpen:v${TICKED_OPEN_VERSION}:${userId ?? 'anon'}:${listId}`;
}

function loadTickedOpen(userId, listId) {
  try {
    return localStorage.getItem(tickedOpenStorageKey(userId, listId)) === '1';
  } catch {
    return false;
  }
}

function saveTickedOpen(userId, listId, open) {
  try {
    if (open) localStorage.setItem(tickedOpenStorageKey(userId, listId), '1');
    else localStorage.removeItem(tickedOpenStorageKey(userId, listId));
  } catch { /* Privatmodus/Quota: der Zustand gilt dann nur fuer diese Sitzung */ }
}

// --------------------------------------------------------
// Kategorie-Einklappen (#1039)
//
// GESPEICHERT WIRD PRO HAUSHALTSMITGLIED UND PRO LISTE, NICHT GETEILT: anders
// als die Aufgaben-Gruppen (eine einzige, ungescopte localStorage-Zeile, #812)
// hat der Einkauf mehrere Listen UND mehrere Nutzer desselben Geraets - eine
// geteilte Zeile haette „Moabit" und „Neukoelln" dieselbe Klapp-Ansicht
// aufgezwungen und einem zweiten Haushaltsmitglied die Gruppen des ersten
// zugeklappt vorgesetzt.
//
// GESPEICHERT WIRD NUR DIE STABILE ID, NICHT DER NAME: eine Kategorie-
// Umbenennung darf den Klapp-Zustand nicht verlieren. Nur Kategorien ohne ID
// (geloescht, oder Altbestand vor der Kategorie-Verwaltung) fallen auf den
// normalisierten Namen zurueck - das einzige, was sie stabil identifiziert.
// --------------------------------------------------------

const COLLAPSED_CATEGORIES_VERSION = 1;

function collapsedCategoriesStorageKey(userId, listId) {
  return `yuvomi:shopping:collapsedCategories:v${COLLAPSED_CATEGORIES_VERSION}:${userId ?? 'anon'}:${listId}`;
}

/** Stabiler Speicherschluessel einer Kategorie: ID wenn bekannt, sonst normalisierter Name. */
function categoryStorageKey(name) {
  const known = state.categories.find((c) => c.name === name);
  return known ? `id:${known.id}` : `name:${String(name ?? '').trim().toLowerCase()}`;
}

function loadCollapsedCategories(userId, listId) {
  try {
    const raw = JSON.parse(localStorage.getItem(collapsedCategoriesStorageKey(userId, listId)) ?? 'null');
    if (!raw || raw.version !== COLLAPSED_CATEGORIES_VERSION || !Array.isArray(raw.collapsed)) {
      return new Set();
    }
    return new Set(raw.collapsed.filter((key) => typeof key === 'string'));
  } catch {
    // Privatmodus/kaputtes JSON/Quota: die Gruppen starten dann offen, statt
    // die Seite an einem defekten Speicherwert scheitern zu lassen.
    return new Set();
  }
}

function saveCollapsedCategories(userId, listId, collapsedSet) {
  try {
    localStorage.setItem(
      collapsedCategoriesStorageKey(userId, listId),
      JSON.stringify({ version: COLLAPSED_CATEGORIES_VERSION, collapsed: [...collapsedSet] }),
    );
  } catch { /* Privatmodus/Quota: der Zustand gilt dann nur fuer diese Sitzung */ }
}

/**
 * Entfernt Schluessel, die zu keiner der GERADE gerenderten Gruppen mehr
 * gehoeren (geloeschte Kategorie, oder die letzte Zeile einer unbekannten
 * Kategorie ist weg). Laeuft erst, NACHDEM Listen- und Kategorie-Metadaten
 * vollstaendig geladen sind - vorher liesse sich „gehoert nicht mehr dazu"
 * nicht von „ist nur noch nicht geladen" unterscheiden.
 */
function pruneCollapsedCategories(groups) {
  const validKeys = new Set(groups.map(([cat]) => categoryStorageKey(cat)));
  let changed = false;
  for (const key of [...state.collapsedCategories]) {
    if (!validKeys.has(key)) {
      state.collapsedCategories.delete(key);
      changed = true;
    }
  }
  if (changed) saveCollapsedCategories(state.currentUserId, state.activeListId, state.collapsedCategories);
}

/** Klappt eine Kategorie in-place um (kein Listen-Rerender, siehe renderItems). */
function toggleCategoryCollapse(button) {
  const key = button.dataset.categoryToggle;
  const nowCollapsed = !state.collapsedCategories.has(key);

  if (nowCollapsed) state.collapsedCategories.add(key);
  else state.collapsedCategories.delete(key);

  foldGroup(button, nowCollapsed, () => state.collapsedCategories.has(key));

  saveCollapsedCategories(state.currentUserId, state.activeListId, state.collapsedCategories);
}

/**
 * Die Bewegung eines Gruppenkopfs, geteilt von Kategorie und „Abgehakt".
 * `stillCollapsed` fragt den ZUSTAND im Moment, in dem das Einklappen endet.
 */
function foldGroup(button, nowCollapsed, stillCollapsed) {
  const rowsEl = button.closest('.list-group')?.querySelector('.row-carrier');
  const chevron = button.querySelector('.list-group__chevron');
  button.setAttribute('aria-expanded', String(!nowCollapsed));
  chevron?.classList.toggle('list-group__chevron--collapsed', nowCollapsed);
  // Die Zeilen klappen, statt zu springen (Critique 2026-09-26, A3 P1-4), wie
  // in den Aufgaben. `hidden` faellt erst NACH dem Einklappen - vorher gaebe es
  // nichts mehr zu bewegen. Ein Gegenklick waehrend der Bewegung bricht sie ab
  // und zieht von der aktuellen Stelle wieder auf; das spaete `then` sieht am
  // Zustand, dass es nicht mehr gemeint ist.
  if (!rowsEl) return;
  rowsEl.getAnimations?.().forEach((anim) => anim.cancel());
  rowsEl.style.overflow = '';
  if (nowCollapsed) {
    collapseOut(rowsEl).then(() => {
      if (!stillCollapsed()) return;
      rowsEl.hidden = true;
      rowsEl.getAnimations?.().forEach((anim) => anim.cancel());
      rowsEl.style.overflow = '';
    });
  } else {
    rowsEl.hidden = false;
    expandIn(rowsEl);
  }
}

/** Klappt den Abschnitt „Abgehakt" um - an Ort und Stelle, wie eine Kategorie. */
function toggleTickedSection(button) {
  state.tickedOpen = !state.tickedOpen;
  foldGroup(button, !state.tickedOpen, () => !state.tickedOpen);
  saveTickedOpen(state.currentUserId, state.activeListId, state.tickedOpen);
}

// --------------------------------------------------------
// Nur-lesen (#1265 P4)
// --------------------------------------------------------

/**
 * Darf dieses Konto in den Einkauf schreiben? Regel 1 in utils/module-access.js:
 * `!mayWritePath('/shopping')` ist dasselbe Urteil wie
 * `isNavModuleReadOnly('shopping')`. Als Funktion, damit jedes Neuzeichnen neu
 * fragt - ein Rechtewechsel kommt ohne Neuladen an.
 *
 * WAS BEI `read` BLEIBT: die Listen-Reiter, das Auf- und Zuklappen der
 * Kategorien, der Haken als ZEICHEN (`.item-check--static`, gesetzt oder offen
 * - beides ist ein Zustand des Datensatzes) und, wo der Artikel mehr traegt als
 * die Zeile zeigt, eine Leseansicht (Regel 9). WAS GEHT: Quick-Add und FAB,
 * neue Liste, das ganze Listenmenue, Griff, Loeschen, Bearbeiten und beide
 * Wischgesten - die zwei letzten haben kein Markup und bleiben deshalb
 * unverdrahtet (Regel 3).
 *
 * KEIN WANDTABLETT: ein Display fuehrt `shopping` nicht in seiner Scope-Liste
 * (server/display-scopes.js) und erreicht diese Seite nicht; ein
 * `actingAsDisplay()` davor braucht es hier nicht.
 */
function readOnly() {
  return !mayWritePath('/shopping');
}

/**
 * Die `data-action`s dieser Seite, die NICHT schreiben - eine Positivliste wie
 * in waste.js: eine morgen ergaenzte Schreib-Aktion ist bei `read` damit zu,
 * bis sie hier ausdruecklich eingetragen wird. Das Klappen der Kategorien laeuft
 * ueber `data-category-toggle`, nicht ueber `data-action`, und steht davor.
 */
const READ_SAFE_ACTIONS = new Set(['switch-list', 'item-details']);

/** Der Riegel im delegierten Handler: laesst bei `read` nur die Positivliste durch. */
function readOnlyBlocks(action) {
  return readOnly() && !READ_SAFE_ACTIONS.has(action);
}

function shouldIgnoreShoppingRowToggle(target) {
  return Boolean(target?.closest?.('button, a, input, select, textarea, [data-no-row-toggle]'));
}

// --------------------------------------------------------
// Sammelaktions-Pille: Zustandsautomat (#1039)
//
// VORHER rief updateCheckedActions() bei JEDEM Aufruf setBulkPill() auf,
// solange irgendein Artikel abgehakt war - die Pille blieb dadurch dauerhaft
// stehen, sobald beim Laden schon etwas abgehakt war, und nahm der Liste einen
// Streifen Flaeche fuer eine Rueckmeldung, die zur einzelnen Abhak-Handlung
// gehoert, nicht zum Ladezustand.
//
// JETZT vier Zustaende:
//   idle       - nichts abgehakt (der naechste Treffer eroeffnet einen Batch)
//   visible    - Pille steht, Fuenf-Sekunden-Frist laeuft
//   deferred   - Frist abgelaufen, aber Zeiger/Tastatur stehen noch auf der
//                Pille; sie verschwindet erst, wenn die Interaktion endet
//   suppressed - Frist (oder deferred-Interaktion) ist zu Ende, der Batch
//                bleibt aber > 0: dieselbe Teilmenge zeigt die Pille nicht
//                erneut, bis sie auf 0 faellt
//
// GENERATION UND `container.isConnected` STATT EINES ROUTER-HOOKS: die Seite
// hat keinen Teardown-Callback - switchList()/render() ersetzen den Inhalt
// einfach. Ein gestellter Timer wuerde ohne Gegenmassnahme nach einem
// Listenwechsel oder einer Navigation noch feuern und setBulkPill()/
// clearBulkPill() auf der SHELL-Schicht ausloesen, die ueber die Seite hinaus
// lebt - sichtbar als eine fremde Pille (Pantry/Kontakte teilen dieselbe
// Schicht), die ploetzlich verschwindet. Jeder Timer traegt die Generation,
// unter der er entstand, und prueft sie plus die Verbindung seiner Wurzel zum
// Dokument, bevor er etwas anfasst.
// --------------------------------------------------------

let BULK_PILL_HOLD_MS_OVERRIDE = null; // nur fuer Tests, siehe __test unten
const BULK_PILL_HOLD_MS = 5000;

let pillTimer = null;
let pillPhase = 'idle'; // 'idle' | 'visible' | 'deferred' | 'suppressed'
let pillInteracting = false;
/** Die Seiten-Wurzel, der der aktuell sichtbare Batch gehoert - siehe unten. */
let pillOwnerContainer = null;

function clearPillTimer() {
  if (pillTimer) { clearTimeout(pillTimer); pillTimer = null; }
}

function schedulePillHide(container) {
  clearPillTimer();
  pillTimer = setTimeout(() => {
    pillTimer = null;
    // Verlassene Seite: die Wurzel haengt nicht mehr im Dokument (der Router
    // hat sie beim Navigieren ersetzt). `resetPillMachine()` raeumt jeden
    // Listenwechsel/Seitenaufbau selbst per `clearPillTimer()` auf, deshalb
    // genuegt hier die Verbindung zum Dokument als einzige Pruefung.
    if (!container.isConnected) return;
    if (pillInteracting) { pillPhase = 'deferred'; return; }
    pillPhase = 'suppressed';
    clearBulkPill();
  }, BULK_PILL_HOLD_MS_OVERRIDE ?? BULK_PILL_HOLD_MS);
}

/**
 * Haengt Hover/Fokus-Beobachtung einmalig an die geteilte Pillen-Schicht - sie
 * lebt app-weit, der Aufruf ist deshalb idempotent (dataset-Flag) statt an
 * einen bestimmten Seitenbesuch gebunden.
 */
function wirePillInteractionGuards() {
  const layer = bulkPillLayer();
  if (!layer || layer.dataset.shoppingPillWired) return;
  layer.dataset.shoppingPillWired = '1';

  layer.addEventListener('mouseenter', () => { pillInteracting = true; });
  layer.addEventListener('focusin', () => { pillInteracting = true; });

  const endInteraction = () => {
    pillInteracting = false;
    if (pillPhase !== 'deferred') return;
    pillPhase = 'suppressed';
    // Diese Schicht ist GETEILT (Pantry/Kontakte zeigen hier ihre eigene
    // Pille) und der Listener bleibt app-weit bestehen, auch nachdem der
    // Einkauf laengst verlassen wurde - ohne die Eigentuems-Pruefung wuerde
    // ein Maus-Verlassen auf einer FREMDEN, gerade sichtbaren Pille sie
    // versehentlich loeschen, nur weil `pillPhase` hier zufaellig noch
    // 'deferred' vom letzten Einkaufsbesuch war.
    if (pillOwnerContainer?.isConnected) clearBulkPill();
  };
  layer.addEventListener('mouseleave', endInteraction);
  layer.addEventListener('focusout', (e) => {
    if (layer.contains(e.relatedTarget)) return; // Fokus bleibt innerhalb der Pille
    endInteraction();
  });
}

/** Setzt den Automaten zurueck - bei Listenwechsel und bei jedem Rendern der Seite. */
function resetPillMachine() {
  clearPillTimer();
  pillPhase = 'idle';
  pillInteracting = false;
  pillOwnerContainer = null;
}

/**
 * DIE ABSICHT, NICHT DER STAND.
 *
 * `state.items` traegt ausschliesslich, was der Server zuletzt gesagt hat. Was
 * der Nutzer WILL, steht hier: id -> { value, seq, listId, delta }. Die Zeile
 * zeigt die Ueberlagerung von beidem (`checkedOf`).
 *
 * Der Vorlaeufer vermischte die zwei in einem Feld. Dann braucht ein
 * Fehlschlag eine Ruecksprung-Grundlage, die Grundlage braucht eine
 * Bestaetigungsnummer, die Bestaetigung eine Ladenummer - sechs Felder, die
 * sich gegenseitig ueberschreiben, und sieben Review-Runden lang fand jede
 * neue Wache eine neue Reihenfolge zwischen ihnen. Getrennt gehalten gibt es
 * keinen Wert mehr, der veralten kann: ein Ruecksprung ist das ENTFERNEN der
 * Absicht, und was dann steht, ist der Serverstand.
 *
 * Vier Regeln, mehr nicht:
 *   - Antippen setzt die Absicht.
 *   - Scheitert der Schreibvorgang, faellt sie. Sie war nie wahr.
 *   - Traegt eine Ladeantwort den gewollten Wert, faellt sie. Sie ist erfuellt.
 *   - Gelingt der Schreibvorgang und sagt eine SPAETER begonnene Antwort etwas
 *     anderes, faellt sie auch: der Server hat sie gesehen und seither
 *     geaendert - jemand anderes im Haushalt. Ohne diese Regel lebte die
 *     Absicht ewig weiter und niemand koennte die Zeile je zurueckholen.
 *
 * Der Schreib-ERFOLG allein raeumt bewusst nichts: die ueberholende Antwort
 * kommt gerade danach, und wer hier raeumte, liesse sie den Stand
 * zurueckdrehen. Er vermerkt nur `settledAt`, damit die vierte Regel weiss, ab
 * wann eine Antwort etwas ueber diese Absicht aussagen KANN.
 *
 * Was der Umbau wegnimmt, sind `rollback` und `confirmedAt` - genau die zwei
 * Felder, die vier Review-Runden lang Befunde erzeugt haben, weil sie einen
 * WERT festhielten, der veralten konnte. `settledAt` haelt keinen Wert fest,
 * sondern eine Reihenfolge, und hat nie einen Befund erzeugt. `delta` ist die
 * Buchungsquittung des Zaehlers: was beim Setzen gebucht wurde, damit das
 * Zuruecknehmen exakt dasselbe abzieht.
 */
const intents = new Map();
/** Monotone Folgenummer, damit ein zweites Antippen das erste ueberstimmt. */
let _checkSeq = 0;
/**
 * Artikel, die lokal schon weg sind, deren Loeschung der Server aber noch nicht
 * in jeder Antwort widerspiegelt: Id -> { listId, checked, removedAt } fuer das
 * Undo-Fenster (`deleteItemUndoable`, `clearCheckedUndoable`) und den Moment
 * danach.
 *
 * Dasselbe Muster wie `intents`, nur fuer das Loeschen: `state.items` traegt
 * den Serverstand, und der Server hat den Artikel im Undo-Fenster noch. Landet
 * in diesen fuenf Sekunden eine Live-Auffrischung (jemand anderes hat die
 * Liste bewegt), ersetzt `loadItems` den Bestand mit der Serverantwort - und
 * die Zeile stuende wieder da, unter dem Toast, der sie als geloescht meldet.
 * Schlimmer: die Quittung des DELETE traegt danach als `before` genau die
 * Marke, die die Auffrischung gesetzt hat, der Feed rueckt vor, und die
 * naechste Abfrage laedt NICHT nach. Die Zeile bliebe stehen, bis sich die
 * Liste das naechste Mal bewegt. Und ein Zuruecknehmen im Fenster legte den
 * Schnappschuss neben die schon wieder vorhandene Zeile: zweimal Milch.
 *
 * Deshalb filtert `loadItems` diese Ids aus jeder Antwort: der Bestand nach
 * der Auffrischung ist der Serverstand OHNE die schwebenden Loeschungen, und
 * genau das ist der Stand, den die Quittung des DELETE dann meint. `loadLists`
 * zieht die Eintraege vom Zaehler im Reiter ab, aus demselben Grund: der Server
 * zaehlt den Artikel noch mit, die Anzeige nicht mehr.
 *
 * DER ERFOLG DES DELETE RAEUMT NICHT SOFORT - dieselbe Regel wie `settledAt`
 * beim Abhaken. Eine Antwort, die VOR dem DELETE losgeschickt wurde und danach
 * eintrifft, traegt den Artikel noch: sie hat den Server gelesen, als er ihn
 * hatte. Waere die Schwebe da schon geraeumt, kaeme die Zeile zurueck - und
 * bliebe, weil die Quittung die Marke des Feeds schon vorgerueckt hat und keine
 * Abfrage mehr nachlaedt. Genau dieses Fenster oeffnet die Live-Auffrischung
 * selbst: eine Abfrage stoesst `loadItems` an, und das Undo-Fenster schliesst,
 * waehrend der GET noch unterwegs ist. Deshalb bekommt der Eintrag beim Erfolg
 * die Ladenummer `removedAt = _loadSeq`: jede Antwort, die bis dahin begonnen
 * hat (`startedAt <= removedAt`), wird weiter gefiltert; eine spaeter begonnene
 * ist die Wahrheit des Servers. Der Eintrag faellt, sobald kein Ladevorgang
 * mehr unterwegs ist, der ihn noch tragen koennte (`pruneSettledRemovals`) -
 * bei ruhiger Seite also sofort. Ein Zuruecknehmen und ein FEHLGESCHLAGENER
 * DELETE raeumen dagegen sofort: der Server hat den Artikel, `restore` bringt
 * ihn zurueck, und jede Antwort darf ihn wieder tragen.
 */
const pendingRemovals = new Map();
/**
 * Wann der Server einen Artikel zuletzt BESTAETIGT hat: id -> Ladenummer.
 *
 * Sie haengt am Artikel, nicht an der Absicht - denn sie ueberlebt diese. Wer
 * zweimal antippt, ersetzt die Absicht; die Bestaetigung des ersten Antippens
 * gilt trotzdem weiter, und eine Ladeantwort, die VOR ihr begann, darf den
 * Wert dieses Artikels nicht zurueckdrehen. Die uebrigen Artikel und die
 * Kategorien derselben Antwort landen ganz normal - deshalb je Artikel und
 * nicht als Wache ueber die ganze Antwort.
 */
const settledAt = new Map();

/**
 * Die Ladeordnung: eine Nummer je BEGONNENEM Ladevorgang, und je Liste die
 * Nummer des zuletzt ANGEWANDTEN.
 *
 * Die einzige verbliebene Zeitrechnung, und sie gehoert zum LADEN, nicht zur
 * Absicht: zwei Auffrischungen koennen sich ueberholen, und eine aeltere
 * Antwort darf den Stand nicht ueberschreiben, den eine juengere schon gesetzt
 * hat. Je Liste, weil ein Laden von Liste B ueber Liste A nichts aussagt.
 *
 * `_loadSeq` zaehlt Artikel- UND Listen-Ladevorgaenge: die Schwebe der
 * Loeschungen fragt bei beiden, ob eine Antwort vor oder nach dem DELETE
 * begonnen hat, und dafuer muss EINE Ordnung gelten. `_loadsInFlight` haelt
 * die Nummern der noch offenen Ladevorgaenge, damit die Schwebe weiss, ob noch
 * eine Antwort unterwegs ist, die einen geloeschten Artikel tragen koennte.
 */
let _loadSeq = 0;
const _appliedLoad = new Map();
// Die Nummer der zuletzt ANGEWANDTEN Listenantwort: eine aeltere, die danach
// eintrifft, ersetzt sie nicht (siehe `loadLists`).
let _appliedListsLoad = 0;
const _loadsInFlight = new Set();

/** Einen Ladevorgang beginnen: Nummer ziehen und als offen vermerken. */
function beginLoad() {
  const startedAt = ++_loadSeq;
  _loadsInFlight.add(startedAt);
  return startedAt;
}

/** Einen Ladevorgang abschliessen - angewandt, verworfen oder gescheitert. */
function endLoad(startedAt) {
  _loadsInFlight.delete(startedAt);
  pruneSettledRemovals();
}

/**
 * Ob eine Antwort, die bei `startedAt` begann, den schwebend geloeschten
 * Artikel noch tragen darf: im Undo-Fenster immer (der Server hat ihn), nach
 * dem DELETE nur, wenn sie vor der Bestaetigung losgeschickt wurde.
 */
function removalHides(entry, startedAt) {
  return entry.removedAt == null || entry.removedAt >= startedAt;
}

/**
 * Den Erfolg eines DELETE vermerken: ab jetzt filtert die Schwebe nur noch
 * Antworten, die vor diesem Moment begonnen haben.
 */
function confirmRemovals(ids) {
  for (const id of ids) {
    const entry = pendingRemovals.get(id);
    if (entry) entry.removedAt = _loadSeq;
  }
  pruneSettledRemovals();
}

/**
 * Bestaetigte Loeschungen fallen lassen, sobald keine Antwort mehr unterwegs
 * ist, die vor ihrer Bestaetigung begonnen hat. Ist nichts unterwegs, sofort.
 */
function pruneSettledRemovals() {
  let oldest = Infinity;
  for (const seq of _loadsInFlight) if (seq < oldest) oldest = seq;
  for (const [id, entry] of pendingRemovals) {
    if (entry.removedAt != null && entry.removedAt < oldest) pendingRemovals.delete(id);
  }
}
/**
 * Zu welcher Liste `state.items` gerade gehoert.
 *
 * `_appliedLoad` merkt sich je Liste, ob schon etwas Netzfrisches ankam -
 * `state.items` haelt aber immer nur EINE Liste. Ohne diese Unterscheidung
 * lehnte die Cache-Wache unten die gecachte Antwort fuer A ab, weil A irgendwann
 * einmal geladen war, und `switchList` zeichnete danach die noch liegenden
 * Artikel von B unter dem Reiter von A - ohne Fehlermeldung, und jede weitere
 * Aktion traf die falsche Liste.
 */
let _itemsListId = null;

/**
 * Den Bestand verwerfen - und mit ihm die Zugehoerigkeit.
 *
 * Die beiden gehoeren zusammen, und getrennt gesetzt laufen sie auseinander:
 * nach `state.items = []` im Fehlerzweig behauptete `_itemsListId` weiter, der
 * (leere) Bestand gehoere zu dieser Liste, und die Wache in `loadItems` lehnte
 * die einzige brauchbare Antwort - die gecachte - als Rueckschritt ab. Der
 * Aufrufer loeschte den Fehler, und die Liste stand als echt leer da.
 */
function clearItems() {
  state.items = [];
  _itemsListId = null;
}

/** Was die Zeile ZEIGT: die Absicht, sonst der Serverstand. */
function checkedOf(item) {
  const intent = intents.get(item?.id);
  return intent ? intent.value : (item?.is_checked ?? 0);
}

/**
 * Erfuellte Absichten fallen lassen: die Antwort traegt, was gewollt war.
 *
 * Der Vergleich ist der ganze Trick. Er braucht keine Uhr und keine
 * Ladenummer - eine Antwort, die den gewollten Wert traegt, BEWEIST, dass der
 * Server ihn hat, ganz gleich wann sie losgeschickt wurde. Und eine, die ihn
 * nicht traegt, beweist nichts: sie kann aelter sein als die Bearbeitung, aus
 * dem Offline-Cache kommen oder von einer fremden Aenderung erzaehlen. In
 * allen drei Faellen ist Warten richtig.
 */
function settleIntents(items, listId, { fromCache = false, startedAt = 0 } = {}) {
  // Eine Antwort aus dem Offline-Cache beweist nichts: sie kann beliebig alt
  // sein, und traegt sie den gewollten Wert zufaellig doch (zweimal antippen
  // fuehrt zum Ausgangswert zurueck), waere die Absicht faelschlich erfuellt.
  if (fromCache) return;
  for (const item of items) {
    const intent = intents.get(item.id);
    if (!intent || intent.listId !== listId) continue;
    // Erfuellt: die Antwort traegt, was gewollt war.
    const erfuellt = item.is_checked === intent.value;
    // Ueberholt: der Server hat diesen Artikel bestaetigt, und DIESE Antwort
    // begann danach - was sie sagt, ist juenger als die eigene Bearbeitung.
    const bestaetigt = settledAt.get(item.id);
    const ueberholt = bestaetigt != null && bestaetigt < startedAt;
    if (erfuellt || ueberholt) intents.delete(item.id);
  }
}

/** Der Haken einer Artikelzeile - das Element, das die Quittung traegt. */
function checkOf(container, id) {
  return container.querySelector(`.swipe-row[data-swipe-id="${id}"] .item-check`);
}

/**
 * @param {object} [opts]
 * @param {boolean} [opts.settleNow] die Zeile zieht sofort um statt nach der Pause
 * @param {object|null} [opts.extra] weitere Felder, die MIT dem Haken in
 *   derselben Anfrage geschrieben werden (das Zurueckholen ueber das
 *   Eingabefeld: Menge, Kategorie). Eine Anfrage, damit es kein Halb gibt -
 *   die Route schreibt alle Felder in einem UPDATE oder keines.
 * @returns {Promise<object|undefined>} die Antwort des Servers; undefined, wenn
 *   nichts geschrieben wurde oder der Schreibvorgang scheiterte
 */
async function toggleShoppingItem(id, checked, container, { settleNow = false, extra = null } = {}) {
  // Dritte Linie hinter Markup und Handler-Riegel: auch ein Aufruf, den ein
  // Rechtewechsel ueberholt hat, schickt nichts.
  if (readOnly()) return;
  const newVal = checked ? 0 : 1;
  const listId = state.activeListId;
  const item   = state.items.find((i) => i.id === id);

  // EINE ABSICHT, DIE HIER ERSETZT WIRD, MUSS ZWEI DINGE HINTERLASSEN.
  //
  // Ihre Zaehlerbuchung: die wird zurueckgenommen, denn die neue bucht gleich
  // ihre eigene. Sonst blieb die des ersten Antippens stehen, wenn dessen
  // Schreibvorgang spaeter schweigend scheitert (er ist ja ueberstimmt).
  //
  // Und ihren bestaetigten Wert: hat der Server sie schon angenommen, ist das
  // ab jetzt der SERVERSTAND. Ohne diese Zeile ging die Bestaetigung mit der
  // Absicht verloren, und ein Fehlschlag der neuen sprang an ihr vorbei auf
  // einen Stand zurueck, den der Server nicht mehr hatte.
  const vorher = intents.get(id);
  if (vorher) updateListCounter(vorher.listId, 0, -vorher.delta);

  // Das Delta zaehlt gegen den SERVERSTAND, nicht gegen das Gezeigte: so ist
  // jede Absicht fuer sich verrechenbar, und ihr Zuruecknehmen trifft genau
  // ihre eigene Buchung.
  const delta = (newVal ? 1 : 0) - (item?.is_checked ? 1 : 0);

  // Wo die Zeile JETZT steht - vor der neuen Absicht gelesen (siehe holdPlacement).
  const shownTicked = Boolean(item && checkedOf(item));
  const seq = ++_checkSeq;
  intents.set(id, { value: newVal, seq, listId, delta });
  // HAPTIK IM MOMENT DES TIPPS (Critique 2026-10-05, R16). Sie stand nach der
  // Serverantwort: die Zeile wechselte sofort, das Vibrieren kam mit der
  // Leitung hinterher. Die Zeile ist optimistisch, also ist es ihre Quittung auch.
  vibrate(10);
  if (item) {
    // Nur die betroffene Zeile aktualisieren — kein Komplett-Re-Render,
    // damit die Scroll-Position der Liste erhalten bleibt (Issue #276).
    updateItemRow(container, item);
    // DIE QUITTUNG GEHOERT DIESEM TIPP (R18). Sie hing als CSS-Animation an
    // `.item-check--checked` und lief deshalb bei jedem Neuzeichnen auf allen
    // abgehakten Zeilen. `updateItemRow` selbst quittiert nichts: es laeuft
    // auch fuer fremde Aenderungen und beim Zuruecksetzen nach einem Fehler.
    acknowledgeCheck(checkOf(container, id), { checked: newVal === 1 });
    // Die Zeile zieht um, sobald man innehaelt (#1816) - als einzelner Knoten,
    // die Liste um sie herum bleibt stehen. Das Zurueckholen ueber das
    // Eingabefeld wartet nicht: dort ist der Umzug selbst die Quittung.
    if (settleNow) settleItemPlacements(container, [id]);
    else holdPlacement(container, id, shownTicked);
    // userChecked NUR beim Abhaken selbst (#1039): das Zurueckholen eines
    // Artikels eroeffnet keinen neuen Feedback-Batch.
    updateCheckedActions(container, { userChecked: newVal === 1 });
    updateListCounter(listId, 0, delta);
    renderTabs(container);
  }

  try {
    const antwort = await api.patch(`/shopping/items/${id}`, { ...extra, is_checked: newVal });
    acknowledgeOwnChange(antwort);
    // BEWUSST OHNE AUFRAEUMEN. Die Absicht faellt erst, wenn eine Ladeantwort
    // den Wert traegt (`settleIntents`) - der Erfolg allein beweist der Zeile
    // nichts gegen eine Antwort, die gleich danach mit dem alten Stand kommt.
    //
    // Eine Ausnahme: ist diese Absicht schon ueberstimmt, wird ihr Ausgang
    // sonst gar nicht verbucht. Der Server steht jetzt auf `newVal`, also
    // gehoert das in den SERVERSTAND - nicht in die Absicht, die einem
    // spaeteren Antippen gehoert.
    // Der Server traegt jetzt `newVal` - das ist ab hier der SERVERSTAND, ganz
    // gleich ob diese Absicht noch die aktuelle ist. Der Zeitstempel daneben
    // schuetzt ihn vor einer Antwort, die vorher losgeschickt wurde.
    const current = state.items.find((i) => i.id === id);
    if (current) {
      // Verschiebt die Bestaetigung den Serverstand unter einer noch offenen
      // Absicht weg, war deren Buchung gegen die ALTE Basis gerechnet. Die
      // Anzeige aendert sich nicht (die Absicht ueberlagert weiter), also darf
      // der Zaehler jetzt nicht wandern - aber das Delta muss mitziehen,
      // damit sein Zuruecknehmen spaeter auf dem richtigen Wert landet.
      const offen = intents.get(id);
      if (offen) offen.delta -= (newVal ? 1 : 0) - (current.is_checked ? 1 : 0);
      current.is_checked = newVal;
    }
    settledAt.set(id, _loadSeq);
    return antwort;
  } catch (err) {
    // ZWEI GRUENDE, WARUM DIE EIGENE ABSICHT NICHT MEHR DA IST, und sie fuehren
    // auseinander. Ueberstimmt: ein neueres Antippen steht an, dessen Ausgang
    // entscheidet ueber Zeile, Zaehler UND Meldung - hier ist nichts zu tun.
    // Erfuellt: eine Antwort trug den Wert schon, weil jemand anderes im
    // Haushalt dasselbe getan hat. Dann steht die Zeile richtig, aber der
    // EIGENE Schreibvorgang ist trotzdem gescheitert und gehoert gemeldet.
    const intent = intents.get(id);
    if (intent && intent.seq !== seq) return;
    if (intent) {
      // DIE ABSICHT FAELLT, mehr passiert nicht. Was die Zeile danach zeigt,
      // ist der Serverstand - der aktuellste, den wir haben, auch wenn eine
      // Auffrischung ihn zwischendurch ausgetauscht hat. Es gibt keinen
      // gemerkten Wert mehr, der dabei veralten koennte.
      intents.delete(id);
      // Der Zaehler nimmt GENAU die Buchung zurueck, die das Setzen gemacht
      // hat - deshalb liegt sie in der Absicht und wird nicht neu berechnet.
      updateListCounter(intent.listId, 0, -intent.delta);
      const current = state.items.find((i) => i.id === id);
      if (current) {
        updateItemRow(container, current);
        // Der Haken ist zurueck, also auch die Zeile - aber nicht unter dem
        // Finger: laeuft gerade eine Pause, wartet sie mit.
        placeOrHold(container, id);
        updateCheckedActions(container);
      }
      renderTabs(container);
    }
    reportError(err, container);
  }
  return undefined;
}

/**
 * Löschen eines Artikels, fünf Sekunden lang widerrufbar: die Zeile geht sofort,
 * der Server-Delete erst nach Ablauf des Fensters (`scheduleUndoableDelete`).
 *
 * Benannt und geteilt, weil das Löschen in dieser Liste über ZWEI Wege geht -
 * den Knopf in der Zeile und die Wischgeste. Als Kopie nebeneinander lief das
 * auseinander: der Knopf hatte den Rückweg, der Wisch rief `api.delete` direkt
 * und löschte sofort und endgültig. Das war die einzige Stelle der App, an der
 * eine Geste unwiderruflich Daten entfernt - wer sie in Aufgaben und
 * Geburtstagen als harmlos gelernt hat, verlor hier ohne Rückweg.
 */
function deleteItemUndoable(id, container) {
  if (readOnly()) return;
  const item     = state.items.find((i) => i.id === id);
  const snapshot = item ? { ...item } : null;
  // Was die Zeile ZEIGT - danach richtet sich, was der Zaehler abzieht. Der
  // Schnappschuss daneben traegt den Serverstand, weil `state.items` nur den
  // fuehrt; eine noch laufende Absicht bleibt in ihrer Karte liegen und
  // ueberlagert den Artikel wieder, wenn das Loeschen zurueckgenommen wird.
  //
  // FRUEHER STAND HIER EIN SONDERFALL: der Merker musste beim Loeschen
  // aufgeraeumt und der Schnappschuss von einem optimistischen Wert
  // zurueckgezogen werden, sonst buchte ein spaeterer Fehlschlag ein zweites
  // Mal (gemessen: `item_total: 0, item_checked: -1`). Mit getrennter Absicht
  // gibt es nichts zurueckzuziehen und nichts doppelt zu buchen.
  const gebucht = Boolean(item && checkedOf(item));
  // DIE BUCHUNG DER OFFENEN ABSICHT IST MIT DIESEM LOESCHEN ABGEGOLTEN: der
  // Zaehler zieht gleich die ANZEIGE ab, und die enthaelt sie. Bliebe die
  // Quittung stehen, buchte ein spaeterer Fehlschlag ein zweites Mal ab -
  // gemessen `item_checked: -1` an einer einelementigen Liste.
  const offen = intents.get(id);
  if (offen) offen.delta = 0;
  // DIE LISTE GEHOERT ZUR AKTION, NICHT ZUM ZEITPUNKT DER RUECKNAHME. Das
  // Undo-Fenster ist fuenf Sekunden lang, und ein Listenwechsel darin tauscht
  // `state.items` samt `state.activeListId` aus. Wer danach zurueckholte, legte
  // den Artikel in die FALSCHE Liste und zaehlte deren Zaehler hoch. Steht so
  // schon seit dem Knopf; mit dem Wisch daneben ist es nur viel leichter zu
  // treffen.
  const listId = state.activeListId;

  // Optimistisch entfernen - und als schwebend vermerken, damit eine
  // Live-Auffrischung im Undo-Fenster die Zeile nicht zurueckbringt.
  pendingRemovals.set(id, { listId, checked: gebucht, removedAt: null });
  state.items = state.items.filter((i) => i.id !== id);
  updateItemsList(container);
  updateListCounter(listId, -1, gebucht ? -1 : 0);
  renderTabs(container);

  scheduleUndoableDelete({
    message: t('shopping.itemDeletedToast', { name: snapshot?.name ?? '' }),
    commit: async ({ keepalive }) => {
      let response;
      let schonWeg = false;
      try {
        response = await api.delete(`/shopping/items/${id}`, { keepalive });
      } catch (err) {
        // JEMAND ANDERES HAT DEN ARTIKEL SCHON GELOESCHT: das Ziel ist
        // erreicht, also gilt das als Erfolg - kein Toast, und die Zeile kommt
        // nicht zurueck (`isAlreadyDeleted`). Alles andere ist ein Fehler.
        schonWeg = isAlreadyDeleted(err, 'shopping_item_not_found');
        if (!schonWeg) {
          // Schlaegt das DELETE fehl, bringt `restore` die Zeile zurueck, und
          // jede Antwort darf sie wieder tragen - sofort, nicht erst spaeter.
          pendingRemovals.delete(id);
          throw err;
        }
      }
      // Ohne Antwort gibt es keine Quittung: die Marke des Feeds bleibt stehen.
      if (response) acknowledgeOwnChange(response);
      // Bestaetigt, aber noch nicht geraeumt: eine Antwort, die vor dem DELETE
      // losging, traegt den Artikel noch (siehe `pendingRemovals`).
      confirmRemovals([id]);
      // Endgueltig weg: die Absicht kann von keiner Antwort mehr erfuellt oder
      // ueberholt werden und laege sonst tot in der Karte. Bis hierher bleibt
      // sie liegen - ein Zuruecknehmen im Undo-Fenster braucht sie, damit die
      // wiederhergestellte Zeile zeigt, was der Server inzwischen hat.
      intents.delete(id);
      // Der Stand der Seite war veraltet, also holt sie den frischen - still,
      // und erst NACH `confirmRemovals`: die Antwort beginnt dann nach der
      // Bestaetigung und gilt als Wahrheit des Servers, auch fuer den Zaehler.
      // Nicht beim Verlassen der Seite (`keepalive`): da zeichnet niemand mehr.
      if (schonWeg && !keepalive) reloadAfterGone(container);
    },
    restore: (err) => {
      pendingRemovals.delete(id);
      if (snapshot) {
        // Der sichtbare Zustand nur, wenn die Liste noch die gezeigte ist -
        // sonst gehoert `state.items` bereits einer anderen. Der Server hat
        // nichts geloescht, also bringt `switchList` den Artikel beim
        // Zurueckwechseln ohnehin mit. Und nur, wenn die Zeile nicht schon
        // wieder da ist - sonst stuende sie zweimal.
        if (state.activeListId === listId && !state.items.some((i) => i.id === id)) {
          state.items.push(snapshot);
          state.items.sort((a, b) => a.id - b.id);
          updateItemsList(container);
        }
        // Zurueckgeholt wird die ANZEIGE, also samt der noch offenen Absicht -
        // und damit ist deren Quittung wieder gueltig. Sie wird berechnet,
        // nicht aufbewahrt: der Abstand zwischen dem, was sie will, und dem
        // Serverstand des Schnappschusses.
        if (offen && intents.get(id) === offen) {
          offen.delta = (offen.value ? 1 : 0) - (snapshot.is_checked ? 1 : 0);
        }
        updateListCounter(listId, 1, checkedOf(snapshot) ? 1 : 0);
        renderTabs(container);
      }
      if (err) reportError(err, container);
    },
  });
}

