/**
 * Die Eintraege des Werkzeugmenues der gewaehlten Liste, in vier Gruppen:
 * Abgehakt | Liste | Stammdaten | Loeschen.
 *
 * DIE ABGEHAKT-GRUPPE (Critique 2026-10-05, R16). "In den Vorrat" und
 * "Abgehakt loeschen" lebten nur in der Sammel-Pille: fuenf Sekunden nach dem
 * ersten Abhaken eines Batches, danach unterdrueckt, bis die Zahl auf 0 faellt
 * (#1039). Wer im Laden zwanzig Artikel abhakt und zu Hause einraeumt, fand
 * den Weg in den Vorrat nicht wieder. Die Pille bleibt die Abkuerzung im
 * Moment des Abhakens; der DAUERHAFTE Ort ist dieses Menue - mit denselben
 * Handlern und denselben Rechtefragen (`pantryTransferOffered`, #1265).
 * Bei `read` entfaellt das ganze Menue (renderTabs), also auch die Gruppe.
 */
function listToolsItems() {
  const list = state.activeList;
  if (!list) return [];
  const checkedCount = state.items.filter((i) => checkedOf(i)).length;
  const checkedGroup = checkedCount ? [{
    group: t('shopping.checkedHint', { count: checkedCount }),
    items: [
      ...(pantryTransferOffered()
        ? [{ action: 'checked-to-pantry', label: t('shopping.toPantry'), icon: 'archive' }]
        : []),
      { action: 'clear-checked', label: t('shopping.clearChecked', { count: checkedCount }), icon: 'list-x', danger: true },
    ],
  }, { separator: true }] : [];
  return [
    ...checkedGroup,
    { action: 'rename-list', label: t('shopping.renameListLabel'), icon: 'pencil', id: list.id },
    { action: 'duplicate-list', label: t('shopping.duplicateListLabel'), icon: 'copy' },
    // Die Uebernahme schreibt auch in den Essensplan (`on_shopping_list`),
    // und die Route verlangt dafuer `meals: write` - schon fuer die
    // Vorschau (#1290). Ohne das endete der Eintrag im 403.
    ...(mayImportMealPlan(list.id)
      ? [{ action: 'import-meals', label: t('shopping.importMeals'), icon: 'utensils' }]
      : []),
    { action: 'send-list', label: t('shopping.sendList'), icon: 'mail' },
    { separator: true },
    { action: 'manage-categories', label: t('shopping.manageCategories'), icon: 'tags' },
    { action: 'manage-stores', label: t('shopping.manageStores'), icon: 'store' },
    { separator: true },
    { action: 'delete-list', label: t('shopping.deleteListLabel'), icon: 'trash', id: list.id, danger: true },
  ];
}

function renderTabs(container) {
  const bar = container.querySelector('#list-tabs-bar');
  if (!bar) return;

  const tabsHtml = state.lists.map((list) => {
    const unchecked = list.item_total - list.item_checked;
    // Der Zähler ist aria-hidden, sonst klebt er am Buttonnamen („Einkauf23");
    // die Ansage steht als aria-label auf dem Tab selbst - dasselbe Muster wie
    // setSubTabBadge. „0 offene Artikel" deckt auch den ✓-Zustand ehrlich ab.
    //
    // DIE WAHL WIRD ANGESAGT, NICHT NUR GEFAERBT (R8 H11): bis dahin trug nur
    // `list-tab--active` den Zustand, und ein Screenreader las fuenf gleiche
    // Knoepfe. Die Leiste ist `role="group"` (sie haelt auch „Neue Liste"),
    // kein Tablist - `aria-selected` waere dort ungueltig, `aria-current`
    // sagt genau „das ist die gezeigte Liste".
    const active = list.id === state.activeListId;
    return `
      <button type="button" class="list-tab ${active ? 'list-tab--active' : ''}"
              data-action="switch-list" data-id="${list.id}"${active ? ' aria-current="true"' : ''}
              ${list.item_total > 0 ? `aria-label="${esc(list.name)}, ${esc(t('nav.shoppingOpen', { count: unchecked }))}"` : ''}>
        ${esc(list.name)}
        ${list.item_total > 0 ? `<span class="list-tab__count" aria-hidden="true">${unchecked > 0 ? unchecked : '✓'}</span>` : ''}
      </button>`;
  }).join('');

  bar.replaceChildren();
  // Führender Listen-Marker: signalisiert „das hier sind Listen" und grenzt die
  // Leiste sichtbar von den Küchen-Modul-Tabs darüber ab (dekorativ, aria-hidden).
  //
  // Am hinteren Ende die Aktionen der GEWÄHLTEN Liste. Sie standen bis 2026-08-11
  // in einem eigenen Kopf darunter, der den Namen der aktiven Liste ein zweites
  // Mal zeigte - der aktive Chip trägt ihn schon (Keine-sichtbare-
  // Titelwiederholung-Regel, DESIGN.md). Der Chip IST der Titel; was der Kopf
  // sonst noch trug, ist genau dieses Menü.
  //
  // Der Trigger klebt am rechten Rand (sticky), während die Chips darunter
  // durchscrollen - das Gegenstück zum Marker links. Sein Panel läuft über die
  // native Popover-API im Top-Layer und wird deshalb vom `overflow-x: auto`
  // dieser Leiste nicht geclippt; ein absolut positioniertes Eigenbau-Menü wäre
  // hier abgeschnitten worden.
  // Bei `read` entfaellt das GANZE Menue: jeder Eintrag schreibt (umbenennen,
  // duplizieren, uebernehmen, senden - ein POST -, verwalten, loeschen), und
  // ein Ausloeser ohne Eintraege waere ein Knopf, der nichts oeffnet.
  const ro = readOnly();
  const actionsHtml = state.activeList && !ro ? `
      ${pageToolsMenuHtml({
        id: 'list-actions-menu',
        // Der Name muss die Liste nennen: der Trigger steht nicht mehr neben
        // einer Überschrift, die den Bezug herstellt. „Mehr" allein ließe offen,
        // worauf sich „Löschen" bezieht - und das löscht die Liste des Haushalts.
        label: t('shopping.listActionsLabel', { name: state.activeList.name }),
        items: listToolsItems(),
      })}` : '';

  bar.insertAdjacentHTML('beforeend', `
    ${tabsHtml}
    ${ro ? '' : `<button class="list-tab__new" data-action="new-list" aria-label="${t('shopping.newListButton')}">
      <i data-lucide="plus" class="icon-md" aria-hidden="true"></i>
    </button>`}
  `);
  if (window.lucide) window.lucide.createIcons({ el: bar });

  // KUECHENKOPF (Kopfregel mobil, 2026-09-26): das Menue der gewaehlten Liste
  // ist das EINE Werkzeugmenue des Kopfs und steht im __actions-Slot - wie im
  // Essensplan und im Vorrat -, nicht mehr klebend am Ende der Chip-Leiste.
  // Eigener Traeger im Slot, weil der Router am Desktop den Primaerknopf in
  // denselben Slot dockt: ein replaceChildren() am Slot warfe ihn hinaus
  // (dieselbe Lehre wie #recipes-source-filter, test:hidden-cascade).
  const tools = container.querySelector('#shopping-tools');
  if (tools) {
    tools.replaceChildren();
    tools.insertAdjacentHTML('beforeend', actionsHtml);
    if (window.lucide) window.lucide.createIcons({ el: tools });
  }
}

/**
 * Die offene Liste an ein Haushaltsmitglied mailen (#944).
 *
 * ABSCHRIFT, KEIN ZUGANG. Der Dialog sagt beides: wie viele Artikel mitgehen
 * und dass es eine Momentaufnahme ist. Wer im Laden steht, haekelt nicht mit -
 * die Mail kann von spaeteren Aenderungen nichts wissen, und der Absender soll
 * das vorher lesen, nicht hinterher merken.
 *
 * Die Auswahl kennt nur Mitglieder MIT hinterlegter Adresse. Ein Name, den man
 * anklicken kann und der dann scheitert, ist eine Zusage, die nicht haelt; die
 * Route lehnt denselben Fall ohnehin ab, aber sie ist die zweite Verteidigung,
 * nicht die erste.
 */
async function openSendListDialog(container) {
  // Der Versand ist am Server ein POST und zaehlt dort als Schreiben.
  if (readOnly()) return;
  const listId = state.activeListId;
  const openCount = state.items.filter((item) => !checkedOf(item)).length;
  if (!openCount) {
    window.yuvomi.showToast(t('shopping.sendListEmpty'), 'warning');
    return;
  }

  let members = [];
  try {
    // Nicht `/family/members`: der zeigt dieselben Haushaltsmitglieder, prueft
    // aber nicht, ob jemand genau EINE gueltige Adresse hat. Dieser Endpunkt
    // fragt dieselbe Funktion wie die Versandroute, damit die Auswahl niemanden
    // anbietet, den der Server ablehnt - und umgekehrt.
    //
    // Sich selbst einzuschliessen ist Absicht: "schick mir die Liste aufs
    // Handy" ist derselbe Wunsch wie "schick sie meiner Mutter", und wer sie
    // sich selbst schickt, bekommt den Absendersatz nicht vorgesetzt (die
    // Route laesst ihn dann weg).
    const res = await api.get('/shopping/send-recipients');
    members = res.data || [];
  } catch {
    window.yuvomi.showToast(t('common.errorGeneric'), 'danger');
    return;
  }

  // WAEHREND DES LADENS KANN DIE LISTE GEWECHSELT HABEN. Der Dialog haelt
  // `listId` und die Artikelzahl von vorhin fest, sagt aber nirgends, welche
  // Liste er meint - er wuerde also die alte verschicken, waehrend auf dem
  // Bildschirm die neue steht. Bei etwas, das sich nicht zuruecknehmen laesst,
  // ist das der teuerste Fehler dieser Funktion.
  if (state.activeListId !== listId) return;

  if (!members.length) {
    window.yuvomi.showToast(t('shopping.sendListNoRecipients'), 'warning');
    return;
  }

  openModal({
    title: t('shopping.sendListTitle'),
    content: `
      <p class="form-hint">${esc(t('shopping.sendListDescription', { count: openCount }))}</p>
      <div class="form-group">
        <label class="form-label" for="send-list-recipient">${esc(t('shopping.sendListRecipient'))}</label>
        <select id="send-list-recipient" class="form-input">
          ${members.map((m) => `<option value="${m.id}">${esc(m.display_name)}</option>`).join('')}
        </select>
      </div>
      <p class="form-hint">${esc(t('shopping.sendListSnapshotHint'))}</p>
      <div class="modal-panel__footer modal-panel__footer--plain">
        <button type="button" class="btn btn--secondary" data-action="close-modal">${esc(t('common.cancel'))}</button>
        <button type="button" class="btn btn--primary" id="send-list-confirm">${esc(t('shopping.sendListSubmit'))}</button>
      </div>`,
    onSave(panel) {
      panel.querySelector('#send-list-confirm').addEventListener('click', async (event) => {
        const btn = event.currentTarget;
        const select = panel.querySelector('#send-list-recipient');
        const userId = Number(select.value);
        const name = members.find((m) => m.id === userId)?.display_name ?? '';
        btn.disabled = true;
        try {
          await api.post(`/shopping/${listId}/send`, { userId });
          closeModal({ force: true });
          // BEWUSST KEIN success-Toast. Die Erfolgsmeldungen der App zeigen
          // nach 50 Bestaetigungen keine Flaeche mehr (`TOAST_SUCCESS_MAX` in
          // utils/toast-show.js; angesagt werden sie weiter) - richtig fuer
          // Handlungen, deren Ergebnis auf dem Bildschirm steht und die man
          // taeglich wiederholt. Ein Mailversand
          // ist das Gegenteil: er passiert selten, laesst sich nicht
          // zuruecknehmen, und sein Ergebnis liegt in einem fremden Postfach.
          // Wer hier nichts sieht, weiss nicht, ob die Liste unterwegs ist.
          window.yuvomi.showToast(t('shopping.sendListSent', { name }), 'info');
        } catch (err) {
          // Der Server nennt seinen Grund maschinenlesbar mit, damit die drei
          // Absagen hier in der Sprache der Oberflaeche stehen koennen. Alles
          // Unerwartete bekommt den allgemeinen Satz des Versands, nie den
          // Meldungstext des Servers (#1909).
          const byReason = {
            recipient_no_email: 'shopping.sendListRecipientNoEmail',
            smtp_unconfigured: 'shopping.sendListSmtpMissing',
            nothing_open: 'shopping.sendListEmpty',
          }[err.data?.reason];
          if (byReason) window.yuvomi.showToast(t(byReason), 'danger');
          else reportError(err, container, 'shopping.sendListError');
          btn.disabled = false;
        }
      });
    },
  });
}

/**
 * Liste duplizieren (#1103) - "der Einkauf letzte Woche war gut, das meiste
 * davon wieder", ohne die alte Liste anzutasten. Kategorie und Handsortierung
 * werden serverseitig immer übernommen; nur Häkchen/Menge/Notiz sind Flags.
 *
 * Artikelzahlen für die neue Liste kommen aus den schon geladenen Artikeln der
 * QUELL-Liste statt aus einem zweiten `GET /shopping` - genau die Zahlen, die
 * gleich kopiert werden, sind bereits im Client, ein Neuladen der ganzen
 * Listen-Übersicht dafür wäre eine Anfrage für eine Antwort, die schon da ist.
 */
async function openDuplicateListDialog(container) {
  if (readOnly()) return;
  const source = state.activeList;
  if (!source) return;

  openModal({
    title: t('shopping.duplicateListTitle', { name: source.name }),
    content: `
      <div class="form-group">
        <label class="form-label" for="duplicate-list-name">${esc(t('shopping.duplicateListNameLabel'))}</label>
        <input class="form-input" type="text" id="duplicate-list-name"
               value="${esc(t('shopping.duplicateDefaultName', { name: source.name }))}" autocomplete="off">
      </div>
      <div class="form-group">
        <label class="toggle">
          <input type="checkbox" id="duplicate-reset-checked" checked>
          <span class="toggle__track"></span>
          <span>${esc(t('shopping.duplicateResetChecked'))}</span>
        </label>
      </div>
      <div class="form-group">
        <label class="toggle">
          <input type="checkbox" id="duplicate-keep-quantities" checked>
          <span class="toggle__track"></span>
          <span>${esc(t('shopping.duplicateKeepQuantities'))}</span>
        </label>
      </div>
      <div class="form-group">
        <label class="toggle">
          <input type="checkbox" id="duplicate-keep-notes" checked>
          <span class="toggle__track"></span>
          <span>${esc(t('shopping.duplicateKeepNotes'))}</span>
        </label>
      </div>
      <div class="modal-panel__footer modal-panel__footer--plain">
        <button type="button" class="btn btn--secondary" data-action="close-modal">${esc(t('common.cancel'))}</button>
        <button type="button" class="btn btn--primary" id="duplicate-list-confirm">${esc(t('shopping.duplicateSubmit'))}</button>
      </div>`,
    onSave(panel) {
      panel.querySelector('#duplicate-list-confirm').addEventListener('click', async (event) => {
        const btn = event.currentTarget;
        const name = panel.querySelector('#duplicate-list-name').value.trim();
        if (!name) {
          reportFieldError(panel.querySelector('#duplicate-list-name'), t('common.nameRequired'));
          return;
        }
        const resetChecked   = panel.querySelector('#duplicate-reset-checked').checked;
        const keepQuantities = panel.querySelector('#duplicate-keep-quantities').checked;
        const keepNotes      = panel.querySelector('#duplicate-keep-notes').checked;

        btn.disabled = true;
        try {
          const data = await api.post(`/shopping/${source.id}/duplicate`, {
            name, resetChecked, keepQuantities, keepNotes,
          });
          const itemTotal   = state.items.length;
          const itemChecked = resetChecked ? 0 : state.items.filter(checkedOf).length;
          state.lists.push({ ...data.data, item_total: itemTotal, item_checked: itemChecked });
          closeModal({ force: true });
          await switchList(data.data.id, container);
          refocusAfterRender();
        } catch (err) {
          reportError(err, container, 'shopping.duplicateError');
          btn.disabled = false;
        }
      });
    },
  });
}

function renderListContent(container) {
  const content = container.querySelector('#list-content');
  if (!content) return;
  content.removeAttribute('aria-busy');

  // Listen nicht ladbar: Fehlerzustand statt Leerzustand. Muss VOR der
  // `!state.activeList`-Prüfung stehen - ohne geladene Listen ist auch keine
  // aktiv, und der Leerzustand darunter hätte „Keine Listen" behauptet und mit
  // „Neue Liste erstellen" ausgerechnet eine schreibende Handlung als einzigen
  // Ausweg angeboten (Critique P0, 2026-07-30).
  if (state.listsError) {
    mountLoadError(content, {
      title: t('shopping.listsLoadError'),
      description: t('common.loadErrorDescription'),
      error: state.listsError,
      retryLabel: t('common.retry'),
      // Das Router-Signal reist mit: ein Aufbau aus dem Retry-Knopf gehoert
      // zur selben Route und muss mit ihr fallen (#976).
      onRetry: () => render(container, { user: { id: state.currentUserId }, signal: _routeSignal }),
    });
    return;
  }

  if (!state.activeList) {
    // Ohne aktive Liste gibt es nichts zu benennen: renderTabs lässt die
    // Aktionszone der Leiste dann weg, statt vier tote Menü-Einträge zu zeigen.
    // Geteilter Renderer (utils/empty-state.js), damit dieser Zustand dieselbe
    // Reihenfolge und Rolle trägt wie die drei Geschwister-Tabs.
    // Bei `read` bleibt nur der Titel: Beschreibung und Hinweis laden zum
    // Anlegen und Fuellen ein, und der Knopf, den sie meinen, entfaellt
    // (Regel 9 in utils/module-access.js).
    const ro = readOnly();
    mountEmptyState(content, {
      icon: 'shopping-cart',
      title: t('shopping.noLists'),
      description: ro ? undefined : t('shopping.noListsDescription'),
      // Nennt die EINGEHENDE Station des Kreislaufs (der Essensplan füllt die
      // Liste) - wie der Vorrat, dessen Hinweis auf den Einkauf zeigt. Dieser
      // Zustand war der einzige der vier ohne Hinweis (Critique 2026-07-29).
      hint: ro ? undefined : t('shopping.noListsHint'),
      action: ro ? null : {
        label: t('shopping.newListButton'),
        icon: 'plus',
        onClick: () => container.querySelector('[data-action="new-list"]')?.click(),
      },
    });
    return;
  }

  content.replaceChildren();
  content.insertAdjacentHTML('beforeend', `
    ${readOnly() ? '' : `<!-- Quick-Add -->
    <div class="quick-add">
      <form class="quick-add__form" id="quick-add-form" novalidate autocomplete="off">
        <div class="quick-add__input-wrap">
          <input class="quick-add__input" type="text" id="item-name-input"
                 placeholder="${t('shopping.itemNamePlaceholder')}" aria-label="${t('shopping.itemNameLabel')}" autocomplete="off">
          <div class="autocomplete-dropdown" id="autocomplete-dropdown" hidden></div>
        </div>
        <input class="quick-add__qty" type="text" id="item-qty-input"
               placeholder="${t('shopping.itemQtyPlaceholder')}" aria-label="${t('shopping.itemQtyLabel')}" autocomplete="off">
        <select class="quick-add__cat" id="item-cat-select" aria-label="${t('shopping.categoryLabel')}">
          ${state.categories.map((c) => `<option value="${esc(c.name)}" ${c.name === DEFAULT_CATEGORY_NAME ? 'selected' : ''}>${esc(categoryLabel(c.name))}</option>`).join('')}
        </select>
        <!-- Return-Glyphe statt eines zweiten "+" (Re-Critique 2026-09-28,
             A4 P2-4): das Plus gehoert der Kopf-Pille bzw. dem FAB. -->
        <button class="quick-add__btn" type="submit" aria-label="${t('shopping.addItemLabel')}">
          <i data-lucide="corner-down-left" class="icon-lg" aria-hidden="true"></i>
        </button>
      </form>
    </div>`}

    <!-- Die Sammelaktions-Leiste stand hier als statischer Block über der
         Liste. Seit Etappe 5 ist sie eine Pille in der unteren Shell-Zone
         (utils/bulk-pill.js) - der Grund steht dort und an .list-bulkbar in
         layout.css: 103px Listenfläche für einen einzigen abgehakten Artikel.
         Die alte Begründung („Geschwister der Liste, nicht Kind: mountItems()
         leert #items-list") ist damit erledigt statt umgezogen - was gar nicht
         mehr in dieser Seite hängt, kann von ihrem Rendern nicht getroffen
         werden. -->

    <!-- Artikel-Liste; Inhalt via mountItems(), damit der Leerzustand über den
         geteilten Renderer läuft statt als HTML-String hier drin. -->
    <div class="list-scroller page-scrollport items-list" id="items-list"></div>

    <!-- Ansage für Umsortierungen (#678), wie im Kategorie-Manager: das
         aria-label des Griffs allein ist zu leise - ob ein Screenreader die
         Label-Änderung am fokussierten Element vorliest, ist von Programm zu
         Programm verschieden. Eine Live-Region ist die verlässliche Zusage. -->
    <div class="sr-only" role="status" aria-live="polite" id="items-reorder-announce"></div>
  `);

  // Der Listenteil kommt aus updateItemsList - mountItems, Stagger,
  // Wischgesten, Sortierung und die Sammelaktions-Leiste, die erst dann
  // feststeht, wenn die abgehakten Artikel im DOM stehen.
  //
  // NICHT ein zweites Mal aufgezählt: die Aufzählung stand hier neben der in
  // updateItemsList und hatte genau einen Schritt verloren. `wireSwipeGestures`
  // lief nur im Nachlade-Pfad, also erst, wenn die Liste ein ZWEITES Mal gebaut
  // wurde - beim ersten Öffnen der Seite antwortete keine Zeile auf die Geste.
  // Der Aufruf stand seit dem Tag falsch, an dem die Geste eingeführt wurde.
  updateItemsList(container);

  // Für den ganzen Inhalt, nicht nur die Liste: Quick-Add und Kopfzeile tragen
  // eigene Icons. Der Lauf in updateItemsList hat die Zeilen schon ersetzt.
  if (window.lucide) window.lucide.createIcons({ el: content });
  wireAutocomplete(container);
  wireQuickAdd(container);
  syncQuickAddDisclosure(container, false);
}

/**
 * Füllt den Artikel-Container: entweder Kategorie-Gruppen oder den
 * Leerzustand über den geteilten Renderer.
 *
 * Der Leerzustand lag vorher als HTML-String in `renderItems()` und trug als
 * einziger im Modul ein handgezeichnetes Inline-SVG statt eines Lucide-Icons -
 * dieselbe Warenkorb-Form, nur mit eigener Strichstärke (Critique 2026-07-29).
 */
function mountItems(listEl, container) {
  if (!listEl) return;

  // Artikel nicht ladbar: eigener Fehler mit eigener Wiederholung. Die Liste
  // existiert und ist im Kopf benannt - nur ihr Inhalt fehlt, also lädt der
  // Retry auch nur diese eine Liste nach.
  if (state.itemsError) {
    mountLoadError(listEl, {
      title: t('shopping.itemsLoadError'),
      description: t('common.loadErrorDescription'),
      error: state.itemsError,
      retryLabel: t('common.retry'),
      onRetry: container
        ? () => switchList(state.activeListId, container)
        : undefined,
    });
    return;
  }

  if (!state.items.length) {
    // Bei `read` nur der Zustand: Beschreibung („Der Name genuegt ...") und
    // Hinweis (abgehakte Artikel in den Vorrat) meinen beide eine Handlung.
    // Der Hinweis nennt die Kapsel „In den Vorrat" und steht deshalb nur, wo
    // sie auch steht (#1607) - dieselbe Frage wie in updateCheckedActions().
    const ro = readOnly();
    mountEmptyState(listEl, {
      icon: 'shopping-cart',
      title: t('shopping.emptyList'),
      description: ro ? undefined : t('shopping.emptyListDescription'),
      hint: ro || !pantryTransferOffered() ? undefined : t('emptyHint.shopping'),
      action: ro ? null : {
        label: t('shopping.emptyAction'),
        icon: 'plus',
        onClick: () => document.querySelector('.page-fab')?.click(),
      },
    });
    return;
  }

  listEl.replaceChildren();
  // EINE HUELLE UM DIE GRUPPEN (R11 H5): sie ist die Flaeche, die am Desktop
  // in zwei Spalten packt (shopping.css, `.items-lanes`). Der Scroller selbst
  // kann das nicht - mit begrenzter Hoehe liefe Multicol seitlich ueber.
  // Mobil ist sie `display: contents` und aendert nichts.
  listEl.insertAdjacentHTML('beforeend', `<div class="items-lanes">${renderItems()}</div>`);
}

function renderItems() {
  const { groups, ticked } = listSections(state.items);
  pruneCollapsedCategories(groups);
  // Geteilte Gruppen-Grammatik (styles/list-row.css): .list-group ordnet,
  // .row-carrier trägt die Fläche und die Trennlinien. Die Zeilen selbst
  // sind flächenlos - vorher war Einkaufen eine Trennlinien-Liste und der Vorrat
  // eine Kartenliste, dieselbe Sache in zwei Paradigmen (Critique 2026-07-30).
  //
  // Gruppenkopf als echter Knopf im h2 (#1039, Muster aus tasks.js/#812): nur
  // ein <button> kennt die Tastatur und traegt aria-expanded ueberhaupt. Die
  // Zeilen (.row-carrier) bleiben bei [hidden] im DOM - ein Rerender wuerde
  // Sortable-Instanzen und Swipe-Closures verwerfen, nur um eine Gruppe
  // zuzuklappen.
  return groups.map(([cat, items], idx) => {
    const key = categoryStorageKey(cat);
    const collapsed = state.collapsedCategories.has(key);
    const rowsId = `shopping-category-rows-${idx}`;
    return `
    <div class="list-group item-category" data-category="${esc(cat)}" ${items.length ? '' : 'hidden'}>
      <h2 class="list-group__title">
        <button type="button" class="list-group__toggle" data-category-toggle="${esc(key)}"
                aria-expanded="${collapsed ? 'false' : 'true'}" aria-controls="${rowsId}">
          <i data-lucide="chevron-down" aria-hidden="true"
             class="list-group__chevron${collapsed ? ' list-group__chevron--collapsed' : ''}"></i>
          <i data-lucide="${catIcon(cat)}" class="icon-sm" aria-hidden="true"></i>
          <span>${esc(categoryLabel(cat))}</span>
        </button>
        <span class="list-group__count">${items.length}</span>
      </h2>
      <div class="row-carrier" id="${rowsId}" ${collapsed ? 'hidden' : ''}>
        ${items.map(renderItem).join('')}
      </div>
    </div>`;
  }).join('') + renderTickedSection(ticked);
}

/**
 * Der Abschnitt „Abgehakt" (#1816): EINE Gruppe am Listenende, von Haus aus
 * zu. Dieselbe Grammatik wie ein Kategoriekopf - Knopf im h2, Winkel, Zeichen,
 * Zaehlstand -, damit er sich bedient wie die Gruppen darueber.
 *
 * DER ZAEHLSTAND GEHOERT ZUM NAMEN DES KNOPFS (`aria-labelledby` auf Wort und
 * Zahl): zugeklappt ist die Zahl alles, was der Abschnitt ueber seinen Inhalt
 * sagt. Sie steht als eigener Knoten da, weil `syncGroupChrome` sie beim
 * Wandern einer Zeile fortschreibt.
 *
 * Steht auch leer im DOM (`hidden`): der erste abgehakte Artikel braucht
 * seinen Traeger, ohne dass die Liste neu gebaut wird.
 */
function renderTickedSection(ticked) {
  const open = state.tickedOpen;
  return `
    <div class="list-group item-ticked" ${ticked.length ? '' : 'hidden'}>
      <h2 class="list-group__title">
        <button type="button" class="list-group__toggle" data-ticked-toggle
                aria-expanded="${open ? 'true' : 'false'}" aria-controls="shopping-ticked-rows"
                aria-labelledby="shopping-ticked-label shopping-ticked-count">
          <i data-lucide="chevron-down" aria-hidden="true"
             class="list-group__chevron${open ? '' : ' list-group__chevron--collapsed'}"></i>
          <i data-lucide="check" class="icon-sm" aria-hidden="true"></i>
          <span id="shopping-ticked-label">${t('shopping.tickedSection')}</span>
        </button>
        <span class="list-group__count" id="shopping-ticked-count">${ticked.length}</span>
      </h2>
      <div class="row-carrier" id="shopping-ticked-rows" ${open ? '' : 'hidden'}>
        ${ticked.map(renderItem).join('')}
      </div>
    </div>`;
}

/**
 * Dezente Inline-Indikatoren (Progressive Disclosure): zeigen an, dass ein
 * Artikel zusätzliche Details (Link/Notiz) trägt, ohne die Zeile zu überladen.
 * Rein visuell (aria-hidden) — der Zugang läuft über den beschrifteten Details-Button.
 */
function renderItemMeta(item) {
  const bits = [];
  if (item.url)   bits.push('<i data-lucide="link" class="item-meta__icon" aria-hidden="true"></i>');
  if (item.notes) bits.push('<i data-lucide="sticky-note" class="item-meta__icon" aria-hidden="true"></i>');
  return bits.length ? `<span class="item-meta">${bits.join('')}</span>` : '';
}

// Wie viele Tags eine Zeile zeigt, bevor sie zusammenfasst - wie auf den
// Aufgabenkarten, die am 12.08.2026 aus demselben Grund von drei auf EINEN
// gegangen sind: die Etiketten standen dort in einer Metazeile, die umbrach,
// hier auf einer dritten Zeile. Beides macht aus einer 64px-Zeile eine mit 91.
const ITEM_TAGS_VISIBLE = 1;

/**
 * Gespiegelte VTODO-CATEGORIES eines Einkaufspostens (#586).
 *
 * Anzeige, keine Bedienung: die Etiketten gehören der CalDAV-Quellliste, Yuvomi
 * verwaltet sie hier nicht und schreibt sie auch nicht zurück. Deshalb <span>
 * statt Button - anders als in den Aufgaben, wo ein Klick danach filtert.
 */
function renderItemTags(tags) {
  if (!tags?.length) return '';
  const shown = tags.slice(0, ITEM_TAGS_VISIBLE);
  const rest  = tags.length - shown.length;
  const chips = shown.map((tag) => `<span class="list-row__tag">${esc(tag)}</span>`);
  if (rest > 0) {
    chips.push(`<span class="list-row__tag list-row__tag--more"
                      title="${esc(tags.slice(ITEM_TAGS_VISIBLE).join(', '))}">+${rest}</span>`);
  }
  // KEIN eigener Block mehr: die Etiketten stehen in der Metazeile neben der
  // Menge, nicht als dritte Zeile darunter. Als Block kosteten sie 27px in
  // jeder Zeile, die welche hat - gemessen 90,9px gegen 64px, und das war die
  // ganze Streuung des Einkaufs.
  return chips.join('');
}

/**
 * Traegt der Artikel etwas, das NUR im Bearbeiten-Dialog steht? Name, Menge,
 * Etiketten und (ueber die Gruppe) die Kategorie zeigt die Zeile selbst; Preis,
 * Laden, Link und Notiz nicht. Nur dann hat die Leseansicht bei `read` etwas zu
 * sagen, und nur dann bekommt die Zeile ihren Knopf - die Antwort folgt dem
 * DATENSATZ (Regel 2), ein Knopf ohne neuen Inhalt sagte nichts, was die Zeile
 * nicht schon sagt.
 */
function hasReadDetails(item) {
  return item.price_cents != null || Boolean(storeName(item)) || Boolean(item.url) || Boolean(item.notes);
}

/** Name des Ladens eines Artikels, leer, wenn keiner (mehr) gesetzt ist. */
function storeName(item) {
  if (item?.store_id == null) return '';
  return state.stores.find((st) => st.id === item.store_id)?.name ?? '';
}

/**
 * Der Haken als ZEICHEN (#1265 P4, Bauart `.task-status-btn--static`): ein
 * `span role="img"`, dessen Beschriftung den Zustand nennt, statt eines
 * deaktivierten Knopfs, der „abhaken" verspraeche. Kein `data-action`: der
 * Zeilenklick sucht den Knopf ueber genau dieses Attribut und findet so nichts.
 */
function itemStateLabel(item) {
  return `${item.name}: ${t(checkedOf(item) ? 'shopping.itemStateChecked' : 'shopping.itemStateOpen')}`;
}

function renderItemCheck(item, isDone) {
  if (readOnly()) {
    return `
        <span class="item-check item-check--static ${isDone ? 'item-check--checked' : ''}"
              role="img" aria-label="${esc(itemStateLabel(item))}">
          <i data-lucide="check" class="item-check__icon" aria-hidden="true"></i>
        </span>`;
  }
  return `
        <button class="item-check ${isDone ? 'item-check--checked' : ''}"
                data-action="toggle-item" data-id="${item.id}" data-checked="${checkedOf(item)}"
                aria-label="${isDone ? t('shopping.markUndoneLabel', { name: esc(item.name) }) : t('shopping.markDoneLabel', { name: esc(item.name) })}">
          <i data-lucide="check" class="item-check__icon" aria-hidden="true"></i>
        </button>`;
}

/**
 * Die Bedienzone bei `read`: hoechstens der Knopf zur Leseansicht, und nur,
 * wenn es dort etwas zu lesen gibt. Der Container bleibt auch leer stehen,
 * damit die Zeile ihre Form behaelt.
 */
function renderReadActions(item) {
  if (!hasReadDetails(item)) return '';
  return `
          <button class="row-action" data-action="item-details" data-id="${item.id}"
                  aria-label="${esc(readDetailsLabel(item.name))}">
            <i data-lucide="info" class="icon-md" aria-hidden="true"></i>
          </button>`;
}

function renderItem(item) {
  const isDone = Boolean(checkedOf(item));
  const ro = readOnly();
  return `
    <div class="swipe-row${ro ? ' swipe-row--static' : ''}" data-swipe-id="${item.id}" data-swipe-checked="${checkedOf(item)}">
      ${ro ? '' : `<div class="swipe-reveal swipe-reveal--done swipe-reveal--leading" aria-hidden="true">
        <i data-lucide="${isDone ? 'rotate-ccw' : 'check'}" class="icon-xl" aria-hidden="true"></i>
        <span>${isDone ? t('shopping.swipeBack') : t('shopping.swipeCheck')}</span>
      </div>
      <div class="swipe-reveal swipe-reveal--delete swipe-reveal--trailing" aria-hidden="true">
        <i data-lucide="trash-2" class="icon-xl" aria-hidden="true"></i>
        <span>${t('shopping.swipeDelete')}</span>
      </div>`}
      <div class="list-row shopping-item ${isDone ? 'shopping-item--checked' : ''}${ro ? ' shopping-item--static' : ''}"
           data-item-id="${item.id}">
        ${renderItemCheck(item, isDone)}
        <div class="list-row__main">
          <div class="list-row__name">${esc(item.name)}${renderItemMeta(item)}</div>
          ${item.quantity || item.tags?.length ? `<div class="list-row__meta">
            ${item.quantity ? `<span class="shopping-item__quantity">${esc(item.quantity)}</span>` : ''}
            ${renderItemTags(item.tags)}
          </div>` : ''}
        </div>
        <!-- Geteilte .row-action-Grammatik aus layout.css (app-weit von sieben
             Modulen genutzt), gruppiert in der geteilten .list-row__actions -
             vorher hingen die zwei Buttons als direkte Flex-Kinder in der Zeile,
             wodurch die Bedienzone in jedem Tab anders zusammengesetzt war. -->
        <div class="list-row__actions">
          ${ro ? renderReadActions(item) : `<!-- Griff für die Handsortierung (#678). Ein BUTTON, kein role="img"
               wie im Kategorie-Manager: dort steht daneben ein Auf/Ab-Paar als
               Tastaturpfad, hier trägt der Griff ihn selbst (Pfeiltasten bei
               Fokus). Die Einkaufszeile hat schon Abhaken, Details, Löschen und
               zwei Wischgesten - zwei weitere Knöpfe hätten die Bedienzone auf
               dem Handy zugestellt. -->
          <button class="row-action list-row__drag" data-action="reorder-handle" data-id="${item.id}"
                  aria-label="${t('shopping.reorderHandle', { name: esc(item.name) })}"
                  title="${t('shopping.reorderHandleHint')}">
            <i data-lucide="grip-vertical" class="icon-md" aria-hidden="true"></i>
          </button>
${/* ZWEI SICHTBAR, DER REST IM MEHR-KNOPF (Entscheidung 2026-10-07,
               utils/row-action.js): Stift und Papierkorb standen in jeder der
               23 Zeilen - drei Dauer-Aktionen neben dem Haken. Bearbeiten und
               Loeschen sind jetzt Eintraege mit Wort; Loeschen bleibt
               widerrufbar (Undo-Toast) und per Wischen erreichbar. */ ''}
          ${rowMenuHtml({
            id: `shopping-item-menu-${item.id}`,
            label: t('common.moreActionsNamed', { name: item.name }),
            items: [
              { action: 'item-details', id: item.id, icon: 'pencil', label: t('common.edit') },
              { action: 'delete-item', id: item.id, icon: 'trash-2', label: t('common.delete'), danger: true },
            ],
          })}`}
        </div>
      </div>
    </div>`;
}

// --------------------------------------------------------
// Autocomplete
// --------------------------------------------------------

let autocompleteTimeout = null;

/** Gleicher Name, Gross-/Kleinschreibung egal - wie der Vorschlag selbst sucht (COLLATE NOCASE). */
function sameName(a, b) {
  return String(a ?? '').trim().toLowerCase() === String(b ?? '').trim().toLowerCase();
}

/**
 * Der abgehakte Artikel dieses Namens auf der OFFENEN Liste, sonst undefined.
 *
 * NUR, WENN DER BESTAND DIESER LISTE GEHOERT. Nach einem Listenwechsel traegt
 * `state.items` bis zum Ende des Ladens noch die verlassene Liste
 * (`_itemsListId`); ein Treffer dort holte einen Artikel auf einem Zettel
 * zurueck, den niemand mehr ansieht, und auf dem offenen entstuende nichts.
 * Dann gilt der Name als neu und wird auf der offenen Liste angelegt.
 */
function tickedItemNamed(name) {
  if (!String(name ?? '').trim()) return undefined;
  if (_itemsListId !== state.activeListId) return undefined;
  return state.items
    .filter((i) => checkedOf(i) && sameName(i.name, name))
    .sort((a, b) => byRank(a, b))[0];
}

/**
 * Holt eine abgehakte Zeile zurueck, statt eine zweite gleichen Namens
 * anzulegen (#1816). Der Haken faellt ueber denselben Weg wie ein Tipp auf die
 * Zeile (`toggleShoppingItem`: Absicht, Zaehler, Fehlerbild).
 *
 * WAS DAS FORMULAR SAGT, UEBERSCHREIBT; WAS ES NICHT SAGT, BLEIBT. Eine
 * getippte Menge ersetzt die der Zeile, ein leeres Mengenfeld laesst sie
 * stehen. Die Kategorie reist nur mit, wenn sie im Formular GEWAEHLT wurde
 * (`category` ist sonst undefined): das Auswahlfeld zeigt immer irgendeinen
 * Wert, und eine Zeile, deren Kategorie es dort gar nicht (mehr) gibt, wuerde
 * sonst still auf den zufaellig angezeigten umgeschrieben.
 *
 * @returns {Promise<boolean>} ob die Zeile wieder offen ist
 */
async function reviveTickedItem(container, item, { quantity, category }) {
  const id = item.id;
  const changes = {};
  if (quantity && quantity !== (item.quantity ?? null)) changes.quantity = quantity;
  if (category && category !== item.category) changes.category = category;
  const hatAenderung = Object.keys(changes).length > 0;

  // HAKEN UND FELDER IN EINER ANFRAGE. Als zwei Anfragen gab es ein Halb: der
  // Haken fiel, das Schreiben der Menge scheiterte, und das Formular meldete
  // trotzdem "ist wieder auf der Liste" und leerte sich - die getippte Menge
  // war weg und die Fehlermeldung von der Erfolgsmeldung ueberschrieben.
  const antwort = await toggleShoppingItem(id, 1, container, {
    settleNow: true, extra: hatAenderung ? changes : null,
  });

  const current = state.items.find((i) => i.id === id);
  if (!current || checkedOf(current)) return false;

  if (hatAenderung && antwort?.data) {
    // Den Haken traegt die Absicht bzw. die Bestaetigung von eben - die
    // Antwort hier kann ihn nicht besser kennen.
    Object.assign(current, antwort.data, { is_checked: current.is_checked });
    if ('category' in changes) updateItemsList(container);
    else refreshItemName(container, current);
  }
  return true;
}

/**
 * Übernimmt eine gewählte Vorschlagszeile ins Formular (#1103): Name immer,
 * Kategorie/Menge nur, wenn die Zeile sie kennt. Eine Kategorie, die es im
 * Haushalt nicht mehr gibt (umbenannt/gelöscht seit dem letzten Einkauf),
 * bleibt beim aktuellen Stand des Feldes stehen, statt eine ungültige Option
 * zu erzwingen - `<select>` würde sie ohnehin nur stillschweigend ignorieren.
 */
function applyAutocompleteSuggestion(container, el) {
  const nameInput = container.querySelector('#item-name-input');
  const qtyInput  = container.querySelector('#item-qty-input');
  const catSelect = container.querySelector('#item-cat-select');
  if (!nameInput) return;

  // Was hier ins Kategoriefeld kommt, hat niemand gewaehlt (siehe reviveTickedItem).
  quickAddCategoryChosen = false;

  // STEHT DER NAME ABGEHAKT AUF DIESER LISTE, MEINT DIE WAHL DIESE ZEILE (#1816).
  // Das Formular zeigt dann IHRE Werte, nicht die des juengsten Namensvetters
  // auf irgendeiner Liste: was beim Absenden zurueckkommt, soll dastehen. Ein
  // Merker ist dafuer nicht noetig - das Absenden gleicht den Namen selbst ab,
  // gewaehlt oder getippt.
  const ticked = tickedItemNamed(el.dataset.name);
  if (ticked) {
    nameInput.value = ticked.name;
    if (catSelect && [...catSelect.options].some((o) => o.value === ticked.category)) {
      catSelect.value = ticked.category;
    }
    if (qtyInput && ticked.quantity) qtyInput.value = ticked.quantity;
    return;
  }

  nameInput.value = el.dataset.name ?? '';
  if (catSelect && el.dataset.category
    && [...catSelect.options].some((o) => o.value === el.dataset.category)) {
    catSelect.value = el.dataset.category;
  }
  if (qtyInput && el.dataset.quantity) {
    qtyInput.value = el.dataset.quantity;
  }
}

function wireAutocomplete(container) {
  const input    = container.querySelector('#item-name-input');
  const dropdown = container.querySelector('#autocomplete-dropdown');
  if (!input || !dropdown) return;

  let activeIdx = -1;

  input.addEventListener('input', () => {
    clearTimeout(autocompleteTimeout);
    const q = input.value.trim();
    if (q.length < 1) { dropdown.hidden = true; return; }

    autocompleteTimeout = setTimeout(async () => {
      try {
        const data = await api.get(`/shopping/suggestions?q=${encodeURIComponent(q)}`);
        const suggestions = data.data ?? [];
        if (!suggestions.length) { dropdown.hidden = true; return; }

        dropdown.replaceChildren();
        // Angezeigt wird nur der Name - Kategorie/Menge reisen unsichtbar als
        // data-Attribute mit und füllen beim Wählen die übrigen Felder (#1103).
        // Ein Name, der abgehakt auf dieser Liste steht, sagt es (#1816): die
        // Wahl holt dann die Zeile zurueck, statt eine zweite anzulegen.
        dropdown.insertAdjacentHTML('beforeend', suggestions.map((s, i) =>
          `<div class="autocomplete-item" data-idx="${i}" data-name="${esc(s.name)}"
                data-category="${esc(s.category ?? '')}" data-quantity="${esc(s.quantity ?? '')}"><span>${esc(s.name)}</span>${
            tickedItemNamed(s.name) ? `<span class="autocomplete-item__state">${esc(t('shopping.itemStateChecked'))}</span>` : ''}</div>`
        ).join(''));
        dropdown.hidden = false;
        activeIdx = -1;

        dropdown.querySelectorAll('.autocomplete-item').forEach((el) => {
          el.addEventListener('mousedown', (e) => {
            e.preventDefault();
            applyAutocompleteSuggestion(container, el);
            dropdown.hidden = true;
          });
        });

        if (window.lucide) window.lucide.createIcons({ el: dropdown });
      } catch { dropdown.hidden = true; }
    }, 200);
  });

  input.addEventListener('keydown', (e) => {
    if (dropdown.hidden) return;
    const items = dropdown.querySelectorAll('.autocomplete-item');
    if (!items.length) return;

    if (e.key === 'ArrowDown') {
      e.preventDefault();
      activeIdx = Math.min(activeIdx + 1, items.length - 1);
      items.forEach((el, i) => el.classList.toggle('autocomplete-item--active', i === activeIdx));
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      activeIdx = Math.max(activeIdx - 1, 0);
      items.forEach((el, i) => el.classList.toggle('autocomplete-item--active', i === activeIdx));
    } else if (e.key === 'Enter' && activeIdx >= 0) {
      e.preventDefault();
      applyAutocompleteSuggestion(container, items[activeIdx]);
      dropdown.hidden = true;
    } else if (e.key === 'Escape') {
      dropdown.hidden = true;
    }
  });

  input.addEventListener('blur', () => {
    setTimeout(() => { dropdown.hidden = true; }, 150);
  });
}

// --------------------------------------------------------
// Quick-Add Form
// --------------------------------------------------------

/**
 * Zeigt kurzes Checkmark-Feedback auf dem +-Button (700ms).
 * Verwendet DOM-API statt innerHTML um XSS-Risiken zu vermeiden.
 * @param {HTMLButtonElement|null} btn
 */
function _flashAddBtn(btn) {
  if (!btn) return;
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('width', '16');
  svg.setAttribute('height', '16');
  svg.setAttribute('viewBox', '0 0 24 24');
  svg.setAttribute('fill', 'none');
  svg.setAttribute('stroke', 'currentColor');
  svg.setAttribute('stroke-width', '2.5');
  svg.setAttribute('aria-hidden', 'true');
  const poly = document.createElementNS('http://www.w3.org/2000/svg', 'polyline');
  poly.setAttribute('points', '20 6 9 17 4 12');
  svg.appendChild(poly);

  const saved = [...btn.childNodes];
  btn.classList.add('btn--success');
  btn.replaceChildren(svg);
  setTimeout(() => {
    btn.classList.remove('btn--success');
    btn.replaceChildren(...saved);
    if (window.lucide) window.lucide.createIcons({ el: btn });
  }, 700);
}

// --------------------------------------------------------
// Quick-Add als Disclosure (nur Touch)
// --------------------------------------------------------

/**
 * Auf Touch ist das Quick-Add eingeklappt und der FAB öffnet es.
 *
 * WARUM: Der Einkauf trug mobil 439 von 852px Chrome, bevor ein Artikel sichtbar
 * war (52%; bei 320px 495 von 720 = 69%). Das zweizeilige Quick-Add ist davon
 * 126px - und es ist der einzige Tab, dessen FAB kein Formular öffnet, sondern
 * nur ein bereits sichtbares Feld fokussiert. Ein Griff löst beides: der FAB tut
 * dasselbe wie in Mahlzeiten, Rezepten und Vorrat, und die Liste beginnt weiter
 * oben (Critique 2026-07-30, P1).
 *
 * KEIN BOTTOM-SHEET, obwohl der FAB unten sitzt und die Tastatur unten aufgeht:
 * das Feld bleibt an seinem Platz über der Liste, wird nur enthüllt und
 * eingescrollt. Ein Sheet wäre die schönere Geste und ein zweiter Overlay-Typ mit
 * eigenem Focus-Trap - „Modal als erster Gedanke" ist in diesem Projekt ein
 * ausdrücklich verbotenes Muster, und die Eingabe gehört sichtbar zur Liste, in
 * die sie schreibt.
 *
 * Der Zustand hängt an `.shopping-page--adding` (siehe shopping.css) statt an
 * einem `hidden` am Formular: das Kriterium ist die Zeigerfähigkeit, und die
 * kennt nur CSS. JS setzt die Absicht, CSS entscheidet, ob sie überhaupt eine
 * Wirkung hat - auf Desktop ist die Klasse ein No-op.
 *
 * @param {Element} container
 * @param {boolean} open
 */
/** Letzte Absicht des Quick-Add (offen/zu) - ein Zuklappen, das ein Oeffnen ueberholt hat, raeumt nicht mehr ab. */
let quickAddOpenIntent = false;

function syncQuickAddDisclosure(container, open) {
  const page = container.querySelector('.shopping-page');
  const fab = findPageFab('fab-new-item');
  if (!page || !fab) return;

  const collapsible = window.matchMedia('(hover: none)').matches && Boolean(state.activeList);
  const wasOpen = page.classList.contains('shopping-page--adding');
  const nowOpen = collapsible && open;
  quickAddOpenIntent = nowOpen;
  // DAS FELD ZIEHT AUF UND KLAPPT ZU (R16, Bewegung). Vorher schaltete nur
  // `display` um: die Liste darunter sprang um die Hoehe des Formulars (127px
  // bei 390). Der ZUSTAND bleibt die Klasse; die Bewegung liegt davor bzw.
  // dahinter, und wo nichts animiert (kein `animate`, reduzierte Bewegung -
  // dann loest collapseOut sofort auf), faellt sie im selben Takt wie bisher.
  const quick = page.querySelector?.('.quick-add') ?? null;
  const canAnimate = typeof quick?.animate === 'function';
  if (wasOpen && !nowOpen && canAnimate) {
    collapseOut(quick).then(() => {
      // Inzwischen wieder geoeffnet: das Oeffnen hat schon aufgeraeumt.
      if (quickAddOpenIntent) return;
      page.classList.remove('shopping-page--adding');
      // collapseOut haelt die Hoehe 0 (fill: forwards) - nach `display: none` verwerfen.
      quick.getAnimations?.().forEach((anim) => anim.cancel());
      quick.style.overflow = '';
    });
  } else {
    page.classList.toggle('shopping-page--adding', nowOpen);
    if (nowOpen && canAnimate) {
      quick.getAnimations?.().forEach((anim) => anim.cancel());
      quick.style.overflow = '';
      if (!wasOpen) expandIn(quick);
    }
  }

  // `aria-expanded` NUR wo der Knopf tatsächlich etwas aufklappt. Auf Desktop
  // fokussiert er ein sichtbares Feld; ein „eingeklappt" zu melden, was gar nicht
  // eingeklappt ist, wäre eine Falschaussage an den Screenreader.
  if (collapsible) {
    fab.setAttribute('aria-expanded', String(open));
    fab.setAttribute('aria-controls', 'quick-add-form');
  } else {
    fab.removeAttribute('aria-expanded');
    fab.removeAttribute('aria-controls');
  }
}

/**
 * Setzt die Kategorie-Auswahl des Quick-Add auf den Standard zurueck.
 *
 * Die Kategorie faellt nach dem Anlegen auf den Standard zurueck (#548:
 * neu = Sonstiges), statt fuer den NAECHSTEN, unverwandten Artikel stehen zu
 * bleiben. Ohne diesen Rueckfall blieb sie an der zuletzt gewaehlten
 * Kategorie haengen - ob von Hand gewaehlt oder von einem Vorschlag
 * uebernommen (applyAutocompleteSuggestion) - und ein danach eingetippter
 * Artikel landete dort, nicht in Sonstiges (gemeldet 2026-09-11: "Toast"
 * landete in "Milchprodukte", weil zuvor ein Milch-Vorschlag gewaehlt wurde).
 *
 * Eigene Funktion statt Inline-Zweig im Submit-Handler, damit das Verhalten
 * testbar ist (Review #1165: die reine Textprobe blieb auch bei totem Code
 * gruen). Fehlt "Sonstiges" (umbenannt/geloescht), bleibt die Auswahl stehen -
 * ein ungueltiger Wert im <select> waere schlimmer als eine stehende Kategorie.
 *
 * @param {HTMLSelectElement} catSelect
 */
function resetQuickAddCategory(catSelect) {
  quickAddCategoryChosen = false;
  if ([...catSelect.options].some((o) => o.value === DEFAULT_CATEGORY_NAME)) {
    catSelect.value = DEFAULT_CATEGORY_NAME;
  }
}

/**
 * Hat jemand die Kategorie im Eingabefeld GEWAEHLT? Das Feld zeigt immer einen
 * Wert - den Standard, oder was ein Vorschlag hineingesetzt hat. Nur eine
 * Wahl von Hand ist eine Aussage ueber den Artikel; sie faellt mit jedem
 * Zuruecksetzen und jeder Uebernahme aus einem Vorschlag.
 */
let quickAddCategoryChosen = false;

function wireQuickAdd(container) {
  const form = container.querySelector('#quick-add-form');
  if (!form) return;

  // Esc klappt zu und gibt den Fokus an den FAB zurück - dieselbe Zusage wie im
  // Modal, wo Esc schließt und den Auslöser wieder fokussiert.
  form.addEventListener('keydown', (e) => {
    if (e.key !== 'Escape') return;
    const page = container.querySelector('.shopping-page');
    if (!page?.classList.contains('shopping-page--adding')) return;
    e.stopPropagation();
    syncQuickAddDisclosure(container, false);
    findPageFab('fab-new-item')?.focus();
  });

  container.querySelector('#item-cat-select')?.addEventListener?.('change', () => { quickAddCategoryChosen = true; });

  // EIN ABSENDEN ZUR ZEIT. Enter zweimal schnell hintereinander schickte sonst
  // zweimal: das erste holt die abgehakte Zeile zurueck, das zweite findet sie
  // schon offen und legt eine zweite an.
  let submitting = false;

  form.addEventListener('submit', async (e) => {
    e.preventDefault();
    if (submitting) return;
    const nameInput = container.querySelector('#item-name-input');
    const qtyInput  = container.querySelector('#item-qty-input');
    const catSelect = container.querySelector('#item-cat-select');

    const name     = nameInput.value.trim();
    const quantity = qtyInput.value.trim() || null;
    const category = catSelect.value;

    if (!name) { nameInput.focus(); return; }

    submitting = true;
    try {
      // Steht der Name abgehakt auf dieser Liste, kommt DIESE Zeile zurueck
      // (#1816) - gewaehlt aus dem Vorschlag oder von Hand getippt, verglichen
      // wie der Vorschlag sucht. Jeder andere Name wird angelegt.
      const revive = tickedItemNamed(name);
      if (revive) {
        const back = await reviveTickedItem(container, revive, {
          quantity, category: quickAddCategoryChosen ? category : undefined,
        });
        if (!back) return;
        // Die Zeile taucht irgendwo in der Liste auf, nicht unter dem Feld:
        // ein Satz sagt, was aus der Eingabe geworden ist.
        window.yuvomi.showToast(t('shopping.itemBackToast', { name: revive.name }), 'info');
      } else {
        const data = await api.post(`/shopping/${state.activeListId}/items`, { name, quantity, category });
        acknowledgeOwnChange(data);
        state.items.push(data.data);
        // Einfügen in DOM ohne komplettes Re-Render
        updateItemsList(container);
        updateListCounter(state.activeListId, 1, 0);
        renderTabs(container);
      }
      nameInput.value = '';
      qtyInput.value  = '';
      resetQuickAddCategory(catSelect);
      // Erfolgs-Feedback auf dem +-Button (DOM-API, kein innerHTML)
      _flashAddBtn(form.querySelector('.quick-add__btn'));
      nameInput.focus();
      nameInput.classList.add('quick-add__input--flash');
      nameInput.addEventListener('animationend', () => nameInput.classList.remove('quick-add__input--flash'), { once: true });
    } catch (err) {
      reportError(err, container);
    } finally {
      submitting = false;
    }
  });
}

// --------------------------------------------------------
// Swipe-Affordance Hint (Long Loop)
// Zeigt den Nudge-Hinweis maximal 3x (gespeichert in localStorage).
// --------------------------------------------------------

// --------------------------------------------------------
// Handsortierung innerhalb einer Kategorie (#678)
// --------------------------------------------------------

/** Laufende Sortable-Instanzen, damit ein Neuaufbau der Liste sie abräumt. */
let itemSortables = [];

function destroyItemSortables() {
  itemSortables.forEach((inst) => { try { inst.destroy(); } catch { /* schon abgeräumt */ } });
  itemSortables = [];
}

/** Ziehbare (= nicht abgehakte) Zeilen einer Gruppe in DOM-Reihenfolge. */
function movableRows(rowsEl) {
  return Array.from(rowsEl.querySelectorAll(':scope > .swipe-row:not([data-swipe-checked="1"])'));
}

/**
 * Schreibt Position und Gesamtzahl in die Griff-Beschriftungen einer Gruppe.
 *
 * Nach jedem Zug erneut: der Griff ist bei der Tastaturbedienung das fokussierte
 * Element, und seine Beschriftung ist die einzige Rückmeldung darüber, wo der
 * Artikel jetzt steht. Ein statisches „Reihenfolge ändern" ließe Screenreader-
 * Nutzer nach dem Tastendruck ohne Bestätigung zurück.
 */
function refreshHandleLabels(rowsEl) {
  if (!rowsEl) return;
  const rows = movableRows(rowsEl);
  rows.forEach((row, idx) => {
    const handle = row.querySelector('.list-row__drag');
    const name   = row.querySelector('.list-row__name')?.textContent?.trim() ?? '';
    if (!handle) return;
    handle.removeAttribute('disabled');
    handle.setAttribute('aria-label', `${t('shopping.reorderHandle', { name })}, ${
      t('shopping.reorderPosition', { index: idx + 1, total: rows.length })}`);
  });
  // Abgehakte Artikel sortieren sich nicht: sie stehen im Abschnitt am
  // Listenende (#1816; bis zum Umzug noch kurz in ihrer Kategorie), ein Zug an
  // ihnen wäre folgenlos. Der Griff bleibt sichtbar, damit die Zeile ihre Form
  // behält.
  //
  // Beide Richtungen in EINER Funktion: das Zurückholen eines Artikels ist so
  // alltäglich wie das Abhaken, und ein nur gesetztes `disabled` hätte den Griff
  // bis zum nächsten Voll-Render tot gelassen.
  rowsEl.querySelectorAll(':scope > [data-swipe-checked="1"] .list-row__drag')
    .forEach((handle) => handle.setAttribute('disabled', ''));
}

/**
 * Sagt die neue Position einer bewegten Zeile über die Live-Region an.
 * Nutzt bewusst `category.reorderAnnounce` mit: der Satz ist wortgleich, und
 * eine zweite Fassung derselben Aussage wäre 24 Übersetzungen, die
 * auseinanderlaufen können.
 */
function announceItemMove(container, row) {
  const el = container?.querySelector('#items-reorder-announce');
  if (!el || !row) return;
  const rows = movableRows(row.parentElement);
  const idx  = rows.indexOf(row);
  if (idx === -1) return;
  el.textContent = t('category.reorderAnnounce', {
    name:     row.querySelector('.list-row__name')?.textContent?.trim() ?? '',
    position: idx + 1,
    total:    rows.length,
  });
}

/** Kategorien mit laufender Sicherung: Name -> { again: boolean }. */
const orderRuns = new Map();
/** Je Kategorie ALLE ihre Artikel beim letzten Zug (#1816). Was davon nicht im
 *  Traeger steht, haengt die Anfrage hinten an - das Abgehakte im Abschnitt am
 *  Listenende, aber auch eine eben zurueckgeholte Zeile, die dort noch auf die
 *  Pause wartet. Deshalb kein Filter auf den Haken: der Rest ist "nicht im
 *  Traeger", nicht "abgehakt". */
const tickedTails = new Map();

/**
 * Einen Sicherungslauf ausführen: liest die Reihenfolge JETZT aus dem DOM.
 *
 * `listId` kommt vom Einreihen und nicht aus `state.activeListId`: wechselt der
 * Nutzer die Liste, während eine Nachfolge aussteht, hält `groupEl` noch die
 * abgehängten Zeilen der alten Liste. Deren IDs gegen die inzwischen aktive
 * Liste zu schicken, quittiert die Route zu Recht mit 400 - gemeint war der Zug
 * in der alten Liste, und dorthin gehört er auch gesichert.
 */
async function sendItemOrder(groupEl, container, listId) {
  const rowsEl   = groupEl.querySelector('.row-carrier');
  const category = groupEl.dataset.category;
  if (!rowsEl) return true;

  // Alle Artikel der Kategorie, auch die abgehakten: die Route verlangt die
  // vollständige Gruppe, sonst kollidieren die neuen Ränge mit den alten.
  // Die abgehakten stehen seit #1816 nicht mehr in diesem Träger, sondern im
  // Abschnitt am Listenende - sie kommen aus dem Bestand dazu und hinten an,
  // wo der Server sie ohnehin einordnet (is_checked vor sort_order).
  const order = Array.from(rowsEl.querySelectorAll(':scope > .swipe-row'))
    .map((row) => Number(row.dataset.swipeId));
  if (!order.length) return true;
  const inCarrier = new Set(order);
  for (const id of tickedTails.get(category) ?? []) if (!inCarrier.has(id)) order.push(id);

  try {
    const data = await api.patch(`/shopping/${listId}/items/reorder`, { category, order });
    acknowledgeOwnChange(data);
    // Nur den State nachziehen, nicht neu zeichnen: das DOM steht bereits
    // richtig, und ein Re-Render würde den Fokus vom Griff nehmen - mitten in
    // einer Tastaturbedienung wäre das das Ende der Bedienkette.
    //
    // Und nur, solange dieselbe Liste offen ist: die Antwort trägt die Artikel
    // VON `listId`, ein zwischenzeitlicher Listenwechsel bekäme sonst den
    // Bestand der alten Liste in seinen State geschrieben.
    if (listId === state.activeListId) state.items = data.data ?? state.items;
    return true;
  } catch (err) {
    // Fehler einer Liste, die gar nicht mehr offen ist, nicht dem Nutzer
    // vorlegen und erst recht nicht die sichtbare Liste dafür neu bauen.
    if (listId !== state.activeListId) return false;
    reportError(err, container);
    updateItemsList(container);
    return false;
  }
}

/**
 * Neue Reihenfolge einer Gruppe sichern. Geteilter Persistenz-Pfad von Drag und
 * Pfeiltasten - beide haben das DOM vorher schon umgestellt, deshalb baut der
 * Fehlerfall die Liste aus dem unveränderten State neu auf.
 *
 * JE KATEGORIE IMMER NUR EINE LAUFENDE ANFRAGE. Zwei schnell nacheinander
 * gedrückte Pfeiltasten schickten sonst zwei PATCHes parallel los, und es
 * entschied die Ankunftsreihenfolge beim Server statt die Bedienreihenfolge:
 * traf der erste zuletzt ein, schrieb er den Zwischenstand fest, das DOM zeigte
 * aber den zweiten Zug. Der Nutzer sah seine Reihenfolge und bekam beim
 * nächsten Laden eine andere. Bewusst als Warteschlange und nicht als Entprellung:
 * die Sicherung bleibt sofort, nur eben der Reihe nach.
 *
 * Weitere Züge während eines Laufs werden zu EINER Nachfolge zusammengefasst -
 * die liest die dann aktuelle Reihenfolge, also genügt sie für beliebig viele.
 *
 * @param {HTMLElement} [movedRow] - die bewegte Zeile, für die Ansage
 */
function persistItemOrder(groupEl, container, movedRow) {
  const category = groupEl?.dataset.category;
  if (!groupEl || !category) return;

  refreshHandleLabels(groupEl.querySelector('.row-carrier'));
  announceItemMove(container, movedRow);

  // Die Kategorie wird JETZT gelesen, beim Zug, solange der Bestand zu dieser
  // Liste gehoert - der Lauf selbst kann einen Listenwechsel ueberdauern.
  tickedTails.set(category, state.items
    .filter((i) => categoryOf(i) === category)
    .map((i) => i.id));

  const running = orderRuns.get(category);
  if (running) { running.again = true; return; }

  const run    = { again: false };
  const listId = state.activeListId;
  orderRuns.set(category, run);
  (async () => {
    try {
      let ok = true;
      do {
        run.again = false;
        ok = await sendItemOrder(groupEl, container, listId);
      } while (run.again && ok);   // nach einem Fehler hat updateItemsList das DOM zurückgesetzt
    } finally {
      orderRuns.delete(category);
    }
  })();
}

/**
 * Verschiebt eine Zeile um einen Platz und hält den Fokus auf ihrem Griff.
 * @param {HTMLElement} row
 * @param {-1|1} delta
 */
function moveItemRow(row, delta, container) {
  const rowsEl = row.parentElement;
  const rows   = movableRows(rowsEl);
  const idx    = rows.indexOf(row);
  const target = idx + delta;
  if (idx === -1 || target < 0 || target >= rows.length) return;

  if (delta < 0) rowsEl.insertBefore(row, rows[target]);
  else           rowsEl.insertBefore(row, rows[target].nextSibling);

  vibrate(15);
  row.querySelector('.list-row__drag')?.focus();
  persistItemOrder(rowsEl.closest('.list-group'), container, row);
}

/**
 * Verdrahtet je Kategorie-Gruppe das Ziehen und die Pfeiltasten am Griff.
 *
 * Je Gruppe eine eigene Instanz und kein `group`-Verbund: ein Zug von „Obst"
 * nach „Backwaren" wäre ein Kategoriewechsel, keine Umsortierung - dafür gibt es
 * den Detail-Dialog, und die Ränge gelten ohnehin je Kategorie.
 */
function wireItemReorder(container) {
  const listEl = container.querySelector('#items-list');
  if (!listEl) return;
  destroyItemSortables();

  listEl.querySelectorAll('.list-group').forEach((groupEl) => {
    const rowsEl = groupEl.querySelector('.row-carrier');
    if (!rowsEl) return;
    refreshHandleLabels(rowsEl);
    // „Abgehakt" sortiert sich nicht: der Abschnitt mischt Kategorien, und die
    // Ränge gelten je Kategorie. Seine Griffe hat refreshHandleLabels gesperrt.
    if (groupEl.classList.contains('item-ticked')) return;

    makeSortable(rowsEl, {
      handle: '.list-row__drag',
      draggable: '.swipe-row',
      // Abgehaktes bleibt liegen: es steht am Ende der Kategorie, und ein Zug
      // daran würde beim nächsten Laden zurückspringen.
      filter: '[data-swipe-checked="1"]',
      onEnd: (evt) => persistItemOrder(groupEl, container, evt?.item),
    }).then((inst) => { if (inst) itemSortables.push(inst); })
      .catch(() => { /* ohne SortableJS bleibt der Tastaturpfad */ });
  });

  // Tastaturpfad, delegiert: derselbe Persistenz-Handler wie das Drag-Ende.
  // Einmal pro #items-list-Element - mountItems() tauscht nur dessen Inhalt aus,
  // ein Listener pro Aufruf hätte sich mit jedem Nachladen gestapelt.
  if (listEl.dataset.reorderWired) return;
  listEl.dataset.reorderWired = '1';
  listEl.addEventListener('keydown', (e) => {
    if (e.key !== 'ArrowUp' && e.key !== 'ArrowDown') return;
    const handle = e.target.closest?.('.list-row__drag');
    if (!handle || handle.disabled) return;
    e.preventDefault();
    moveItemRow(handle.closest('.swipe-row'), e.key === 'ArrowUp' ? -1 : 1, container);
  });
}

// --------------------------------------------------------
// Swipe-Gesten
// --------------------------------------------------------

function wireSwipeGestures(container) {
  const listEl = container.querySelector('#items-list');
  if (!listEl) return;

  wireSwipeRows(listEl, {
    card: '.shopping-item',
    ignore: '.list-row__drag',
    // Vor 2.0.0 löschte der Wisch zum Zeilenende hier sofort: eine der zwei
    // Listen, in denen die Seiten wirklich getauscht haben.
    sidesSwapped: true,
    // Beide Seiten führen dieselbe Aktion aus wie der Knopf in der Zeile -
    // über dieselbe Funktion, nicht über eine zweite Schreibweise daneben.
    //
    // Zeilenanfang: abhaken / zurueck - die primäre positive Aktion der Liste
    // (§2). Die Karte fliegt hinaus, die Zeile bleibt - nur ihr Zustand
    // wechselt (Issue #276: kein Re-Render der Liste).
    leading: {
      reveal: '.swipe-reveal--done',
      flyOut: true,
      run: (row) => toggleShoppingItem(
        Number(row.dataset.swipeId),
        Number(row.dataset.swipeChecked),
        container,
      ),
    },
    // Zeilenende: loeschen, widerrufbar - dieselbe Kante wie bei den
    // Geburtstagen. Die Karte federt zurück statt hinauszufliegen, aus
    // demselben Grund wie dort: eine hinausgeflogene Karte behauptet, die
    // Sache sei erledigt, während der Rückgängig-Weg noch fünf Sekunden
    // offen steht.
    trailing: {
      reveal: '.swipe-reveal--delete',
      run: (row) => deleteItemUndoable(Number(row.dataset.swipeId), container),
    },
  });
}

// --------------------------------------------------------
// DOM-Updates (ohne komplettes Re-Render)
// --------------------------------------------------------

/**
 * DIE PAUSE (#1816, Entscheidung 2026-10-08): abgehakte Zeilen ziehen erst um,
 * wenn man INNEHAELT - alle zusammen, nicht jede fuer sich.
 *
 * Mit einer Frist je Zeile (so stand es zuerst, 600 ms) verschob jede Zeile die
 * Liste, waehrend der Finger schon zur naechsten unterwegs war: gemessen lag
 * 750 ms nach dem ersten Haken die dritte Zeile dort, wo der Haken der zweiten
 * gewesen war. Das ist der Sprung, den #276 abgeschafft hatte. Jetzt gibt es
 * EINE Uhr: jeder eigene Haken (setzen wie zuruecknehmen) stellt sie fuer alle
 * wartenden Zeilen neu, und erst wenn sie ablaeuft, ziehen sie gemeinsam um.
 *
 * DIE DAUER ist das Dreifache des laengsten Bewegungsschritts
 * (`--duration-2xl`, 400 ms -> 1,2 s). Eine eigene Zeit gibt die Skala nicht
 * her, und sie muss LAENGER sein als der Abstand zweier Haken beim Abarbeiten
 * einer Liste, sonst ist sie keine Pause: 600 ms waren kuerzer als der Weg
 * des Fingers zur naechsten Zeile, 1,2 s sind es nicht mehr, und die Liste
 * wird trotzdem noch im selben Atemzug kuerzer. Eine Zeit und keine
 * Animation: sie gilt auch unter reduzierter Bewegung - dort entfaellt nur das
 * Gleiten danach.
 */
const SETTLE_PAUSE_STEPS = 3;
let SETTLE_PAUSE_MS_OVERRIDE = null; // nur fuer Tests, siehe __test unten
function settlePauseMs() {
  return SETTLE_PAUSE_MS_OVERRIDE ?? SETTLE_PAUSE_STEPS * durationToken('--duration-2xl', 400);
}

/**
 * Wartende Zeilen: Id -> steht sie gerade im Abschnitt „Abgehakt"? Der Wert
 * haelt fest, WO die Zeile wartet - `listSections` liest ihn, damit auch ein
 * Neuaufbau der Liste (jemand fuegt einen Artikel hinzu) sie nicht vorzeitig
 * umstellt.
 */
const heldRows = new Map();
let settleTimer = null;
let settleContainer = null;

/** Eine Zeile wartet auf die Pause, und die Uhr beginnt fuer alle neu. */
function holdPlacement(container, id, shownTicked) {
  if (!heldRows.has(id)) heldRows.set(id, shownTicked);
  clearTimeout(settleTimer);
  settleContainer = container;
  settleTimer = setTimeout(flushPlacements, settlePauseMs());
}

/**
 * Ein Umzug, den nicht der eigene Finger ausgeloest hat (Live-Auffrischung,
 * abgelehnter Schreibvorgang): sofort, solange hier niemand tippt - sonst
 * reiht er sich in die laufende Pause ein, OHNE sie zu verlaengern.
 */
function placeOrHold(container, id) {
  if (settleTimer == null) { settleItemPlacements(container, [id]); return; }
  if (heldRows.has(id)) return;
  const row = container?.querySelector?.('#items-list')?.querySelector?.(`.swipe-row[data-swipe-id="${id}"]`);
  if (row) heldRows.set(id, Boolean(row.closest('.item-ticked')));
}

/** Die Pause ist um: alles, was gewartet hat, zieht zusammen um. */
function flushPlacements() {
  const container = settleContainer;
  const ids = [...heldRows.keys()];
  resetPlacementHold();
  // Die Seite kann in der Wartezeit verlassen worden sein.
  if (!container || container.isConnected === false) return;
  settleItemPlacements(container, ids);
}

/** Die Pause verwerfen - beim Listenwechsel und beim Seitenaufbau. */
function resetPlacementHold() {
  clearTimeout(settleTimer);
  settleTimer = null;
  settleContainer = null;
  heldRows.clear();
}

/** Zaehlstaende und Sichtbarkeit der Gruppen nach einem Umzug fortschreiben. */
function syncGroupChrome(listEl) {
  listEl.querySelectorAll('.list-group').forEach((groupEl) => {
    const count = groupEl.querySelectorAll('.row-carrier > .swipe-row').length;
    const countEl = groupEl.querySelector('.list-group__count');
    if (countEl) countEl.textContent = String(count);
    groupEl.hidden = count === 0;
  });
}

/** Steht das Element im Bild - weder selbst noch ueber einen Vorfahren `hidden`? */
function shown(el) {
  return Boolean(el) && !el.closest('[hidden]');
}

/**
 * Wer den Fokus bekommt, wenn die Zeile mit dem Fokus umzieht: die naechste
 * Zeile derselben ZONE, sonst die vorige. Die Zone der offenen Artikel ist die
 * ganze Liste in Lesereihenfolge, ueber Kategoriegrenzen hinweg - wer die
 * letzte Zeile von „Obst" abhakt, hakt bei „Milch" weiter und landet nicht am
 * Listenende. Die Zone des Abschnitts „Abgehakt" sind seine Zeilen. Zeilen, die
 * im selben Zug mit umziehen, zaehlen nicht.
 */
function focusSuccessor(listEl, row, moving) {
  const zone = row.closest('.item-ticked')
    ? Array.from(row.parentElement.querySelectorAll(':scope > .swipe-row'))
    : Array.from(listEl.querySelectorAll('.item-category:not([hidden]) > .row-carrier:not([hidden]) > .swipe-row'));
  const idx = zone.indexOf(row);
  const stays = (r) => !moving.has(r);
  const next = zone.slice(idx + 1).find(stays) ?? zone.slice(0, Math.max(idx, 0)).reverse().find(stays);
  return next?.querySelector('button.item-check') ?? null;
}

/**
 * Der Rueckfall, wenn die Zone leer ist: der Haken der umgezogenen Zeile
 * selbst, dort wo sie jetzt steht; ist ihr Traeger zugeklappt, der Kopf ihrer
 * Gruppe. Der Fokus faellt nie auf `body` - ein verschobener Knoten verliert
 * ihn, und ein Kopf, der mit der letzten Zeile verschwindet, ist kein Ziel.
 */
function focusFallback(row) {
  const own = row.querySelector('button.item-check');
  if (shown(own)) return own;
  const head = row.closest('.list-group')?.querySelector('.list-group__toggle');
  return shown(head) ? head : null;
}

/**
 * Stellt Zeilen dorthin, wo ihr Haken sie zeigt (#1816): abgehakt in den
 * Abschnitt am Listenende, offen in ihre Kategorie.
 *
 * EIN ABGLEICH, KEINE BEWEGUNG "VON A NACH B": gefragt wird nur, wo eine Zeile
 * hingehoert, und steht sie dort schon, passiert nichts. Deshalb darf jeder
 * rufen, der einen Haken geaendert hat - die abgelaufene Pause, eine
 * Live-Auffrischung, das Zuruecksetzen nach einem Fehler -, in beliebiger
 * Reihenfolge und beliebig oft.
 *
 * DIE ZEILE WANDERT ALS KNOTEN. Ein Neuaufbau der Liste verwuerfe die
 * Sortable-Instanzen und die Wisch-Verdrahtung, liesse alle Zeilen neu
 * einblenden und naehme der Tastatur ihren Platz - bei der haeufigsten Geste
 * der Seite. Fehlt das Ziel (die Liste wurde anders gebaut als erwartet),
 * bleibt der Neuaufbau als Rueckfall.
 *
 * ALLE ZUSAMMEN: die Zeilen klappen gleichzeitig zu und ziehen in EINEM
 * Schritt um - die Liste rueckt einmal zusammen, nicht je Zeile.
 *
 * DER FOKUS BLEIBT IN DER LISTE, siehe `focusSuccessor` und `focusFallback`.
 */
function settleItemPlacements(container, ids, { animate = true } = {}) {
  const listEl = container?.querySelector?.('#items-list');
  if (!listEl?.querySelector) return;
  const locate = (id) => {
    const row  = listEl.querySelector(`.swipe-row[data-swipe-id="${id}"]`);
    const plan = placementOf(state.items, id);
    if (!row || !plan) return null;
    const groupEl = plan.ticked
      ? listEl.querySelector('.item-ticked')
      : Array.from(listEl.querySelectorAll('.item-category')).find((g) => g.dataset.category === plan.category);
    return { row, plan, to: groupEl?.querySelector('.row-carrier') ?? null };
  };
  const due = () => ids.map(locate).filter((m) => m && m.to !== m.row.parentElement);

  const first = due();
  if (!first.length) return;
  if (first.some((m) => !m.to)) { updateItemsList(container); return; }
  const leaving = first.map((m) => m.row);

  const move = () => {
    for (const row of leaving) {
      row.getAnimations?.().forEach((anim) => anim.cancel());
      row.style.overflow = '';
    }
    // Neu gefragt: waehrend des Zusammenklappens kann ein Haken zurueckgenommen
    // oder die Liste neu gebaut worden sein.
    const moves = due();
    if (!moves.length) return;
    if (moves.some((m) => !m.to)) { updateItemsList(container); return; }

    const moving  = new Set(moves.map((m) => m.row));
    const focused = moves.find((m) => m.row.contains(document.activeElement))?.row ?? null;
    // VOR dem Umzug gelesen: danach steht die Zeile in einer anderen Zone.
    const successor = focused ? focusSuccessor(listEl, focused, moving) : null;

    const carriers = new Set();
    for (const { row, plan, to } of moves) {
      carriers.add(row.parentElement).add(to);
      const before = plan.following
        .map((nextId) => to.querySelector(`:scope > .swipe-row[data-swipe-id="${nextId}"]`))
        .find(Boolean) ?? null;
      to.insertBefore(row, before);
    }

    syncGroupChrome(listEl);
    carriers.forEach((carrier) => refreshHandleLabels(carrier));

    if (focused) (shown(successor) ? successor : focusFallback(focused))?.focus({ preventScroll: true });
    if (animate) for (const { row, to } of moves) if (!to.hidden) expandIn(row);
  };

  // Aus einem zugeklappten Traeger gibt es nichts zusammenzuklappen.
  const closing = animate ? leaving.filter((row) => !row.parentElement.hidden).map((row) => collapseOut(row)) : [];
  if (closing.length) Promise.all(closing).then(move);
  else move();
}

/**
 * Aktualisiert nur die DOM-Zeile eines einzelnen Artikels (Checked-Status),
 * ohne die gesamte Liste neu aufzubauen - so bleibt die Scroll-Position des
 * Listen-Containers erhalten (Issue #276). Wohin die Zeile danach gehoert,
 * entscheidet `settleItemPlacements`.
 */
function updateItemRow(container, item) {
  const row = container.querySelector(`.swipe-row[data-swipe-id="${item.id}"]`);
  if (!row) return;
  const isDone = Boolean(checkedOf(item));

  row.dataset.swipeChecked = String(checkedOf(item));

  row.querySelector('.shopping-item')?.classList.toggle('shopping-item--checked', isDone);

  const checkBtn = row.querySelector('.item-check');
  if (checkBtn) {
    checkBtn.classList.toggle('item-check--checked', isDone);
    // Das Zeichen bei `read` nennt den ZUSTAND; eine Live-Auffrischung (jemand
    // anderes hakt ab) laeuft ueber genau diese Stelle und darf ihm nicht die
    // Handlungs-Beschriftung des Knopfs anhaengen.
    if (checkBtn.classList.contains('item-check--static')) {
      checkBtn.setAttribute('aria-label', itemStateLabel(item));
    } else {
      checkBtn.dataset.checked = String(checkedOf(item));
      checkBtn.setAttribute('aria-label', isDone
        ? t('shopping.markUndoneLabel', { name: item.name })
        : t('shopping.markDoneLabel', { name: item.name }));
    }
  }

  // Der Sortiergriff hängt am Erledigt-Zustand (#678): abgehaktes sortiert sich
  // nicht, und die Positionsangaben der Gruppe verschieben sich mit.
  refreshHandleLabels(row.closest('.row-carrier'));

  // Swipe-Affordance (links) spiegelt den neuen Status
  const reveal = row.querySelector('.swipe-reveal--done');
  if (reveal) {
    reveal.replaceChildren();
    reveal.insertAdjacentHTML('beforeend', `
      <i data-lucide="${isDone ? 'rotate-ccw' : 'check'}" class="icon-xl" aria-hidden="true"></i>
      <span>${isDone ? t('shopping.swipeBack') : t('shopping.swipeCheck')}</span>`);
    if (window.lucide) window.lucide.createIcons({ el: reveal });
  }
}

/**
 * Aktualisiert Name, Menge und die Detail-Indikatoren (Link/Notiz) einer Zeile,
 * ohne das .shopping-item-Element zu ersetzen — so bleiben die
 * Swipe-Gesten-Closures (die die Karte einmalig referenzieren) intakt.
 *
 * Deckte vorher nur die Indikatoren ab: Name und Menge waren im Dialog gar nicht
 * änderbar (Critique 2026-07-30, P2). Seit sie es sind, muss die Zeile beide
 * mitziehen - und die Menge kann von „vorhanden" auf „leer" wechseln, also muss
 * das Meta-Element auch verschwinden können.
 */
function refreshItemName(container, item) {
  const card = container.querySelector(`.shopping-item[data-item-id="${item.id}"]`);
  const nameEl = card?.querySelector('.list-row__name');
  if (!nameEl) return;

  nameEl.replaceChildren(document.createTextNode(item.name));
  const metaHtml = renderItemMeta(item);
  if (metaHtml) {
    nameEl.insertAdjacentHTML('beforeend', metaHtml);
    if (window.lucide) window.lucide.createIcons({ el: nameEl });
  }

  /* Die Metazeile trägt seit dem Zeilenschnitt ZWEI Dinge, Menge und Etiketten.
   * `metaEl.textContent = …` hätte die Etiketten dabei mitgelöscht - deshalb
   * greift die Menge ihren eigenen Knoten. Die Zeile selbst verschwindet nur,
   * wenn beides fehlt. */
  const main = card.querySelector('.list-row__main');
  const metaEl = main?.querySelector('.list-row__meta');
  const hasTags = !!item.tags?.length;
  if (item.quantity || hasTags) {
    if (!metaEl) {
      main?.insertAdjacentHTML('beforeend', `<div class="list-row__meta">
        ${item.quantity ? `<span class="shopping-item__quantity">${esc(item.quantity)}</span>` : ''}
        ${renderItemTags(item.tags)}
      </div>`);
    } else {
      const qtyEl = metaEl.querySelector('.shopping-item__quantity');
      if (item.quantity && qtyEl) {
        qtyEl.textContent = item.quantity;
      } else if (item.quantity) {
        metaEl.insertAdjacentHTML('afterbegin', `<span class="shopping-item__quantity">${esc(item.quantity)}</span>`);
      } else {
        qtyEl?.remove();
      }
    }
  } else {
    metaEl?.remove();
  }
}

/**
 * Artikel bearbeiten.
 *
 * WAS HIER FALSCH WAR (Critique 2026-07-30, P2): dieser Dialog und das
 * strukturgleiche Vorrats-Modal sind dieselbe Handlung - „diesen Eintrag ändern" -
 * und waren zwei verschiedene Dinge. Der Vorrat: Titel „Artikel bearbeiten", acht
 * Felder, Löschen / Abbrechen / Speichern. Der Einkauf: der DATENWERT als Titel
 * („Cherry tomatoes"), zwei Felder (Link, Notiz), Schließen und Speichern - KEIN
 * Abbrechen, und Name und Menge waren gar nicht änderbar. Wer einen Tippfehler im
 * Artikelnamen hatte, musste die Zeile löschen und neu anlegen.
 *
 * Jetzt: derselbe Titel aus demselben Key, Name / Menge / Kategorie editierbar,
 * Abbrechen neben Speichern. Die Rich-Felder (Link, Notiz) bleiben, wo sie waren -
 * sie sind der Grund, aus dem der Dialog existiert, und der Quick-Add bleibt
 * bewusst schlank.
 *
 * KEIN LÖSCHEN im Dialog, anders als im Vorrat: die Einkaufszeile trägt es selbst
 * (× auf Zeigergeräten, Wischen auf Touch), und beide Wege haben Undo. Ein dritter
 * Weg an einer Stelle, an der man gerade einen Namen tippt, wäre eine
 * Fehlerquelle, kein Gewinn.
 */
/** Der Preis als Betrag in der Haushaltswaehrung, in deren kleinster Einheit gespeichert. */
function priceReadText(cents) {
  if (cents == null) return '';
  return formatMoney(Number(cents) / 10 ** currencyFractionDigits(state.currency), state.currency);
}

/**
 * Der Artikel bei `shopping: read`: Leseansicht, sonst nichts (Regel 9,
 * Bauart `openNoteReadModal()` in notes.js). Alles, was der Bearbeiten-Dialog
 * zeigt - Menge, Kategorie, Preis, Laden, Link, Notiz -, als Wert statt als
 * Eingabe; der Name steht im Titel. Kein Fusszeilen-Knopf, das X schliesst.
 * Der Link bleibt ein Link: ihn zu oeffnen ist Lesen.
 */
function itemReadHtml(item) {
  const url = String(item.url ?? '').trim();
  const link = /^https?:\/\//i.test(url)
    ? `<a class="item-details__link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(url)}</a>`
    : esc(url);
  return `
    <div class="item-details-read detail-view" data-view="read" data-item-id="${item.id}">
      <div class="detail-view__rows">
        ${readRowHtml({ icon: 'hash', label: t('shopping.itemQtyLabel'), value: item.quantity || '' })}
        ${readRowHtml({ icon: 'tag', label: t('shopping.categoryLabel'), value: item.category ? categoryLabel(item.category) : '' })}
        ${readRowHtml({ icon: 'receipt', label: t('shopping.priceLabel'), value: priceReadText(item.price_cents) })}
        ${readRowHtml({ icon: 'store', label: t('shopping.storeLabel'), value: storeName(item) })}
        ${readRowHtml({ icon: 'link', label: t('shopping.urlLabel'), valueHtml: link })}
        ${readRowHtml({ icon: 'align-left', label: t('shopping.notesLabel'), value: item.notes || '', multiline: true })}
      </div>
    </div>`;
}

function openItemReadModal(item) {
  openModal({
    title: item.name,
    size: 'md',
    content: itemReadHtml(item),
    onSave(panel) {
      window.lucide?.createIcons({ el: panel });
    },
  });
}

function openItemDetails(itemId, container) {
  const item = state.items.find((i) => i.id === itemId);
  if (!item) return;
  // Der Riegel steht VOR jeder Vorbereitung: bei `read` geht die Leseansicht auf.
  if (readOnly()) {
    openItemReadModal(item);
    return;
  }

  const linkPreview = (value) => {
    const v = String(value ?? '').trim();
    if (!/^https?:\/\//i.test(v)) return '';
    return `
      <a class="item-details__link" href="${esc(v)}" target="_blank" rel="noopener noreferrer">
        <i data-lucide="external-link" class="icon-sm" aria-hidden="true"></i>${t('shopping.openLink')}
      </a>`;
  };

  // DIE LISTE IST EINE EIGENE FORMULARZEILE (#1700, Entscheidung 2026-10-08),
  // unter Menge und Kategorie - die beiden bleiben nebeneinander, wie sie
  // waren, und der Dialog sieht mit einer Liste genauso aus wie mit fuenf,
  // nur ohne diese Zeile: mit einer Liste gibt es nichts zu waehlen. Sie
  // spricht die Zielform des Hauses (utils/form-row.js, DESIGN.md
  // "Formularzeile"): Etikett links, der Wert rechts als randlose Auswahl.
  // Kein eigener "Verschieben"-Weg und kein Ziehen: der Dialog ist ohnehin der
  // Ort, an dem man einen Artikel umhaengt.
  const fromListId = state.activeListId;
  const listRow = state.lists.length > 1 ? formRowsHtml(formRowHtml({
    label: t('shopping.itemListLabel'),
    labelFor: 'item-details-list',
    field: true,
    control: `<select class="form-input" id="item-details-list">
              ${state.lists.map((l) => `<option value="${l.id}" ${l.id === fromListId ? 'selected' : ''}>${esc(l.name)}</option>`).join('')}
            </select>`,
  })) : '';

  openModal({
    title: t('common.editItem'),
    size: 'md',
    content: `
      <form id="item-details-form" class="item-details-form" novalidate autocomplete="off">
        <div class="form-group">
          <label class="form-label" for="item-details-name">${t('common.nameLabel')}</label>
          <input class="form-input" type="text" id="item-details-name" required
                 value="${esc(item.name)}">
        </div>
        <div class="form-pair">
          <div class="form-group">
            <label class="form-label" for="item-details-qty">${t('shopping.itemQtyLabel')}</label>
            <input class="form-input" type="text" id="item-details-qty"
                   placeholder="${t('shopping.itemQtyPlaceholder')}" value="${esc(item.quantity || '')}">
          </div>
          <div class="form-group">
            <label class="form-label" for="item-details-cat">${t('shopping.categoryLabel')}</label>
            <select class="form-input" id="item-details-cat">
              ${state.categories.map((c) => `<option value="${esc(c.name)}" ${c.name === item.category ? 'selected' : ''}>${esc(categoryLabel(c.name))}</option>`).join('')}
            </select>
          </div>
        </div>
        ${listRow}
        ${/* PREIS UND LADEN (#1003).
            *
            * NICHT ALS ZWANGSDIALOG BEIM ABHAKEN. Das Ticket sagt "erfasst,
            * wenn man abhakt - da ist die Zahl bekannt", und das stimmt; ein
            * Dialog, der sich bei JEDEM Haken oeffnet, waere im Laden aber
            * unertraeglich: das Abhaken ist die schnellste Geste der App und
            * bleibt es. Die Felder stehen deshalb hier, wo der Artikel ohnehin
            * geoeffnet wird - nachtragen statt unterbrechen.
            *
            * Betont bei einem abgehakten Artikel: dann ist die Frage aktuell. */ ''}
        <div class="form-pair">
          <div class="form-group">
            <label class="form-label" for="item-details-price">${t('shopping.priceLabel')}</label>
            <input class="form-input" type="text" id="item-details-price" inputmode="decimal"
                   placeholder="${esc(amountPlaceholder(state.currency))}"
                   value="${item.price_cents != null ? esc(centsToAmountInput(item.price_cents, state.currency)) : ''}">
          </div>
          <div class="form-group">
            <label class="form-label" for="item-details-store">${t('shopping.storeLabel')}</label>
            ${/* COMBOBOX, KEIN SELECT (#1003).
                *
                * Eine reine Auswahlliste ist bei einem frischen Haushalt leer und
                * bleibt es: der erste Laden muesste anderswo entstehen. Ein Knopf
                * daneben hilft hier nicht - das geteilte Modal kennt bewusst kein
                * Stacking (siehe modal.js), ein Manager darueber raeumte dieses
                * Formular samt getippter Eingaben weg.
                *
                * Also tippen oder waehlen: die Liste kommt als datalist dazu, und
                * ein unbekannter Name legt beim Speichern den Laden an. Umbenennen
                * und Loeschen liegen im Listenmenue, wo der Manager ein Dialog
                * erster Ebene sein darf. */ ''}
            <input class="form-input" type="text" id="item-details-store" list="item-details-store-options"
                   autocomplete="off" placeholder="${esc(t('shopping.storePlaceholder'))}"
                   value="${esc(state.stores.find((st) => st.id === item.store_id)?.name ?? '')}">
            <datalist id="item-details-store-options">
              ${state.stores.map((st) => `<option value="${esc(st.name)}"></option>`).join('')}
            </datalist>
          </div>
        </div>
        <div class="form-group">
          <label class="form-label" for="item-details-url">${t('shopping.urlLabel')}</label>
          <input class="form-input" type="url" id="item-details-url" inputmode="url"
                 placeholder="${t('shopping.urlPlaceholder')}" value="${esc(item.url || '')}">
          <div class="item-details__link-wrap" id="item-details-link">${linkPreview(item.url)}</div>
        </div>
        <div class="form-group">
          <label class="form-label" for="item-details-notes">${t('shopping.notesLabel')}</label>
          <textarea class="form-input" id="item-details-notes" rows="4"
                    placeholder="${t('shopping.notesPlaceholder')}">${esc(item.notes || '')}</textarea>
        </div>
        ${/* LOESCHEN OHNE WISCHGESTE (A4 P1-1, WCAG 2.5.1). Am Touchgeraet
            * blendet shopping.css den Papierkorb der Zeile aus; einziger Weg
            * war das Wischen, das VoiceOver abfaengt. Jetzt links im Fuss wie
            * bei Mahlzeit und Rezept, und derselbe Weg wie Wisch und Knopf
            * (`deleteItemUndoable`: sofort weg, fuenf Sekunden Rueckgaengig). */ ''}
        <div class="modal-panel__footer modal-panel__footer--plain">
          <button type="button" class="btn btn--danger-outline" id="item-details-delete" data-delete-name="${esc(item.name)}" style="margin-inline-end:auto"><i data-lucide="trash-2" class="icon-md" aria-hidden="true"></i>${esc(t('common.delete'))}</button>
          <button type="button" class="btn btn--secondary" id="item-details-cancel">${t('common.cancel')}</button>
          <button type="submit" class="btn btn--primary">${t('common.save')}</button>
        </div>
      </form>`,
    // Der Dialog meldet sich ab, wenn er zugeht (siehe `reloadAfterGone`).
    onClose: () => { if (_itemDialog?.id === item.id) _itemDialog = null; },
    onSave: (panel) => {
      _itemDialog = { id: item.id, panel };
      const form    = panel.querySelector('#item-details-form');
      const nameEl  = panel.querySelector('#item-details-name');
      const qtyEl   = panel.querySelector('#item-details-qty');
      const catEl   = panel.querySelector('#item-details-cat');
      const urlEl   = panel.querySelector('#item-details-url');
      const notesEl = panel.querySelector('#item-details-notes');
      const preview = panel.querySelector('#item-details-link');

      panel.querySelector('#item-details-cancel')?.addEventListener('click', () => closeModal());
      panel.querySelector('#item-details-delete')?.addEventListener('click', () => {
        // Der Dialog kann vor einem Rechtewechsel aufgegangen sein.
        if (readOnly()) return;
        // force: getippte, ungespeicherte Aenderungen gehen mit dem Artikel -
        // eine Rueckfrage "Verwerfen?" vor dem Loeschen fragte das Falsche.
        closeModal({ force: true });
        deleteItemUndoable(item.id, container);
      });

      urlEl?.addEventListener('input', () => {
        preview.replaceChildren();
        const html = linkPreview(urlEl.value);
        if (html) {
          preview.insertAdjacentHTML('beforeend', html);
          if (window.lucide) window.lucide.createIcons({ el: preview });
        }
      });

      form?.addEventListener('submit', async (e) => {
        e.preventDefault();
        // Der Dialog kann vor einem Rechtewechsel aufgegangen sein.
        if (readOnly()) return;
        const name = nameEl.value.trim();
        if (!name) {
          reportFieldError(nameEl, t('common.nameRequired'));
          return;
        }
        const priceEl = panel.querySelector('#item-details-price');
        const storeEl = panel.querySelector('#item-details-store');
        // Der Preis kommt als Text herein und geht als ganze Cent hinaus: Geld
        // als Gleitkomma summiert sich sichtbar falsch, und die Historie, die
        // spaeter darauf aufbaut, addiert genau solche Zahlen. Ein leeres Feld
        // heisst "kein Preis", nicht "null Cent".
        const priceRoh = priceEl?.value.trim() ?? '';
        const priceCents = priceRoh === '' ? null : amountInputToCents(priceRoh, state.currency);
        if (priceRoh !== '' && priceCents === null) {
          reportFieldError(priceEl, t('budget.validAmountRequired'));
          return;
        }
        try {
          // Der Laden kommt als Name herein, die Zeile speichert eine ID. Ein
          // Name, den es noch nicht gibt, entsteht hier - der Server gibt bei
          // einem schon vorhandenen Namen dieselbe Zeile zurueck (COLLATE
          // NOCASE), zwei Schreibweisen werden also nicht zu zwei Laeden.
          const storeName = storeEl?.value.trim() ?? '';
          let storeId = null;
          if (storeName) {
            const bekannt = state.stores.find((st) => st.name.toLowerCase() === storeName.toLowerCase());
            if (bekannt) {
              storeId = bekannt.id;
            } else {
              const angelegt = await api.post('/shopping/stores', { name: storeName });
              state.stores.push(angelegt.data);
              storeId = angelegt.data.id;
            }
          }
          const payload = {
            name,
            quantity: qtyEl.value.trim() || null,
            category: catEl.value,
            notes: notesEl.value.trim() || null,
            url: urlEl.value.trim() || null,
            price_cents: priceCents,
            store_id: storeId,
          };
          // Die Zielliste reist nur mit, wenn sie eine andere ist (#1700):
          // ein gewöhnliches Speichern bleibt ein gewöhnliches Speichern.
          const targetListId = Number(panel.querySelector('#item-details-list')?.value) || fromListId;
          if (targetListId !== fromListId) payload.list_id = targetListId;
          const data = await api.patch(`/shopping/items/${item.id}`, payload);
          acknowledgeOwnChange(data);
          // Umgezogen ist er, wenn die Antwort die erbetene Liste traegt.
          if (payload.list_id !== undefined && data.data.list_id === payload.list_id) {
            closeModal({ force: true });
            itemMovedAway(container, data.data, fromListId);
            return;
          }
          // DER ARTIKEL WIRD BEIM SPEICHERN NACHGESCHLAGEN, nicht beim Oeffnen
          // festgehalten: waehrend der Dialog offen war, kann eine
          // Live-Auffrischung `state.items` ersetzt haben - dann ist `item` ein
          // Objekt, das nirgends mehr haengt, und die Bearbeitung landete dort
          // statt in der Liste. Die Zeile zeigte weiter den alten Namen, und
          // weil die Quittung die Marke vorrueckt, holte auch keine Abfrage
          // das nach. Fehlt der Artikel ganz (jemand hat ihn inzwischen
          // geloescht, oder er ist noch nicht wieder geladen), bleibt der
          // Neuaufbau aus dem Bestand.
          const aktuell = state.items.find((i) => i.id === item.id);
          if (!aktuell) {
            closeModal({ force: true });
            updateItemsList(container);
            return;
          }
          const categoryChanged = data.data.category !== aktuell.category;
          Object.assign(aktuell, data.data);
          // force: der Dirty-Guard vergleicht gegen den Snapshot vom Öffnen und
          // sähe die gerade gespeicherten Felder als ungespeicherte Änderungen.
          // Ohne das fragte Speichern „Änderungen verwerfen?" (Issue #625).
          closeModal({ force: true });
          // Ein Kategoriewechsel verschiebt die Zeile in eine andere Gruppe - das
          // kann keine Zeilen-Auffrischung leisten, dafür muss die Liste neu
          // gruppiert werden. Sonst genügt der schonende Weg, der die
          // Swipe-Closures und die Scroll-Position erhält (Issue #276).
          if (categoryChanged) {
            updateItemsList(container);
          } else {
            updateItemRow(container, aktuell);
            refreshItemName(container, aktuell);
          }
        } catch (err) {
          reportError(err, container);
        }
      });
    },
  });
}

/**
 * Eine Zeile in einem zugeklappten Traeger (Kategorie oder „Abgehakt", #1816)
 * hat keine Lage: gemessen wird sie bei 0/0, und kaeme sie im Neubau ins Bild,
 * glitte sie aus der Fensterecke herein. Ohne Vorher-Lage erscheint sie wie
 * eine neue Zeile.
 */
function dropHiddenRows(listEl, before) {
  for (const row of listEl.querySelectorAll?.('.row-carrier[hidden] > .swipe-row[data-swipe-id]') ?? []) {
    before.delete(row.dataset.swipeId);
  }
}

function updateItemsList(container) {
  const listEl = container.querySelector('#items-list');
  if (listEl) {
    // FLIP (Re-Critique 2026-09-28, A4 P2-8): ein abgehakter Artikel sprang
    // beim Neubau ans Gruppenende. Die Lage wird VOR dem Neubau gemessen und
    // jede bewegte Zeile gleitet danach von dort an ihre neue Stelle
    // (utils/flip.js; reduzierte Bewegung springt wie bisher).
    const before = flipSnapshot(listEl, '.swipe-row[data-swipe-id]', 'data-swipe-id');
    dropHiddenRows(listEl, before);
    // mountItems() verdrahtet den CTA des Leerzustands selbst; der frühere
    // nachgelagerte #empty-cta-shopping-Listener entfällt damit.
    mountItems(listEl, container);
    flipPlay(listEl, '.swipe-row[data-swipe-id]', 'data-swipe-id', before);
    if (window.lucide) window.lucide.createIcons({ el: listEl });
    stagger(listEl.querySelectorAll('.shopping-item'), { host: listEl });
    // Regel 3 in utils/module-access.js: Wischen und Ziehen haben kein Markup,
    // das man wegnehmen koennte - bei `read` bleibt die VERDRAHTUNG aus. Ein
    // Riegel im Ende-Handler kaeme zu spaet, die Zeile waere schon weggewischt.
    // Der Wisch-Hinweis zeigte eine Geste, die es dann nicht gibt.
    if (readOnly()) {
      destroyItemSortables();
    } else {
      wireSwipeGestures(container);
      wireItemReorder(container);
      maybeShowSwipeHint(container);
    }
  }
  updateCheckedActions(container);
}

/**
 * Zerlegt den Freitext einer Einkaufsmenge in Zahl + Vorrats-Einheit.
 *
 * Bewusst nur die international geschriebenen metrischen Symbole: das Feld ist
 * Freitext in der Sprache des Haushalts, und ein deutschsprachiger Wortschatz
 * („Packung", „Dose") würde in 22 der 23 Sprachen ins Leere greifen. Zahl und
 * g/kg/ml/l sind sprachunabhängig und tragen den Großteil des Nutzens; alles
 * andere landet bei „Stück" und lässt sich im Dialog in einem Griff ändern.
 */
function parseShoppingQuantity(raw) {
  const fallback = { quantity: 1, unit: 'pcs' };
  const text = String(raw ?? '').trim();
  if (!text) return fallback;

  // Dieselbe Umschrift wie die Betragsfelder (utils/money.js): sie leitet Ziffern
  // und Dezimaltrenner aus der eingestellten Region ab. Ein eigenes
  // `replace(',', '.')` stand hier und war in beide Richtungen falsch - unter
  // en-US gruppiert das Komma Tausender, aus „1,000 g" wurde die Menge 1, und
  // unter ar oder fa kam eine Eingabe in östlichen Ziffern gar nicht erst an
  // (`\d` ist ASCII). Beides ohne Fehlermeldung: die Zeile im Übernahme-Dialog
  // stand einfach auf 1.
  //
  // `freeText`, weil hier nur der ANFANG gelesen wird: eine Gruppierung weiter
  // hinten geht diese Zerlegung nichts an. Ohne das fiel „6 × 1.000 ml" auf die
  // Menge 1 zurueck, obwohl die 6 eindeutig ist.
  //
  // Eine gruppierte Zahl weist die Umschrift ab und liefert einen leeren String.
  // Dann bleibt es beim Standard, statt zwischen 1 und 1000 zu raten - dieselbe
  // Entscheidung wie beim Preis, hier aber mit dem sanfteren Ausgang: der Dialog
  // zeigt die Menge in einem Feld, das sich korrigieren lässt.
  const decimal = toDecimalString(text, { freeText: true });
  if (!decimal) return fallback;

  // Die Einheit braucht eine Wortgrenze davor, sonst schluckt `\b` sie bei
  // Schreibweisen wie „3x" nicht und die Menge fiele auf 1 zurück.
  // Der Trenner ist hier immer der Punkt - die Umschrift oben hat den der Region
  // bereits übersetzt.
  const match = decimal.match(/^(\d+(?:\.\d+)?)\s*(?:(kg|g|ml|l)\b)?/i);
  if (!match) return fallback;

  // Bricht die Zahl mitten in einem Trennzeichen ab, ist sie nicht gelesen,
  // sondern abgeschnitten. Die Umschrift weist zwar eine erkannte Gruppierung
  // ab, aber nicht jede: „٢٬٥٠" hat nur zwei Stellen hinter dem Trenner, ist
  // also kein Gruppierungsmuster - und ein Trenner, den die Region nicht kennt,
  // steht ohnehin einfach da (unter fa trennt das ASCII-Komma nichts). Diese
  // Regex liest nur den ANFANG und nähme daraus wortlos die 2.
  //
  // Über die geteilte Prüfung aus utils/money.js, die genau die Trennzeichen der
  // wählbaren Regionen kennt: „irgendein Zeichen zwischen zwei Ziffern" war zu
  // breit und traf „2x500 g" mit, also die Multiplikator-Schreibweise, die zwei
  // Zeilen weiter oben ausdrücklich lesbar bleiben soll.
  if (breaksOffAtSeparator(decimal.slice(match[1].length))) return fallback;

  const quantity = Number(match[1]);
  if (!Number.isFinite(quantity) || quantity <= 0) return fallback;

  return { quantity, unit: match[2] ? match[2].toLowerCase() : 'pcs' };
}

/**
 * Übernahme-Dialog „Einkauf → Vorrat". Ein gemeinsamer Lagerort für alle
 * Artikel plus Menge/Einheit je Zeile: nach dem Einkauf räumt man einen Beutel
 * an einen Ort ein, nicht zwölf Artikel an zwölf Orte. Haltbarkeitsdaten bleiben
 * hier bewusst außen vor - sie sind die Ausnahme, nicht die Regel, und im
 * Vorrat einen Tap entfernt.
 */
async function openPantryTransfer(container) {
  // Der Uebertrag schreibt in den VORRAT (Pfad-Guard `pantry`) - die Frage
  // gehoert dem fremden Modul, nicht dieser Seite (Regel 1).
  if (!mayTransferShoppingToPantry()) return;
  const checked = state.items.filter((i) => checkedOf(i));
  if (!checked.length) return;

  let locations = [];
  try {
    const res = await api.get('/pantry/locations');
    locations = res.data ?? [];
  } catch (err) {
    reportError(err, container);
    return;
  }

  const { PANTRY_UNITS } = await import('/utils/pantry-units.js');
  const { locationLabel } = await import('/utils/pantry-locations.js');

  const unitOptions = (selected) => PANTRY_UNITS
    .map((u) => `<option value="${esc(u)}" ${u === selected ? 'selected' : ''}>${esc(t(`pantry.units.${u}`))}</option>`)
    .join('');

  const rows = checked.map((item) => {
    const parsed = parseShoppingQuantity(item.quantity);
    return `
      <li class="pantry-transfer__row" data-id="${item.id}">
        <span class="pantry-transfer__name">${esc(item.name)}</span>
        <input class="form-input pantry-transfer__qty" type="number" min="0" step="any" inputmode="decimal"
               value="${parsed.quantity}" aria-label="${esc(`${t('pantry.quantityLabel')}: ${item.name}`)}">
        <select class="form-input pantry-transfer__unit" aria-label="${esc(`${t('pantry.unitLabel')}: ${item.name}`)}">
          ${unitOptions(parsed.unit)}
        </select>
      </li>`;
  }).join('');

  openModal({
    title: t('shopping.toPantryTitle'),
    size: 'lg',
    content: `
      <p class="pantry-transfer__intro">${esc(t('shopping.toPantryDescription', { count: checked.length }))}</p>
      <div class="form-group">
        <label class="form-label" for="pantry-transfer-location">${esc(t('pantry.locationLabel'))}</label>
        <select id="pantry-transfer-location" class="form-input">
          <option value="">${esc(t('pantry.unlocated'))}</option>
          ${locations.map((loc) => `<option value="${loc.id}">${esc(locationLabel(loc.name))}</option>`).join('')}
        </select>
      </div>
      <ul class="pantry-transfer__list">${rows}</ul>
      <!-- Geteiltes .form-check (layout.css): 20px-Box in Modul-Akzent, Label mit
           eigener Trefferflaeche. Das war die folgenreichste Checkbox des Moduls -
           sie loescht die eingekauften Artikel von der Liste, ist standardmaessig
           aktiv, und war als nackte System-Checkbox in System-Groesse die
           unauffaelligste (Critique 2026-07-30, P2). Der Default bleibt aktiv: wer
           eingekauft und eingeraeumt hat, will nicht doppelt kaufen.
           Das Abraeumen ist ein DELETE im EINKAUF: ohne dessen Schreibrecht
           entfaellt die Checkbox, sonst endete der Uebertrag danach im 403 (#1265). -->
      ${readOnly() ? '' : `<label class="form-check pantry-transfer__clear">
        <input type="checkbox" id="pantry-transfer-clear" checked>
        <span>${esc(t('shopping.toPantryClearList'))}</span>
      </label>`}
      <div class="modal-panel__footer modal-panel__footer--plain">
        <button type="button" class="btn btn--secondary" data-action="close-modal">${esc(t('common.cancel'))}</button>
        <button type="button" class="btn btn--primary" id="pantry-transfer-confirm">${esc(t('common.apply'))}</button>
      </div>`,
    onSave(panel) {
      // Der erste Ort ist der wahrscheinlichste Standardwert; er ist zugleich
      // der, den der Haushalt in der Lagerort-Verwaltung nach oben sortiert hat.
      if (locations.length) panel.querySelector('#pantry-transfer-location').value = String(locations[0].id);

      panel.querySelector('#pantry-transfer-confirm').addEventListener('click', async (e) => {
        const btn = e.currentTarget;
        const locationId = panel.querySelector('#pantry-transfer-location').value || null;
        // Beim Absenden neu gefragt: die Rechte koennen sich geaendert haben,
        // waehrend der Dialog offen stand.
        const clearList = !readOnly() && Boolean(panel.querySelector('#pantry-transfer-clear')?.checked);
        const listId = state.activeListId;

        const items = [...panel.querySelectorAll('.pantry-transfer__row')].map((row) => ({
          shopping_item_id: Number(row.dataset.id),
          quantity: Number(row.querySelector('.pantry-transfer__qty').value) || 1,
          unit: row.querySelector('.pantry-transfer__unit').value,
          location_id: locationId,
        }));

        btn.disabled = true;
        try {
          const res = await api.post('/pantry/import-shopping', { list_id: listId, items });
          const stored = (res.data?.added ?? 0) + (res.data?.merged ?? 0);

          if (clearList && stored) {
            // Zweiter, getrennter Aufruf: der Vorrats-Router räumt bewusst
            // nichts im Einkauf ab, damit ein `pantry:write`-Token dort keine
            // Daten löschen kann (siehe routes/pantry.js).
            await api.delete(`/shopping/${listId}/items/checked`);
            const removed = checked.length;
            state.items = state.items.filter((i) => !checkedOf(i));
            updateItemsList(container);
            updateListCounter(listId, -removed, -removed);
            renderTabs(container);
          }

          closeModal({ force: true });
          // Der Vorrat ist ein einziges Ziel, der Toast nennt ihn also schon. Was er
          // NICHT nennt, ist der Lagerort - und der ist die Wahl, die der Nutzer im
          // Dialog gerade getroffen hat.
          const locationName = locationId
            ? (locations.find((l) => String(l.id) === String(locationId))?.name ?? '')
            : '';
          window.yuvomi.showToast(
            stored
              ? (locationName
                ? t('shopping.toPantryDoneAt', { count: stored, location: locationLabel(locationName) })
                : t('shopping.toPantryDone', { count: stored }))
              : t('shopping.toPantryNothing'),
            stored ? 'success' : 'info'
          );
          // Der Vorrats-Tab zeigt jetzt eine andere Zahl.
          refreshKitchenBadges();
        } catch (err) {
          btn.disabled = false;
          reportError(err, container);
        }
      });
    },
  });
}

/**
 * Steht der Weg „In den Vorrat" auf dieser Seite? Der Vorrat muss eingeschaltet
 * sein und der Betrachter dort schreiben duerfen (#1265). Die Kapsel und der
 * Hinweis im Leerzustand fragen beide hier.
 */
function pantryTransferOffered() {
  return !window.yuvomi?.isModuleDisabled?.('pantry') && mayTransferShoppingToPantry();
}

/**
 * Baut die Sammelaktions-Leiste neu auf, die an abgehakten Artikeln hängt.
 * Reihenfolge: erst „In den Vorrat", dann „Erledigte löschen" — ein erledigter
 * Einkauf endet im Regal, nicht im Papierkorb, und die Übernahme räumt die Liste
 * auf Wunsch gleich mit ab.
 *
 * Die Leiste trägt eine erklärende Zeile („3 Artikel abgehakt.") - genau der Teil,
 * der im Kopf fehlte: dort standen zwei Buttons, ohne dass irgendwo stand, auf
 * welche Teilmenge sie wirken. Der Vorrat hatte diese Zeile schon, und der
 * Critique nannte sie als das, was funktioniert.
 *
 * `hidden` statt eines leeren Containers: die Leiste hat eine Fläche, einen Rahmen
 * und Polsterung - leer wäre sie ein sichtbarer 42px-Streifen über der Liste. Die
 * [hidden]-Durchsetzung für `.list-bulkbar` steht in layout.css, weil
 * `display: flex` das UA-`[hidden]` sonst schlägt.
 *
 * ZEIGT SICH NUR NOCH ALS FUENF-SEKUNDEN-FENSTER EINES NEUEN BATCHES (#1039),
 * ueber `pillPhase` gesteuert: `userChecked` markiert den EINEN Aufruf, der
 * einen frischen Batch eroeffnen darf (den echten Nutzer-Abhak-Klick aus
 * `toggleShoppingItem`); jeder andere Aufruf (Laden, Listenwechsel,
 * Rueckgaengig) aktualisiert eine bereits sichtbare Pille hoechstens, zeigt
 * aber nie von sich aus eine neue.
 */
function updateCheckedActions(container, { userChecked = false } = {}) {
  const checkedCount = state.items.filter((i) => checkedOf(i)).length;
  if (!checkedCount) {
    clearPillTimer();
    pillPhase = 'idle';
    pillInteracting = false;
    pillOwnerContainer = null;
    clearBulkPill();
    return;
  }

  // Weder ein frischer Nutzer-Treffer aus dem Ruhezustand noch eine schon
  // sichtbare Pille: verborgen bleiben (Ladezustand, Listenwechsel, oder ein
  // Batch, der schon einmal ausgeblendet wurde und noch nicht auf 0 fiel).
  if (!((userChecked && pillPhase === 'idle') || pillPhase === 'visible' || pillPhase === 'deferred')) {
    return;
  }

  const actions = [];
  // „In den Vorrat" schreibt in den VORRAT: abgeschaltet ODER ohne
  // Schreibrecht dort endete die Kapsel im Leeren bzw. im 403 (#1265).
  if (pantryTransferOffered()) {
    actions.push({
      label: t('shopping.toPantry'),
      onClick: () => openPantryTransfer(container),
    });
  }
  // Nur das Verb, nicht „Abgehakt löschen": das Label links nennt den Bezug,
  // und der ganze Satz steht im aria-label. Das Löschen der GANZEN Liste sitzt
  // woanders (Überlaufmenü) und hat einen eigenen Bestätigungsdialog.
  if (!readOnly()) actions.push({
    label: t('common.delete'),
    ariaLabel: t('shopping.clearChecked', { count: checkedCount }),
    // Die Zahl als Marke - sie wird sichtbar, wo das Subjekt links wegfällt
    // (unter 21rem Pillenbreite). Von den beiden Kapseln trägt sie diese, weil
    // ein „Löschen" ohne genanntes Objekt über einer Liste mit 23 Artikeln
    // gelesen werden kann wie „die Liste löschen".
    count: checkedCount,
    // DIE RÜCKFRAGE, UND ZWAR TROTZ DES UNDO (Critique 2026-08-13, P0). Die
    // Rücknahme war hier als Begründung geführt, sie zu lassen - sie hält
    // fünf Sekunden, sieht aus wie die Kapsel, die gerade danebenlag, und
    // steht 8px darunter. Das ist der Rettungsweg für einen Irrtum, den man
    // BEMERKT; die Frage ist der für den, den man nicht bemerkt.
    danger: true,
    confirm: { question: t('shopping.clearCheckedConfirm', { count: checkedCount }) },
    onClick: () => clearCheckedUndoable(container),
  });
  // Ohne eine einzige Aktion ist die Pille ein Satz ohne Anschluss - sie
  // erscheint dann gar nicht erst. Bei `shopping: read` kommt es ohnehin nie
  // dazu: nur das eigene Abhaken eroeffnet einen Batch.
  if (!actions.length) return;

  // KEINE Icons mehr. Sie kosteten je 12px Breite plus Abstand auf einer
  // Fläche, die einzeilig bleiben muss, und benannten nichts, was das Wort
  // daneben nicht schon sagt - „In den Vorrat" mit Archiv-Kiste, „Löschen" mit
  // Papierkorb. Auf dem Shell-Material trägt die Kapsel den Rang, nicht das
  // Zeichen darin (dieselbe Form wie .toast__undo).
  setBulkPill({
    label: t('shopping.checkedHint', { count: checkedCount }),
    actions,
  });

  if (pillPhase === 'idle') {
    // Nur hier moeglich, wenn userChecked die Bedingung oben erfuellt hat: ein
    // frischer Batch beginnt jetzt, mit genau EINER Fuenf-Sekunden-Frist.
    pillPhase = 'visible';
    pillOwnerContainer = container;
    wirePillInteractionGuards();
    schedulePillHide(container);
  }
  // 'visible'/'deferred': Zahl und Aktionen sind frisch, die laufende Frist
  // bzw. die Interaktions-Verlaengerung bleibt unangetastet (Anforderung: kein
  // Aufschub durch weitere Treffer).
}

/**
 * Abgehakte löschen, mit Undo-Fenster. Stand bis Etappe 5 als Zweig im
 * delegierten Klick-Handler von `container`; die Pille lebt seitdem in der
 * Shell und ist von dort aus nicht mehr erreichbar - sie ruft direkt.
 */
function clearCheckedUndoable(container) {
  if (readOnly()) return;
  const checked = state.items.filter((i) => checkedOf(i));
  const count   = checked.length;
  if (!count) return;

  const snapshot = checked.map((i) => ({ ...i }));
  // DIESELBE REGEL WIE BEIM EINZELNEN ARTIKEL, hier mit schwererem Preis:
  // `commit` schlug die Liste bisher ERST beim Ausfuehren nach. Ein
  // Listenwechsel im Undo-Fenster schickte das DELETE damit an die gerade
  // geoeffnete Liste und raeumte deren abgehakte Artikel ab - waehrend der
  // Snapshot zur alten gehoerte und sie also nicht zurueckholen konnte.
  const listId = state.activeListId;

  // Optimistisch entfernen - und als schwebend vermerken, damit eine
  // Live-Auffrischung im Undo-Fenster die Zeilen nicht zurueckbringt.
  for (const item of checked) pendingRemovals.set(item.id, { listId, checked: true, removedAt: null });
  state.items = state.items.filter((i) => !checkedOf(i));
  updateItemsList(container);
  updateListCounter(listId, -count, -count);
  renderTabs(container);

  scheduleUndoableDelete({
    message: t('shopping.itemsRemovedToast', { count }),
    commit: async ({ keepalive }) => {
      let response;
      try {
        // GENAU DIE ARTIKEL, DIE DIE SEITE ENTFERNT HAT - nicht, was beim
        // Eintreffen abgehakt ist. Hat jemand anderes im Undo-Fenster einen
        // weiteren Artikel abgehakt (und eine Auffrischung ihn hergebracht),
        // naehme die Route ohne Liste ihn mit, und das Zuruecknehmen braechte
        // nur den eigenen Schnappschuss zurueck.
        response = await api.delete(`/shopping/${listId}/items/checked`, {
          keepalive,
          body: JSON.stringify({ ids: checked.map((item) => item.id) }),
        });
      } catch (err) {
        // Sofort raeumen: `restore` bringt die Zeilen zurueck, und jede Antwort
        // darf sie wieder tragen.
        for (const item of checked) pendingRemovals.delete(item.id);
        throw err;
      }
      // Weniger als erbeten heisst: jemand hat einen der unseren im Fenster
      // zurueckgeholt, und der Server hat ihn behalten. Dann meint die Quittung
      // WENIGER als die eigene Anzeige, und rueckte sie die Marke vor, lade
      // keine Abfrage nach - die Zeile fehlte, bis die Liste sich das naechste
      // Mal bewegt. Also gilt sie nur, wenn der Server genau so viele entfernt
      // hat, wie die Seite entfernt hat - sonst sieht die naechste Abfrage die
      // Bewegung und holt die Zeile her.
      if (response?.deleted === count) acknowledgeOwnChange(response);
      confirmRemovals(checked.map((item) => item.id));
    },
    restore: (err) => {
      for (const item of checked) pendingRemovals.delete(item.id);
      if (state.activeListId === listId) {
        // Nur, was nicht schon wieder da ist - sonst stuende es zweimal.
        const vorhanden = new Set(state.items.map((i) => i.id));
        snapshot.forEach((item) => { if (!vorhanden.has(item.id)) state.items.push(item); });
        state.items.sort((a, b) => a.id - b.id);
        updateItemsList(container);
      }
      updateListCounter(listId, count, count);
      renderTabs(container);
      if (err) reportError(err, container);
    },
  });
}

function updateListCounter(listId, totalDelta, checkedDelta) {
  const list = state.lists.find((l) => l.id === listId);
  if (list) {
    list.item_total   = (list.item_total   || 0) + totalDelta;
    list.item_checked = (list.item_checked || 0) + checkedDelta;
  }
}

/**
 * Der Artikel steht jetzt auf einer anderen Liste (#1700): er verlaesst den
 * Bestand der Liste, von der er kam, beide Zaehler in den Reitern folgen, und
 * eine Meldung sagt, wohin er gegangen ist - die Zeile ist ja einfach weg.
 *
 * `fromListId` kommt vom Oeffnen des Dialogs: waehrend er offen war, kann der
 * Zettel gewechselt worden sein, und dann gehoert `state.items` einer anderen
 * Liste. Der Zaehler der Herkunft zieht ab, was die Zeile GEZEIGT hat - eine
 * noch offene Abhak-Absicht ist damit abgegolten, wie beim Loeschen.
 */
function itemMovedAway(container, moved, fromListId) {
  const before = state.items.find((i) => i.id === moved.id);
  const shownChecked = before ? Boolean(checkedOf(before)) : Boolean(moved.is_checked);
  // DIE ABSICHT GEHT MIT DEM ARTIKEL. Sie haengt an der Liste, von der er kam
  // (`intent.listId`), und nur eine Ladeantwort DIESER Liste kann sie erfuellen
  // (`settleIntents`) - dort steht er aber nie wieder. Bliebe sie liegen,
  // ueberlagerte sie den Artikel auf seiner neuen Liste fuer immer: jemand
  // nimmt den Haken zurueck, und dieses Geraet zeigt ihn weiter abgehakt. Ihre
  // Buchung ist mit dem Abzug der ANZEIGE unten abgegolten.
  intents.delete(moved.id);

  updateListCounter(fromListId, -1, shownChecked ? -1 : 0);
  updateListCounter(moved.list_id, 1, moved.is_checked ? 1 : 0);
  if (before && state.activeListId === fromListId) {
    state.items = state.items.filter((i) => i.id !== moved.id);
    updateItemsList(container);
  }
  renderTabs(container);

  const target = state.lists.find((l) => l.id === moved.list_id);
  window.yuvomi.showToast(t('shopping.itemMovedToast', { name: moved.name, list: target?.name ?? '' }), 'info');

  // DIE BUCHUNG OBEN IST EINE ANNAHME, DER SERVER DIE WAHRHEIT. Landet eine
  // Live-Auffrischung zwischen dem Schreiben des Umzugs und seiner Antwort,
  // traegt `state.lists` die Zaehler von NACH dem Umzug schon, und die beiden
  // Abzuege oben zaehlen ihn ein zweites Mal - der Feed laedt danach nicht
  // mehr nach, er hat die Aenderung ja gesehen. Die Listenantwort enthaelt
  // keine Artikel, an ihr laesst sich also nicht ablesen, ob sie den Umzug
  // schon traegt. Deshalb wird nachgelesen: diese Antwort beginnt nach dem
  // Umzug und ersetzt jede fruehere (`loadLists`).
  return refreshListCounters(container);
}

/**
 * Die Zaehler der Reiter vom Server nachlesen, still: scheitert es, bleibt der
 * letzte Stand stehen (dieselbe Regel wie `refreshFromFeed`).
 */
async function refreshListCounters(container) {
  const previous = state.lists;
  await loadLists();
  if (state.listsError) {
    state.listsError = null;
    state.lists = previous;
    return;
  }
  renderTabs(container);
}

function openMealPlanImport(container) {
  if (!state.activeListId) return;
  // Zweite Linie hinter dem Menue (Regel 2 in utils/module-access.js).
  if (!mayImportMealPlan(state.activeListId)) return;
  const today = todayKey();
  const defaultTo = addLocalDays(today, 6);

  openModal({
    title: t('shopping.importMealsTitle'),
    size: 'sm',
    content: `
      <form id="shopping-import-meals-form" class="shopping-import-meals-form" novalidate autocomplete="off">
        <div class="form-group">
          <label class="form-label" for="shopping-import-from">${t('calendar.fromLabel')}</label>
          <yuvomi-datepicker type="date" id="shopping-import-from" value="${esc(today)}"></yuvomi-datepicker>
        </div>
        <div class="form-group">
          <label class="form-label" for="shopping-import-to">${t('calendar.toLabel')}</label>
          <yuvomi-datepicker type="date" id="shopping-import-to" value="${esc(defaultTo)}"></yuvomi-datepicker>
        </div>
        <p class="form-hint" id="shopping-import-preview" role="status" aria-live="polite"></p>
        <div class="modal-panel__footer modal-panel__footer--plain">
          <button type="button" class="btn btn--secondary" id="shopping-import-cancel">${t('common.cancel')}</button>
          <!-- Startet deaktiviert und wird von updatePreview() freigeschaltet, sobald
               der Zeitraum Zutaten enthaelt. Die Schwesteraktion „Plan zufaellig
               fuellen" macht das seit dem Audit korrekt; hier blieb „Uebernehmen"
               bei 0 Treffern klickbar und quittierte mit einem Info-Toast, dass
               nichts passiert ist (Critique 2026-07-30, P2). -->
          <button type="submit" class="btn btn--primary" id="shopping-import-submit" disabled>${t('common.apply')}</button>
        </div>
      </form>`,
    onSave: (panel) => {
      const form = panel.querySelector('#shopping-import-meals-form');
      const cancelBtn = panel.querySelector('#shopping-import-cancel');
      cancelBtn?.addEventListener('click', () => closeModal());

      // Vorschau vor dem Import (Audit A1-22): dieselbe Route rechnet mit
      // preview:true nur, statt zu schreiben - der Dialog sagt, was passiert.
      const previewEl = panel.querySelector('#shopping-import-preview');
      const submitBtn = panel.querySelector('#shopping-import-submit');
      async function updatePreview() {
        const from = panel.querySelector('#shopping-import-from')?.value || '';
        const to = panel.querySelector('#shopping-import-to')?.value || '';
        if (!from || !to || !previewEl) return;
        // Die Rechte koennen sich aendern, waehrend der Dialog offen steht; die
        // Vorschau verlangt serverseitig dieselben zwei wie der Import (#1290).
        if (!mayImportMealPlan(state.activeListId)) return;
        try {
          const data = await api.post(`/shopping/${state.activeListId}/import-meal-plan`, { from, to, preview: true });
          const transferred = Number(data.data?.transferred) || 0;
          const meals = Number(data.data?.meals) || 0;
          // Zwei Zahlachsen, eine Pluralmechanik: t() dekliniert nur über
          // `count`. Die Mahlzeiten-Angabe kommt deshalb als eigener, selbst
          // pluralisierter Teilstring herein (Audit A2-21: "aus 1 Mahlzeiten").
          previewEl.textContent = transferred
            ? t('shopping.importMealsPreview', {
              count: transferred,
              mealsText: t('shopping.importMealsPreviewMeals', { count: meals }),
            })
            : t('shopping.importMealsEmpty');
          submitBtn.disabled = !transferred;
        } catch {
          previewEl.textContent = '';
          // Vorschau fehlgeschlagen: nicht sperren. Der Nutzer soll es versuchen
          // duerfen, statt an einem toten Knopf zu haengen, weil eine
          // Nebenanfrage scheiterte.
          submitBtn.disabled = false;
        }
      }
      updatePreview();
      panel.querySelector('#shopping-import-from')?.addEventListener('change', updatePreview);
      panel.querySelector('#shopping-import-to')?.addEventListener('change', updatePreview);
      form?.addEventListener('submit', async (e) => {
        e.preventDefault();
        const from = panel.querySelector('#shopping-import-from')?.value || '';
        const to = panel.querySelector('#shopping-import-to')?.value || '';
        if (!from || !to) return;
        if (!mayImportMealPlan(state.activeListId)) return;
        try {
          const data = await api.post(`/shopping/${state.activeListId}/import-meal-plan`, { from, to });
          if (!data.data?.transferred) {
            window.yuvomi.showToast(t('shopping.importMealsEmpty'), 'default');
            return;
          }
          await Promise.all([loadLists(), loadItems(state.activeListId)]);
          renderTabs(container);
          renderListContent(container);
          wireListContentEvents(container);
          // force: siehe openItemDetails - ein geänderter Zeitraum ist nach dem
          // Import nichts, was noch zu verwerfen wäre.
          closeModal({ force: true });
          const count = Number(data.data.transferred) || 0;
          window.yuvomi.showToast(t('meals.transferSuccess', { count }), 'success');
        } catch (err) {
          reportError(err, container);
        }
      });
    },
  });
}

// --------------------------------------------------------
// API-Aktionen
// --------------------------------------------------------

async function loadLists() {
  // In der Ladeordnung, weil die Schwebe der Loeschungen wissen muss, ob diese
  // Antwort vor oder nach einem DELETE begonnen hat (siehe `pendingRemovals`).
  const startedAt = beginLoad();
  try {
    const data   = await api.get('/shopping');
    // EINE AELTERE ANTWORT ERSETZT KEINE JUENGERE. Zwei Listenantworten koennen
    // sich ueberholen (eine Live-Auffrischung und das Nachladen nach einem
    // Umzug, #1700): die frueher begonnene hat den Server frueher gelesen und
    // truege die Zaehler von vor dem Umzug nach - und sie blieben, weil die
    // Quittung den Feed schon vorgerueckt hat. Dieselbe Regel wie
    // `_appliedLoad` bei den Artikeln.
    if (startedAt < _appliedListsLoad) return;
    _appliedListsLoad = startedAt;
    state.lists  = data.data ?? [];
    // Der Zaehler im Reiter zeigt, was die Zeilen zeigen: ein Artikel im
    // Undo-Fenster ist fuer den Server noch da, fuer die Anzeige nicht mehr
    // (`pendingRemovals`) - sonst zaehlte die Auffrischung ihn wieder mit, und
    // das Zuruecknehmen buchte ihn ein zweites Mal dazu. Dasselbe fuer eine
    // Antwort, die vor dem DELETE losging: der Server zaehlte ihn da noch.
    for (const entry of pendingRemovals.values()) {
      if (removalHides(entry, startedAt)) updateListCounter(entry.listId, -1, entry.checked ? -1 : 0);
    }
    state.listsError = null;
  } catch (err) {
    // Auch eine GESCHEITERTE aeltere Antwort ersetzt keine juengere: ihr
    // Fehler sagt nichts mehr ueber den Stand, den die Seite schon zeigt.
    if (startedAt < _appliedListsLoad) return;
    // Und sie ist selbst die juengste: eine noch aeltere Antwort, die erst
    // danach eintrifft, traegt einen Stand von davor und kommt nicht mehr zum Zug.
    _appliedListsLoad = startedAt;
    console.error('[Shopping] loadLists Fehler:', err);
    state.lists = [];
    // Fehler statt Toast: der Toast verging, während darunter „Keine Listen ·
    // [Neue Liste erstellen]" stehen blieb - bei 31 vorhandenen Artikeln
    // (Critique P0, 2026-07-30).
    state.listsError = err;
  } finally {
    endLoad(startedAt);
  }
}

async function loadCategories({ keepOnError = false } = {}) {
  try {
    const data       = await api.get('/shopping/categories');
    state.categories = data.data ?? [];
  } catch {
    // `keepOnError`: ein stilles Nachladen behaelt den letzten Stand, statt
    // aus einem Netzfehler "es gibt keine" zu machen (`reloadAfterGone`).
    if (!keepOnError) state.categories = [];
  }
}

/* Laeden und Waehrung fuer das Preisfeld (#1003).
 *
 * Beide Ausfaelle sind still und harmlos: ohne Laeden bleibt die Auswahl leer
 * (der Preis laesst sich trotzdem eintragen), ohne Waehrung gilt EUR. Ein
 * Einkaufszettel, der wegen eines Nebenfeldes gar nicht aufgeht, waere der
 * schlechtere Tausch. */
async function loadStores({ keepOnError = false } = {}) {
  try {
    const data   = await api.get('/shopping/stores');
    state.stores = data.data ?? [];
  } catch {
    if (!keepOnError) state.stores = [];
  }
  try {
    const prefs    = await api.get('/preferences');
    state.currency = prefs.data?.currency ?? 'EUR';
  } catch { /* EUR bleibt */ }
}

async function loadItems(listId) {
  const startedAt = beginLoad();
  // try/finally um den ganzen Rundlauf: die Ladeordnung schliesst ihn ab, ob
  // er angewandt, verworfen oder gescheitert ist (siehe `endLoad`).
  try {
    // `getWithSource`, weil dieser Pfad in der Offline-Whitelist des Service
    // Workers steht (`API_CACHE_WHITELIST` in sw.js): faellt das Netz aus, kommt
    // die zuletzt gecachte Antwort mit Status 200 zurueck, und die ist von einer
    // frischen sonst nicht zu unterscheiden.
    const { data, fromCache } = await api.getWithSource(`/shopping/${listId}/items`);
    // Ein Rundlauf kann von einem Listenwechsel ueberholt werden. Alle sechs
    // Aufrufer laden die GERADE aktive Liste - `switchList` setzt
    // `state.activeListId` sogar vor dem Warten -, die Antworten kommen aber in
    // beliebiger Reihenfolge zurueck. Wer nicht mehr die aktive Liste ist, darf
    // den globalen Stand nicht mehr anfassen: sonst stuenden die Artikel der
    // alten Liste unter dem neuen Reiter, und die naechste Bearbeitung traefe
    // die falschen. Das Fenster ist seit #1066 breiter geworden, weil die
    // Auffrischung des Kategorie-Managers laeuft, waehrend die Seite wieder
    // bedienbar ist.
    if (state.activeListId !== listId) return;
    // Wer aelter ist als das, was schon steht, fasst den Stand nicht mehr an.
    // Die Wache darueber deckt das nicht ab: dieselbe Liste, zwei Rundlaeufe.
    // Nur eine netzfrische Antwort setzt die Marke - bei wackligem Netz scheitert
    // die spaeter begonnene Anfrage oft zuerst und wird aus dem Cache bedient.
    if (startedAt < (_appliedLoad.get(listId) ?? 0)) return;
    // EINE GECACHTE ANTWORT ERSETZT KEINEN FRISCHEREN STAND. Sie ist beliebig
    // alt; steht fuer diese Liste schon etwas Netzfrisches, waere sie ein
    // Rueckschritt - offline gehoert der zuletzt bekannte Stand auf den Schirm,
    // nicht ein aelterer. Nur wenn noch gar nichts geladen wurde, ist sie das
    // Beste, was es gibt.
    // ... aber nur, wenn `state.items` diese Liste ueberhaupt zeigt. Gehoert der
    // Bestand einer anderen, ist die gecachte Antwort das Beste, was es gibt -
    // und allemal besser als die Artikel der falschen Liste.
    if (fromCache && _appliedLoad.has(listId) && _itemsListId === listId) return;
    if (!fromCache) _appliedLoad.set(listId, startedAt);

    // `state.items` traegt NUR den Serverstand - die Absichten liegen daneben und
    // ueberlagern beim Zeichnen. Deshalb wird hier nichts aufgetragen; es faellt
    // nur, was die Antwort erfuellt hat.
    // EIN BESTAETIGTER ARTIKEL WIRD VON EINER AELTEREN ANTWORT NICHT
    // ZURUECKGEDREHT. Die Antwort selbst bleibt gueltig - ihre uebrigen Artikel,
    // die Liste und die Kategorien werden gebraucht -, nur der eine Wert, von
    // dem wir sicher wissen, dass er juenger ist, bleibt stehen.
    const vorherige = new Map(state.items.map((i) => [i.id, i]));
    // EIN LOKAL GELOESCHTER ARTIKEL KOMMT NICHT ZURUECK, solange sein Undo-Fenster
    // laeuft: der Server hat ihn noch, die Anzeige nicht mehr (`pendingRemovals`).
    // Nur so ist der Bestand nach einer Auffrischung "Serverstand ohne die
    // schwebenden Loeschungen" - und die Quittung des spaeteren DELETE stimmt.
    // Und auch nicht aus einer Antwort, die VOR dem DELETE losging und erst
    // danach eintrifft: sie hat den Server gelesen, als er den Artikel noch hatte.
    const frisch = (data.data ?? []).filter((i) => {
      const entry = pendingRemovals.get(i.id);
      return !entry || !removalHides(entry, startedAt);
    });
    for (const item of frisch) {
      const bestaetigt = settledAt.get(item.id);
      if (bestaetigt != null && bestaetigt >= startedAt) {
        const alt = vorherige.get(item.id);
        if (alt) item.is_checked = alt.is_checked;
      }
    }
    state.items = frisch;
    _itemsListId = listId;
    settleIntents(state.items, listId, { fromCache, startedAt });
    state.activeList = data.list ?? null;
    // Dem Feed sagen, welchen Stand die Seite jetzt haelt: die Antwort traegt
    // die Laufnummer, zu der ihre Artikel gehoeren. Auch eine gecachte - sie
    // IST der Stand, den die Seite zeigt, und liegt er unter der Laufnummer,
    // ist das Nachladen bei der naechsten Abfrage genau richtig.
    _liveFeed?.hold(listId, data.version);
    // Kategorien aus API-Antwort übernehmen wenn vorhanden (immer aktuell)
    if (data.categories?.length) state.categories = data.categories;
  } finally {
    endLoad(startedAt);
  }
}

async function switchList(listId, container) {
  // Die Pille gehoert zur Teilmenge EINER Liste (dieselbe Regel wie beim
  // Seitenwechsel in router.js) - eine laufende Frist der alten Liste darf die
  // neue nicht treffen (#1039).
  resetPillMachine();
  clearBulkPill();
  // Die Pause gehoert den Zeilen der alten Liste (#1816).
  resetPlacementHold();
  state.activeListId = listId;
  state.collapsedCategories = loadCollapsedCategories(state.currentUserId, listId);
  state.tickedOpen = loadTickedOpen(state.currentUserId, listId);
  renderTabs(container);
  // Lade-Feedback beim Listenwechsel: dimmt den alten Inhalt (CSS), meldet
  // Screenreadern „busy" — bis renderListContent den neuen Inhalt setzt.
  container.querySelector('#list-content')?.setAttribute('aria-busy', 'true');
  try {
    await loadItems(listId);
    state.itemsError = null;
  } catch (err) {
    console.error('[Shopping] loadItems Fehler:', err);
    clearItems();
    state.activeList = state.lists.find((l) => l.id === listId) ?? null;
    state.itemsError = err;
  }
  renderListContent(container);
  wireListContentEvents(container);
}

// --------------------------------------------------------
// Live-Aktualisierung
// --------------------------------------------------------

/**
 * Takt der Laufnummern-Abfrage (GET /shopping/versions), solange der Tab
 * sichtbar ist. Zehn Sekunden sind der Tausch zwischen "es hat sich
 * aktualisiert" neben jemandem im Laden und einem Server, der von jedem
 * offenen Zettel eine kleine Anfrage je Takt bekommt - und einem Haushalt
 * hinter EINER Adresse, der sich den Limiter (300/min) teilt.
 */
const LIVE_POLL_MS = 10_000;

/** Controller der laufenden Live-Verdrahtung: faellt mit dem Router-Signal und beim naechsten render(). */
let _liveController = null;
/** Der laufende Feed - fuer die Quittung eigener Schreibvorgaenge. */
let _liveFeed = null;
/** Das Router-Signal des letzten Aufbaus - der Retry-Knopf reicht es an sein render() weiter. */
let _routeSignal = null;

/**
 * Die Quittung eines eigenen Schreibvorgangs an den Feed reichen.
 *
 * Die Artikel-Routen antworten mit `list_change: { list_id, before, after }`.
 * Ist `before` der Stand, den der Feed zuletzt gesehen hat, ist alles bis
 * `after` das eigene Werk, und die naechste Abfrage laedt die Liste nicht
 * umsonst nach - das waeren sonst zwei Anfragen je Tab und Haken, auch fuer
 * den Tab, der den Haken gesetzt hat.
 */
function acknowledgeOwnChange(response) {
  _liveFeed?.acknowledge(response?.list_change);
}

/**
 * Was ein frischer Stand an der Zeilen-Ansicht aendert.
 *
 * Zwei Faelle, und sie sind mit Absicht verschieden gross. Hat sich nur der
 * Abgehakt-Zustand bewegt - der haeufige Fall, zwei Leute im selben Laden -,
 * wird die Zeile umgefaerbt und als Knoten umgestellt, wie beim eigenen
 * Antippen: kein Neuaufbau, keine Einblend-Animation, die Scroll-Position
 * bleibt (#276). Abgehaktes zieht in den Abschnitt am Listenende (#1816) -
 * sofort, solange hier niemand tippt, sonst mit der laufenden Pause
 * (`placeOrHold`), nicht unter dem Finger weg. Ist ein Artikel dazugekommen, verschwunden,
 * umbenannt oder umsortiert, wird die Liste neu gebaut; das ist der Fall, den
 * die Animation meint. Umsortiert heisst: sein `sort_order` hat sich bewegt -
 * die Reihenfolge der ANTWORT allein nicht, denn die aendert sich schon mit
 * einem Haken (Abgehaktes sortiert der Server ans Ende), und ein Haken darf
 * keinen Neuaufbau kosten. Das Ziehen eines anderen bewegt `sort_order`; das
 * Abhaken laesst es stehen.
 *
 * Verglichen wird der SERVERSTAND vor und nach dem Laden, nicht das DOM: die
 * Seite haelt beides ohnehin deckungsgleich, und `updateItemRow` zeichnet die
 * Ueberlagerung mit der eigenen Absicht selbst (`checkedOf`).
 */
function liveRefreshPlan(previous, fresh) {
  const shape = (i) => JSON.stringify([
    i.id, i.category, i.name, i.quantity ?? '', i.notes ? 1 : 0, i.url ? 1 : 0,
    i.price_cents ?? '', i.store_id ?? '', i.tags ?? [], i.sort_order ?? '',
  ]);
  const before = previous.map(shape).sort();
  const after  = fresh.map(shape).sort();
  if (before.length !== after.length || before.some((s, idx) => s !== after[idx])) {
    return { rebuild: true, changed: [] };
  }
  const checkedBefore = new Map(previous.map((i) => [i.id, i.is_checked]));
  return {
    rebuild: false,
    changed: fresh.filter((i) => checkedBefore.get(i.id) !== i.is_checked),
  };
}

/**
 * Eine Liste nachladen, weil der Feed sie gemeldet hat.
 *
 * Still bei Fehlern, wie der stille Refresh des Dashboards: der Zettel zeigt
 * weiter den letzten bekannten Stand, und die naechste Meldung versucht es
 * wieder. Nur die AKTIVE Liste laedt ihre Artikel; fuer jede andere reicht die
 * Listenzeile mit ihrem Zaehler, und `switchList` laedt ohnehin frisch.
 *
 * Die eigene Bearbeitung ueberlebt das Nachladen: `loadItems` traegt nur den
 * Serverstand ein, die Absicht liegt daneben und faellt erst, wenn die Antwort
 * sie traegt (`settleIntents`). Deshalb darf der Feed auch die eigene
 * Aenderung melden - die Antwort darauf ist genau die, die die Absicht erfuellt.
 */
async function refreshFromFeed(container, listId, signal) {
  if (state.listsError) return;
  // Ohne aktive Liste (Leerzustand) gibt es keine Artikel nachzuladen - das
  // Nachladen nach "gibt es nicht mehr" kommt auch von dort.
  const active        = listId != null && listId === state.activeListId;
  const previous      = state.items;
  const previousLists = state.lists;
  // BEIDE Antworten abwarten, nicht nur bis zur ersten Ablehnung. `loadLists`
  // faengt selbst und vermerkt in `state.listsError`; brach `Promise.all` mit
  // dem Scheitern von `loadItems` ab, waehrend `loadLists` noch unterwegs war,
  // stand der Merker beim Lesen unten noch auf null und wurde DANACH gesetzt -
  // und blieb: die Wache oben wies ab da jede Meldung ab, ohne Fehlerbild,
  // mit leeren Reitern, bis zum naechsten Seitenaufbau.
  const [, items] = await Promise.allSettled([loadLists(), active ? loadItems(listId) : null]);
  const itemsFailed = items.status === 'rejected';
  if (itemsFailed) console.warn('[Shopping] Live-Aktualisierung fehlgeschlagen:', items.reason);
  // loadLists() faengt selbst und vermerkt den Fehler fuer den Seitenaufbau,
  // wo er ein Fehlerbild mit Wiederholung ergibt. Fuer eine STILLE
  // Auffrischung ist derselbe Vermerk das Gegenteil von still: leere Reiter
  // und ein Merker, der jede weitere Meldung abwiese. Also zurueck auf den
  // letzten Stand, und die naechste Meldung versucht es wieder.
  const listsFailed = Boolean(state.listsError);
  if (listsFailed) {
    state.listsError = null;
    state.lists = previousLists;
  }
  if (signal.aborted) return;
  // Was `loadItems` in `state.items` eingetragen hat, kommt auf den Schirm -
  // auch wenn die Listenzeile daneben gescheitert ist. Kehrte die Auffrischung
  // hier um, hielte die Seite einen Stand, den sie nie gezeichnet hat; die
  // naechste Meldung vergleicht Serverstand mit Serverstand (`liveRefreshPlan`),
  // faende nichts Neues, und die Zeile erschiene nie.
  //
  // Die aktive Liste ist weg - jemand anderes hat sie geloescht. Der Zettel
  // wechselt auf die erste verbliebene oder zeigt den Leerzustand, statt eine
  // Liste zu zeigen, die es nicht mehr gibt. Das kann nur eine frische
  // Listenantwort sagen, nicht der zurueckgeholte Stand.
  if (!listsFailed && state.activeListId != null && !state.lists.some((l) => l.id === state.activeListId)) {
    if (state.lists.length) {
      await switchList(state.lists[0].id, container);
      return;
    }
    state.activeListId = null;
    state.activeList = null;
    clearItems();
    renderTabs(container);
    renderListContent(container);
    return;
  }
  renderTabs(container);
  // Inzwischen umgeschaltet: switchList zeichnet die neue Liste selbst.
  if (!active || state.activeListId !== listId) return;
  // Gescheitert heisst: `state.items` ist unangetastet, es gibt nichts zu zeichnen.
  if (itemsFailed) return;
  if (state.itemsError) {
    // Der Fehlerzustand von vorhin ist ueberholt - die Antwort ist da.
    state.itemsError = null;
    updateItemsList(container);
    return;
  }
  const plan = liveRefreshPlan(previous, state.items);
  if (plan.rebuild) {
    updateItemsList(container);
    return;
  }
  for (const item of plan.changed) {
    updateItemRow(container, item);
    // Fremdes Abhaken zieht die Zeile sofort um - solange hier niemand
    // tippt. Laeuft eine eigene Pause, wartet es mit ihr: eine Zeile, die
    // jemand anderes bewegt, verschiebt die Liste genauso unter dem Finger.
    placeOrHold(container, item.id);
  }
  if (plan.changed.length) updateCheckedActions(container);
}

/**
 * Die Live-Aktualisierung eines Seitenaufbaus verdrahten. Alles haengt am
 * Signal DIESES Aufbaus (#976-Muster): der naechste Aufbau bricht den vorigen
 * ab, und das Router-Signal reisst beide beim Verlassen der Seite mit.
 *
 * Der Feed fragt die Laufnummern im Takt ab, solange der Tab sichtbar ist,
 * und sofort, wenn er sichtbar wird oder den Fokus bekommt - das ist der
 * Moment, in dem jemand aufs Telefon schaut und den aktuellen Stand erwartet.
 *
 * Meldungen laufen durch EINE Warteschlange: zwei Listen in einer Antwort
 * ergeben ein Nachladen nach dem anderen, nicht zwei, die sich ueberholen.
 */
function wireLiveUpdates(container, routeSignal) {
  _liveController?.abort();
  const controller = createPageController(routeSignal);
  _liveController = controller;
  const { signal } = controller;
  if (signal.aborted) return;

  const queue = new Set();
  let draining = false;
  const drain = async () => {
    if (draining) return;
    draining = true;
    try {
      while (queue.size && !signal.aborted) {
        const [listId] = queue;
        queue.delete(listId);
        await refreshFromFeed(container, listId, signal);
      }
    } finally {
      draining = false;
    }
  };
  const request = (listId) => {
    if (signal.aborted || listId == null) return;
    queue.add(listId);
    drain();
  };

  const feed = startLiveFeed({
    fetchVersions: async () => (await api.get('/shopping/versions')).data ?? [],
    onChange: request,
    signal,
    intervalMs: LIVE_POLL_MS,
  });
  _liveFeed = feed;
  signal.addEventListener('abort', () => { if (_liveFeed === feed) _liveFeed = null; });

  // Die erste Abfrage setzt die Marken; sie laeuft neben dem Laden der Seite.
  feed.poll();
  const wake = () => { if (!document.hidden) feed.poll(); };
  document.addEventListener('visibilitychange', wake, { signal });
  window.addEventListener('focus', wake, { signal });
}

// --------------------------------------------------------
// Fehler melden - und nachladen, wenn das Ziel verschwunden ist (#1909)
// --------------------------------------------------------

/**
 * DER EINE WEG, AUF DEM DIESE SEITE EINEN FEHLER MELDET.
 *
 * Der Toast sagt den Satz der App (`errorSentence`). Nennt der Server als
 * Grund, dass es das Ziel der Handlung nicht mehr gibt (`isGone`: Liste,
 * Artikel, Laden, Kategorie), war der Stand der Seite veraltet - jemand anderes
 * im Haushalt hat es geloescht. Dann holt die Seite den frischen Stand selbst
 * (`reloadAfterGone`); der Satz raet nicht mehr zum Neuladen, weil es nichts
 * mehr zu tun gibt. Der Toast bleibt: er sagt, WARUM etwas verschwunden ist.
 *
 * Erkannt wird am `reason`, nie am Text und nie am blanken Status 404.
 *
 * EINE AUSNAHME, und sie kommt hier gar nicht an: wer einen Artikel LOESCHT,
 * den es nicht mehr gibt, hat sein Ziel erreicht (`isAlreadyDeleted` in
 * `deleteItemUndoable`) - kein Toast, nur das stille Nachladen.
 *
 * @param {unknown} err
 * @param {Element} container
 * @param {string} [fallbackKey] - der allgemeine Satz dieser Stelle
 */
function reportError(err, container, fallbackKey) {
  window.yuvomi.showToast(errorSentence(err, fallbackKey), 'danger');
  if (isGone(err)) reloadAfterGone(container);
}

/** Laeuft gerade ein Nachladen, und wurde waehrenddessen ein weiteres erbeten? */
let _goneReloadRunning = null;
let _goneReloadWanted = false;
/** Der offene Bearbeiten-Dialog eines Artikels: { id, panel } - oder nichts. */
let _itemDialog = null;
const NEVER_ABORTED = Object.freeze({ aborted: false });

/**
 * Listen, Laeden, Kategorien und die Artikel der aktiven Liste neu holen und
 * zeichnen, weil der Server gemeldet hat, dass etwas nicht mehr da ist.
 *
 * - EIN Lauf zur Zeit. Ein zweiter Fehler waehrenddessen bestellt genau einen
 *   weiteren Lauf danach (sein Ding kann nach dem Lesen des ersten verschwunden
 *   sein), nie einen parallelen.
 * - KEINE SCHLEIFE: das Nachladen meldet seine eigenen Fehler nirgends, also
 *   kann es sich nicht selbst wieder ausloesen. Scheitert es, bleibt der
 *   letzte Stand stehen - wie bei der Live-Auffrischung.
 * - Die eigene Bearbeitung ueberlebt: es ist derselbe Weg wie die
 *   Live-Auffrischung (`refreshFromFeed`), mit Ladeordnung, Absichten und
 *   schwebenden Loeschungen. Auch der Fall "die aktive Liste ist weg" wird
 *   dort entschieden: erste verbliebene Liste oder Leerzustand.
 */
function reloadAfterGone(container) {
  _goneReloadWanted = true;
  if (_goneReloadRunning) return _goneReloadRunning;
  const run = (async () => {
    try {
      while (_goneReloadWanted) {
        _goneReloadWanted = false;
        await reloadAfterGoneOnce(container);
      }
    } catch (err) {
      console.warn('[Shopping] Nachladen nach "gibt es nicht mehr" fehlgeschlagen:', err);
    } finally {
      _goneReloadRunning = null;
      _goneReloadWanted = false;
    }
  })();
  _goneReloadRunning = run;
  return run;
}

async function reloadAfterGoneOnce(container) {
  const signal = _liveController?.signal ?? NEVER_ABORTED;
  const listBefore = state.activeListId;
  await Promise.all([
    loadCategories({ keepOnError: true }),
    loadStores({ keepOnError: true }),
  ]);
  await refreshFromFeed(container, listBefore, signal);
  if (signal.aborted || container?.isConnected === false) return;
  // Was die Seite zur AUSWAHL anbietet, kommt aus demselben Stand: die
  // Kategorie im Eingabefeld und die Felder eines offenen Dialogs. Getipptes
  // bleibt stehen - nur die Auswahl wird ersetzt, nicht das Formular.
  refreshQuickAddChoices(container);
  // EIN DIALOG ZU ETWAS, DAS ES NICHT MEHR GIBT, GEHT ZU. Die aktive Liste ist
  // weg: jeder Dialog dieser Seite meinte sie. Oder der Artikel, den der
  // Bearbeiten-Dialog zeigt, ist weg: Speichern kann nie mehr gelingen, und der
  // Toast hat gesagt, warum. In jedem anderen Fall (Laden, Kategorie oder
  // Zielliste verschwunden) bleibt der Dialog mit den Eingaben offen und
  // bekommt die frische Auswahl.
  const dialog = _itemDialog;
  const listGone = listBefore != null && state.activeListId !== listBefore;
  const itemGone = Boolean(dialog) && _itemsListId === state.activeListId
    && !state.items.some((i) => i.id === dialog.id);
  if (listGone || itemGone) {
    _itemDialog = null;
    await closeModal({ force: true });
  } else if (dialog) {
    refreshItemDialogChoices(dialog.panel);
  }
}

/**
 * Die Optionen einer Auswahl ersetzen und die Wahl behalten, wenn es sie noch
 * gibt. Sonst gilt `fallback`, sonst die erste Option.
 */
function setOptions(el, options, fallback) {
  if (!el?.replaceChildren) return;
  const keep = el.value;
  el.replaceChildren(...options.map(({ value, label }) => {
    const option = document.createElement('option');
    option.value = String(value);
    if (label != null) option.textContent = label;
    return option;
  }));
  const has = (v) => v != null && options.some((o) => String(o.value) === String(v));
  if (has(keep)) el.value = keep;
  else if (has(fallback)) el.value = String(fallback);
}

const categoryOptions = () => state.categories.map((c) => ({ value: c.name, label: categoryLabel(c.name) }));

function refreshQuickAddChoices(container) {
  const select = container?.querySelector?.('#item-cat-select');
  if (!select) return;
  const before = select.value;
  setOptions(select, categoryOptions(), DEFAULT_CATEGORY_NAME);
  // Die gewaehlte Kategorie gibt es nicht mehr: das Feld steht wieder auf dem
  // Standard, und das ist keine Wahl von Hand mehr.
  if (select.value !== before) quickAddCategoryChosen = false;
}

function refreshItemDialogChoices(panel) {
  if (!panel?.querySelector) return;
  setOptions(panel.querySelector('#item-details-cat'), categoryOptions());
  setOptions(
    panel.querySelector('#item-details-list'),
    state.lists.map((l) => ({ value: l.id, label: l.name })),
    state.activeListId,
  );
  setOptions(
    panel.querySelector('#item-details-store-options'),
    state.stores.map((st) => ({ value: st.name })),
  );
}

// --------------------------------------------------------
// Event-Verdrahtung
// --------------------------------------------------------

function wireTabBar(container) {
  container.querySelector('#list-tabs-bar')?.addEventListener('click', async (e) => {
    const target = e.target.closest('[data-action]');
    if (!target) return;

    if (target.dataset.action === 'switch-list') {
      await switchList(Number(target.dataset.id), container);
    }

    // Derselbe Riegel wie im Inhalt: nur die Positivliste kommt durch.
    if (readOnlyBlocks(target.dataset.action)) return;

    if (target.dataset.action === 'new-list') {
      const name = await promptModal(t('shopping.newListPrompt'));
      if (!name) return;
      try {
        const data = await api.post('/shopping', { name });
        state.lists.push({ ...data.data, item_total: 0, item_checked: 0 });
        await switchList(data.data.id, container);
        refocusAfterRender();
      } catch (err) {
        reportError(err, container);
      }
    }
  });
}

function wireListContentEvents(container) {
  // Delegations-Wurzel ist der Modul-Root, nicht #list-content: die Aktionen der
  // Liste (rename-list, import-meals, manage-categories, delete-list) stehen im
  // Überlaufmenü der Chip-Leiste und liegen damit außerhalb des Inhalts.
  // .shopping-page ist der nächste gemeinsame Vorfahre und wird - genau wie
  // #list-content vorher - pro render() genau einmal erzeugt, womit die
  // Einmal-Bindung unten weiter gilt.
  const root = container.querySelector('.shopping-page');
  if (!root) return;

  // Die Klick-Delegation nur EINMAL anhängen. renderListContent ersetzt lediglich
  // die Kinder (replaceChildren), nicht das Element selbst - würde der Listener
  // bei jedem switchList/rename erneut gebunden, feuerte ein Toggle-Klick
  // mehrfach und höbe sich auf (Issue #398).
  // Positionierung und Schließen der Überlaufmenüs. Idempotent, hängt an
  // derselben stabilen Wurzel wie die Klick-Delegation.
  installPopoverMenus(root);

  if (root.dataset.eventsWired) return;
  root.dataset.eventsWired = 'true';

  root.addEventListener('click', async (e) => {
    // ---- Kategorie auf-/zuklappen (#1039) ----
    // Eigener, frueher Zweig statt eines weiteren [data-action]-Falls: die
    // uebrigen Aktionen loesen serverseitige Aenderungen aus, dieser hier
    // toggelt nur lokal sichtbares DOM - kein `await`, kein try/catch noetig.
    const catToggle = e.target.closest('[data-category-toggle]');
    if (catToggle) {
      toggleCategoryCollapse(catToggle);
      return;
    }
    // ---- Abschnitt „Abgehakt" auf-/zuklappen (#1816): ebenso nur lokal, und
    // deshalb auch bei `read` offen.
    const tickedToggle = e.target.closest('[data-ticked-toggle]');
    if (tickedToggle) {
      toggleTickedSection(tickedToggle);
      return;
    }

    const target = e.target.closest('[data-action]');
    if (!target) {
      // Der Zeilenklick hakt ab - bei `read` gibt es nichts abzuhaken.
      if (readOnly()) return;
      if (shouldIgnoreShoppingRowToggle(e.target)) return;
      const row = e.target.closest('.shopping-item');
      if (!row) return;
      const toggle = row.querySelector('[data-action="toggle-item"]');
      if (!toggle) return;
      await toggleShoppingItem(Number(row.dataset.itemId), Number(toggle.dataset.checked), container);
      return;
    }
    const action = target.dataset.action;

    // Der eine Riegel fuer alle Aktionen darunter (siehe READ_SAFE_ACTIONS):
    // das Markup nimmt die Affordanz, diese Zeile den Effekt eines Knotens,
    // der trotzdem stehen geblieben ist.
    if (readOnlyBlocks(action)) return;

    // ---- Artikel abhaken ----
    if (action === 'toggle-item') {
      const id      = Number(target.dataset.id);
      const checked = Number(target.dataset.checked);
      await toggleShoppingItem(id, checked, container);
    }

    // ---- Artikel-Details (URL/Notiz) bearbeiten ----
    if (action === 'item-details') {
      openItemDetails(Number(target.dataset.id), container);
    }

    // ---- Artikel löschen (mit Undo, 5s Fenster) ----
    if (action === 'delete-item') {
      deleteItemUndoable(Number(target.dataset.id), container);
    }

    // ---- Kategorien verwalten ----
    if (action === 'manage-categories') {
      openCategoryManager(container);
    }

    // ---- Laeden verwalten (#1003) ----
    if (action === 'manage-stores') {
      openStoreManager(container);
    }

    if (action === 'import-meals') {
      openMealPlanImport(container);
    }

    // ---- Abgehakt-Gruppe des Werkzeugmenues (R16): dieselben Handler wie
    // die Sammel-Pille. Die Rueckfrage vor dem Sammel-Loeschen bleibt
    // (Critique 2026-08-13, P0) - hier als Dialog, weil ein Menue keine
    // zweite Stufe in sich traegt.
    if (action === 'checked-to-pantry') {
      if (pantryTransferOffered()) await openPantryTransfer(container);
    }

    if (action === 'clear-checked') {
      const count = state.items.filter((i) => checkedOf(i)).length;
      if (!count) return;
      // Ohne `danger`: das Loeschen ist fuenf Sekunden lang ruecknehmbar,
      // der Dialog droht also mit nichts Unwiederbringlichem.
      const confirmed = await confirmModal(
        t('shopping.clearCheckedConfirm', { count }),
        { confirmLabel: t('common.delete') },
      );
      if (confirmed) clearCheckedUndoable(container);
    }

    if (action === 'send-list') {
      await openSendListDialog(container);
    }

    // ---- Liste duplizieren (#1103) ----
    if (action === 'duplicate-list') {
      await openDuplicateListDialog(container);
    }

    // ---- Liste umbenennen ----
    if (action === 'rename-list') {
      const newName = await promptModal(t('shopping.renameListPrompt'), state.activeList?.name ?? '');
      if (!newName || newName === state.activeList?.name) return;
      try {
        const data = await api.put(`/shopping/${state.activeListId}`, { name: newName });
        const idx  = state.lists.findIndex((l) => l.id === state.activeListId);
        if (idx >= 0) state.lists[idx].name = data.data.name;
        state.activeList = data.data;
        renderTabs(container);
        renderListContent(container);
        wireListContentEvents(container);
        refocusAfterRender();
      } catch (err) {
        reportError(err, container);
      }
    }

    // ---- Liste löschen ----
    //
    // Der Sicherheitsgradient war invertiert (Critique 2026-07-30, P2): ein
    // einzelner Artikel hatte Undo und keine Rückfrage, die ganze Liste des
    // Haushalts hatte eine Rückfrage und kein Undo - und die Rückfrage nannte nicht
    // einmal, wie viel sie vernichtet („Liste \"Weekly Shop\" und alle Artikel
    // löschen?" - wie viele?).
    //
    // Jetzt BEIDES, und in dieser Reihenfolge: die Rückfrage nennt die Artikelzahl,
    // danach läuft der Commit über dieselbe 5s-Rücknahme wie jede andere Löschung im
    // Modul. Redundant ist das nicht - eine Rückfrage schützt vor dem Fehlgriff, ein
    // Undo vor dem falschen Entschluss, und hier hängen die Artikel eines ganzen
    // Haushalts dran.
    if (action === 'delete-list') {
      const deletedListId = state.activeListId;
      const snapshot = {
        list: state.activeList ? { ...state.activeList } : null,
        listEntry: state.lists.find((l) => l.id === deletedListId),
        items: state.items.map((i) => ({ ...i })),
        index: state.lists.findIndex((l) => l.id === deletedListId),
      };
      // Bei 0 Artikeln eine eigene Fassung: „und 0 Artikel löschen?" ist zwar
      // richtig, liest sich aber wie ein Fehler.
      const confirmed = await confirmModal(
        state.items.length
          ? t('shopping.deleteListConfirm', { name: state.activeList?.name ?? '', count: state.items.length })
          : t('shopping.deleteListConfirmEmpty', { name: state.activeList?.name ?? '' }),
        { danger: true, confirmLabel: t('common.delete'), detail: t('shopping.deleteListConfirmDetail') },
      );
      if (!confirmed) return;

      // Optimistisch aus der Leiste nehmen und auf die Nachbarliste wechseln.
      state.lists = state.lists.filter((l) => l.id !== deletedListId);
      state.activeListId = state.lists[0]?.id ?? null;
      if (state.activeListId) {
        await switchList(state.activeListId, container);
        refocusAfterRender();
      } else {
        clearItems();
        state.activeList = null;
        renderTabs(container);
        renderListContent(container);
        wireListContentEvents(container);
      }

      scheduleUndoableDelete({
        message: t('shopping.deletedListToast'),
        commit: async ({ keepalive }) => {
          await api.delete(`/shopping/${deletedListId}`, { keepalive });
          // Erst wenn das Loeschen wirklich feststeht (Undo-Fenster verstrichen):
          // ein rueckgaengig gemachtes Loeschen soll den Klapp-Zustand behalten.
          try {
            localStorage.removeItem(collapsedCategoriesStorageKey(state.currentUserId, deletedListId));
          } catch { /* Privatmodus/Quota - unschaedlich, die Zeile war ohnehin verwaist */ }
        },
        restore: async (err) => {
          // Der Server hat nichts gelöscht (der Commit war aufgeschoben) - die Liste
          // muss also nur zurück in den State und an ihren alten Platz in der Leiste.
          if (snapshot.listEntry) {
            state.lists.splice(Math.max(0, snapshot.index), 0, snapshot.listEntry);
          }
          state.activeListId = deletedListId;
          state.activeList = snapshot.list;
          state.items = snapshot.items;
          renderTabs(container);
          renderListContent(container);
          wireListContentEvents(container);
          if (err) reportError(err, container, 'common.unknownError');
        },
      });
    }
  });
}

// Hier stand `wireRenameKeydown`: eine Bindung, die „Enter" auf dem Listen-Titel
// in einen Klick übersetzte. Sie war nötig, weil der Titel ein `<span
// role="button" tabindex="0">` war - ein nachgebauter Knopf, dem der Browser
// keine Tastaturbedienung schenkt. Umbenennen ist jetzt ein echter `<button>` im
// Überlaufmenü und braucht dafür keine Zeile JS.

// --------------------------------------------------------
// Kategorie-Verwaltung (kanonischer Ort, früher in Settings)
// --------------------------------------------------------

/**
 * Öffnet den Kategorie-Manager in einem Modal. Reagiert auf
 * `category-manager-changed`, um den lokalen State und die aktive Liste
 * zu aktualisieren. Schließen navigiert zurück nach /shopping (Query entfernen).
 * @param {Element} container Seiten-Container
 * @param {object}  [opts]
 * @param {boolean} [opts.fromDeepLink] true, wenn via ?manage=categories geöffnet
 */
/**
 * Laeden verwalten (#1003) - derselbe Manager wie fuer die Kategorien.
 *
 * Eine eigene Komponente waere die zweite Bauart fuer dieselbe Sache: eine
 * kurze, benannte Liste anlegen, umbenennen, loeschen. Der Manager kann das
 * bereits und braucht nur einen anderen `basePath`; deshalb hat der Server oben
 * ein PUT bekommen, das die Form spricht, die diese Komponente erwartet.
 *
 * Er haengt im Listenmenue und nicht im Artikel-Dialog: das geteilte Modal
 * kennt kein Stacking, ein Manager ueber dem Formular raeumte es weg. Angelegt
 * wird ein Laden deshalb beim Speichern des Artikels (siehe Combobox oben),
 * umbenannt und geloescht hier.
 * @param {Element} container Seiten-Container
 */
function openStoreManager(container) {
  if (readOnly()) return;
  // Die Arbeit haengt am Ereignis, nicht am Schliessen: `confirmOverModal`
  // raeumt beim Loeschen das Modal darunter gleich mit ab, das
  // `category-manager-changed` kommt also erst DANACH. Ein in onClose
  // ausgewerteter Merker stuende hier auf false, und `state.stores` boete
  // weiter einen Laden an, den es nicht mehr gibt - die naechste Speicherung
  // liefe in die 400-Antwort des Servers (gemessen 08.09.).
  const onChanged = async () => {
    await Promise.all([loadStores(), loadItems(state.activeListId)]);
    updateItemsList(container);
  };

  openModal({
    title: t('shopping.manageStores'),
    content: '<yuvomi-category-manager></yuvomi-category-manager>',
    onSave: (panel) => {
      const manager = panel.querySelector('yuvomi-category-manager');
      if (!manager) return;
      manager.addEventListener('category-manager-changed', onChanged);
      manager.configure({
        basePath: '/shopping/stores',
        titleKey: 'shopping.manageStores',
        hintKey: 'shopping.storesHint',
        // Der Standard liest "Neue Kategorie" - in einem Dialog mit dem Titel
        // "Laeden verwalten" waere das derselbe Bruch wie beim Vorrat.
        addPlaceholderKey: 'shopping.addStore',
        // Frage UND Folgentext: der Standard fragte "Kategorie ... loeschen?"
        // in einem Dialog, der "Laeden verwalten" heisst. Der Fremdschluessel
        // steht ausserdem auf SET NULL, nicht auf einer Ersatzzuordnung wie bei
        // den Kategorien dieses Moduls.
        deleteConfirmKey: 'shopping.storeDeleteConfirm',
        deleteDetailKey: 'shopping.storeDeleteConfirmDetail',
        // Nie der Satz des Servers (#1909): bekannter Fall oder der allgemeine.
        errorFallbackKey: 'common.errorGeneric',
      });
    },
    // Bewusst KEIN onClose, das den Listener abmeldet: gemessen kommt das
    // Ereignis des Loeschens erst, wenn das Element schon aus dem Dokument ist
    // (confirmOverModal raeumt das Modal darunter mit ab, api.delete laeuft
    // danach weiter). Wer beim Schliessen abmeldet, verpasst genau die
    // Aenderung, die state.stores veralten laesst - und der Artikel-Dialog boete
    // danach einen Laden an, den der Server nicht mehr kennt (400 beim
    // Speichern). Das Element entsteht je Oeffnen neu und wird mit dem Overlay
    // verworfen; der Listener geht mit ihm.
  });
}

async function openCategoryManager(container, { fromDeepLink = false } = {}) {
  // Regel 7: der Aufrufer versteckt den Ausloeser, die Komponente fragt nicht.
  if (readOnly()) return;
  const { openModal } = await import('/components/modal.js');

  // Die geteilte Komponente (Audit F-15) dispatcht ohne Detail — der lokale
  // State wird nach jeder Mutation frisch vom Server geladen.
  //
  // Und wie beim Laden-Manager oben haengt die Auffrischung am Ereignis, nicht
  // am Schliessen: beim Loeschen raeumt `confirmOverModal` das Modal darunter
  // ab, bevor `api.delete` laeuft. Ein in onClose ausgewerteter `changed`-Merker
  // stuende genau dann auf false, und die sichtbare Liste behielte ihre
  // Gruppierung nach einer Kategorie, die es nicht mehr gibt.
  //
  // Und es reichen NICHT die Kategorien allein. Anders als Aufgaben, Kontakte
  // und Budget, die ueber einen stabilen `key` zeigen, steht die Kategorie im
  // Einkauf als NAME in `shopping_items.category` - der Server schreibt also in
  // die Artikelzeilen: Umbenennen per `UPDATE shopping_items SET category = ?`,
  // Loeschen weist sie der naechsten Kategorie zu. `loadCategories()` fasst
  // `state.items` nicht an, und `groupItemsByCategory` liest den Namen von dort;
  // die Zeilen landeten sonst unter der alten Ueberschrift am Listenende.
  const onCategoriesChanged = async () => {
    // Die Seite kann unter diesem Handler weggezogen sein. Kommt der Manager
    // aus dem Deep-Link `?manage=categories`, navigiert onClose sofort auf
    // /shopping - und weil diese Seite kein `update()` anbietet, baut der Router
    // sie ganz neu auf (`content.replaceChildren(...)` plus frisches
    // `render()`). Beim Loeschen laeuft dieser Handler erst DANACH: `container`
    // waere ein abgehaengter Knoten, und der neue Aufbau hat ohnehin schon
    // frisch geladen. Dieselbe Regel wie bei der Sammelaktions-Pille (#1039).
    if (!container.isConnected) return;
    await loadCategories();
    const listId = state.activeListId;
    if (listId) {
      try {
        await loadItems(listId);
        // Hat der Nutzer waehrenddessen die Liste gewechselt, gehoert das
        // Rendern `switchList` - `loadItems` hat den Stand oben schon
        // unangetastet gelassen.
        if (state.activeListId !== listId) return;
        state.itemsError = null;
      } catch (err) {
        // Ohne dieses catch bliebe eine unbeobachtete Rejection zurueck:
        // `_notifyChanged()` dispatcht synchron und sieht die Promise dieses
        // Listeners nie. Der Server hat die Artikel dann schon umgeschrieben,
        // und die Liste zeigte stillschweigend den alten Stand weiter - hier
        // stattdessen die Fehlerkarte mit Wiederholung, wie bei `switchList`.
        console.error('[Shopping] loadItems Fehler:', err);
        // Auch der Fehlerfall gehoert der Liste, fuer die geladen wurde: sonst
        // leerte ein Fehler der alten Liste die Artikel der neuen.
        if (state.activeListId !== listId) return;
        state.items      = [];
        state.itemsError = err;
      }
    }
    if (state.activeList) {
      renderListContent(container);
      wireListContentEvents(container);
    }
    refocusAfterRender();
  };

  openModal({
    title: t('shopping.manageCategories'),
    content: '<yuvomi-category-manager></yuvomi-category-manager>',
    onSave: (panel) => {
      const manager = panel.querySelector('yuvomi-category-manager');
      if (!manager) return;
      manager.addEventListener('category-manager-changed', onCategoriesChanged);
      manager.configure({
        basePath: '/shopping/categories',
        labelResolver: (item) => categoryLabel(item.name),
        titleKey: 'shopping.manageCategories',
        hintKey: 'settings.shoppingCategoriesHint',
        // Anders als Budget/Tasks/Kontakte loescht der Einkauf auch belegte
        // Kategorien und schiebt die Artikel auf die naechste Kategorie.
        deleteDetailKey: 'shopping.categoryDeleteConfirmDetail',
        // Nie der Satz des Servers (#1909): bekannter Fall oder der allgemeine.
        errorFallbackKey: 'common.errorGeneric',
      });
    },
    // onClose traegt nur noch, was wirklich am Schliessen haengt. Kein
    // Listener-Abmelden: das liefe vor dem Loeschen, und das Element entsteht
    // je Oeffnen neu und geht mit dem Overlay.
    onClose: () => {
      // Deep-Link-Query entfernen, wenn der Manager über die URL geöffnet wurde.
      if (fromDeepLink && new URLSearchParams(window.location.search).has('manage')) {
        window.yuvomi?.navigate?.('/shopping');
      }
    },
  });
}

// --------------------------------------------------------
// Haupt-Render
// --------------------------------------------------------

export async function render(container, { user, signal: routeSignal = null } = {}) {
  state.currentUserId = user?.id ?? null;
  _routeSignal = routeSignal;
  // Ein Seitenaufbau ist immer ein neuer Batch fuer die Sammelaktions-Pille -
  // eine Frist der vorherigen Seite darf diese hier nicht treffen (#1039).
  resetPillMachine();
  // Ebenso die Pause der wartenden Zeilen (#1816): sie faellt mit dem Aufbau
  // und mit dem Verlassen der Seite.
  resetPlacementHold();
  routeSignal?.addEventListener?.('abort', resetPlacementHold, { once: true });
  // VOR dem Laden: die erste Laufnummern-Abfrage laeuft neben dem Laden der
  // Seite. Die Reihenfolge der beiden Antworten ist damit NICHT entschieden -
  // und muss es nicht sein: die Artikel-Antwort traegt ihre Laufnummer, und
  // `loadItems` gibt sie dem Feed als den Stand, den die Seite haelt
  // (`hold`). Eine Aenderung zwischen den beiden Antworten faellt so nicht
  // durch, egal welche zuerst kam. Eine Meldung, die noch in den Aufbau
  // faellt, laedt hoechstens einmal umsonst; die Ladeordnung (`_loadSeq`)
  // haelt die Antworten auseinander.
  wireLiveUpdates(container, routeSignal);
  container.replaceChildren();
  container.insertAdjacentHTML('beforeend', `
    <div class="shopping-page page-measure--narrow">
      <div class="list-tabs-bar" id="list-tabs-bar">
        <div class="skeleton skeleton-line skeleton-line--medium" style="height:36px;width:120px;border-radius:var(--radius-full)"></div>
        <div class="skeleton skeleton-line skeleton-line--short"  style="height:36px;width:80px; border-radius:var(--radius-full)"></div>
      </div>
      <div id="list-content" style="flex:1;display:flex;flex-direction:column">
        <div style="padding:var(--space-6)">
          ${[1,2,3].map(() => `
            <div class="skeleton skeleton-line skeleton-line--full" style="height:48px;margin-bottom:var(--space-2);border-radius:var(--radius-sm)"></div>
          `).join('')}
        </div>
      </div>
    </div>
  `);
  // Die Kuechen-Leiste gehoert in den SYNCHRONEN Teil des Aufbaus: das neue
  // Bild der View Transition wird direkt nach ihm aufgenommen (router.js,
  // swap). Kam sie erst nach den Daten, fehlte sie dort - die Leiste blendete
  // beim Wechsel Mahlzeiten -> Einkauf aus und sprang nach dem Laden zurueck,
  // statt zu stehen wie in den drei Geschwister-Tabs (Integration Runde 3).
  const kitchenBar = renderKitchenTabsBar(container, '/shopping');
  state.itemsError = null;
  try {
    // loadCategories() und loadLists() fangen selbst; der äußere catch ist das
    // Netz für alles Unerwartete und bildet es auf denselben Fehlerzustand ab,
    // statt die Ausnahme in den globalen Fehlerbildschirm laufen zu lassen.
    await Promise.all([loadCategories(), loadStores(), loadLists()]);
    if (!state.listsError && state.lists.length) {
      const listParam = parseInt(new URLSearchParams(window.location.search).get('list'), 10) || null;
      const target = listParam && state.lists.find((l) => l.id === listParam);
      state.activeListId = target ? target.id : state.lists[0].id;
      state.collapsedCategories = loadCollapsedCategories(state.currentUserId, state.activeListId);
      state.tickedOpen = loadTickedOpen(state.currentUserId, state.activeListId);
      try {
        await loadItems(state.activeListId);
      } catch (err) {
        console.error('[Shopping] loadItems Fehler:', err);
        clearItems();
        state.activeList = state.lists.find((l) => l.id === state.activeListId) ?? null;
        state.itemsError = err;
      }
    }
  } catch (err) {
    console.error('[Shopping] Ladefehler:', err);
    state.listsError = err;
  }

  // Alles ausser der Leiste abraeumen: sie bleibt eingehaengt, damit ihre
  // Kapsel weitergleitet und der waagrechte Scrollstand nicht zurueckspringt.
  [...container.children].forEach((child) => { if (child !== kitchenBar) child.remove(); });
  container.insertAdjacentHTML('beforeend', `
    <div class="shopping-page page-measure--narrow">
      <h1 class="sr-only">${t('nav.shopping')}</h1>
      <!-- Die Listenwahl ist zugleich der Titel der Seite: der aktive Chip nennt
           die Liste, sein Nachbar am hinteren Ende traegt ihre Aktionen. Hier
           stand bis 2026-08-11 zusaetzlich ein page-toolbar-Kopf, der denselben
           Namen ein zweites Mal zeigte (Keine-sichtbare-Titelwiederholung-Regel,
           DESIGN.md) und mobil rund 64px kostete: /shopping lag bei 53 %
           Contentflaeche, waehrend /tasks und /budget nach ihrer Kopf-Diaet bei
           62-63 % standen.
           KEINE BACKTICKS IN DIESEM KOMMENTAR: er steht INNERHALB des
           Template-Literals, ein Backtick-Paar schliesst es und macht aus dem
           Rest ein Tagged Template ("TypeError: toolbar is not a function"). -->
      <!-- Seit der Kopfregel mobil (2026-09-26) wieder ein page-toolbar-Kopf,
           aber OHNE Titel: Zeile 2 des Kuechenkopfs. Kontext sind die
           Listen-Kapseln (sie nennen die Liste), am Ende das Werkzeugmenue
           der Liste; am Desktop dockt der Router davor den Primaerknopf an,
           wie in den drei Geschwister-Tabs. Kein --narrow (Re-Critique
           2026-09-27, D3): der Kopf endet an der Kuechen-Leiste, damit die
           Primaeraktion in allen vier Tabs an derselben Stelle steht. -->
      <div class="page-toolbar page-toolbar--in-group shopping-toolbar">
        <div class="page-toolbar__center">
          <div class="list-tabs-bar" id="list-tabs-bar" role="group" aria-label="${t('shopping.listsLabel')}"></div>
        </div>
        <div class="page-toolbar__actions">
          <div class="shopping-tools" id="shopping-tools"></div>
        </div>
      </div>
      <div id="list-content" style="flex:1;display:flex;flex-direction:column;overflow:hidden"></div>
      ${readOnly() ? '' : `<button class="page-fab" id="fab-new-item" aria-label="${t('shopping.addItemLabel')}" data-dock-label="${t('newLabel.shopping')}">
        <i data-lucide="plus" class="icon-xl" aria-hidden="true"></i>
      </button>`}
    </div>
  `);

  renderTabs(container);
  wireTabBar(container);
  renderListContent(container);
  wireListContentEvents(container);

  findPageFab('fab-new-item')?.addEventListener('click', (e) => {
    if (readOnly()) return;
    const input = container.querySelector('#item-name-input');
    if (!input) {
      // Keine Liste aktiv → neue Liste erstellen
      container.querySelector('[data-action="new-list"]')?.click();
      return;
    }

    // Auf Touch ist das Quick-Add eingeklappt: der FAB schaltet es um, statt nur
    // ein sichtbares Feld zu fokussieren (siehe syncQuickAddDisclosure).
    if (e.currentTarget.getAttribute('aria-expanded') === 'true') {
      syncQuickAddDisclosure(container, false);
      return;
    }
    syncQuickAddDisclosure(container, true);

    // FAB = Erstell-Flow (wie Meals/Recipes): die Quick-Add-Fläche sichtbar
    // aktivieren — Scroll + Fokus + kurzer Puls als „hier entsteht das Neue".
    input.scrollIntoView({ behavior: 'smooth', block: 'center' });
    input.focus();
    input.classList.add('quick-add__input--flash');
    input.addEventListener('animationend', () => input.classList.remove('quick-add__input--flash'), { once: true });
  });

  // Deep-Link: ?highlight=<id> scrollt zum Artikel
  const highlightId = parseInt(new URLSearchParams(window.location.search).get('highlight'), 10) || null;
  if (highlightId) revealHighlightedItem(container, highlightId);

  // Deep-Link: ?manage=categories öffnet den Kategorie-Manager sofort. Bei
  // `read` riegelt `openCategoryManager()` selbst ab - ein zweiter Riegel hier
  // waere von aussen nicht zu unterscheiden und damit von keinem Test belegt.
  if (new URLSearchParams(window.location.search).get('manage') === 'categories') {
    openCategoryManager(container, { fromDeepLink: true });
  }
}

/**
 * Fuehrt einen Suchtreffer (`?highlight=<id>`) ins Bild.
 *
 * Ueber die Zeile, nicht ueber den Abhak-Knopf: bei `read` steht dort ein
 * Zeichen ohne `data-action`, und ein Suchtreffer muss trotzdem ankommen.
 *
 * Steht der Treffer in einem zugeklappten Traeger, bleibt er bei [hidden]
 * unsichtbar, obwohl der Selektor ihn findet - ein globaler Suchtreffer darf
 * nie hinter persistiertem Zustand verschwinden. Der Traeger ist eine
 * Kategorie ODER der Abschnitt "Abgehakt" (#1816): ein abgehakter Treffer
 * steht dort, und der ist im Grundzustand zu.
 *
 * DAS AUFKLAPPEN WIRD HIER NICHT ABGEWARTET, SONDERN BEENDET. Es laeuft als
 * Bewegung von Hoehe 0 an, und `scrollIntoView` rechnet sein Ziel im selben
 * Augenblick aus: die Zeile lag dann am Ende des noch geschlossenen Inhalts,
 * das Rollen endete dort, und der Traeger wuchs danach nach unten aus dem
 * Bild - gemessen bei 390 px: der Treffer lag hinter der Navigationsleiste.
 * Beim Ankommen ueber einen Link sieht dem Aufklappen ohnehin niemand zu.
 */
function revealHighlightedItem(container, id) {
  const el = container.querySelector(`.shopping-item[data-item-id="${id}"]`);
  if (!el) return;
  const rowsEl = el.closest('.row-carrier');
  if (rowsEl?.hidden) {
    const group = rowsEl.closest('.list-group');
    const toggleBtn = group?.querySelector('[data-category-toggle]');
    const tickedBtn = group?.querySelector('[data-ticked-toggle]');
    if (toggleBtn) toggleCategoryCollapse(toggleBtn);
    else if (tickedBtn) toggleTickedSection(tickedBtn);
    rowsEl.getAnimations?.().forEach((anim) => anim.finish());
  }
  el.scrollIntoView({ behavior: 'smooth', block: 'center' });
}

