    zustand();
    const { gets, stub } = server();
    stub.patch = async () => { throw err; };

    await mit(stub, () => shopping.toggleShoppingItem(10, 0, nullContainer()));

    assert.equal(toasts.length, 1);
    assert.deepEqual(gets, [], 'die Seite hat nichts nachgeladen');
