test('Zwei Fehler waehrend EINES Laufs bestellen genau einen Folgelauf, keinen parallelen', async () => {
  zustand({ items: [item(), item({ id: 11, name: 'Brot', sort_order: 2 }), item({ id: 12, name: 'Salz', sort_order: 3 })] });
  let offen = 0;
